window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0071", [{"word":"vein","ipa_uk":"/veɪn/","ipa_us":"/veɪn/","definition_zh":"静脉；叶脉；矿脉；（言行的）风格，一丝（气质）","definition_en":"a tube that carries blood back to the heart, or a narrow streak running through a leaf, through rock, or through a person's manner","core_image":"一根青蓝色细管从指尖蜿蜒回到心脏，同时像叶脉、矿脉那样不断分叉","scene":"The nurse found a blue vein on the back of his hand and slid the needle in.","sceneCN":"这里 vein 指「皮下可见的静脉」（第 2 个义项：透过皮肤能看到、可用于进针的青蓝色血管）；句意：护士在他手背上找到一根青色的静脉，把针扎了进去。图中可辨识物件：手背、青蓝色血管、输液针、止血带。","pos":[{"tag":"n.","zh":"静脉；叶脉；（昆虫）翅脉；矿脉；水脉；（言行的）风格，一丝（气质）"},{"tag":"vt.","zh":"使…带有纹理（罕用）"}],"collocations":[{"phrase":"jugular vein","zh":"颈静脉"},{"phrase":"portal vein","zh":"门静脉"},{"phrase":"pulmonary vein","zh":"肺静脉"},{"phrase":"in the same vein","zh":"以同样的风格；顺着同一思路"},{"phrase":"a vein of humour","zh":"一丝幽默"},{"phrase":"gold vein","zh":"金矿脉"}],"forms":[{"label":"复数","form":"veins"},{"label":"形容词（静脉的）","form":"venous（静脉的）"},{"label":"形容词（有纹理的）","form":"veined（有纹理的；有静脉的）"},{"label":"小称名词","form":"venule（小静脉）"},{"label":"动词（罕用）","form":"vein（使成纹理）"}],"derivatives":[{"word":"venous","pos":"adj.","zh":"静脉的；静脉中的"},{"word":"venule","pos":"n.","zh":"小静脉"},{"word":"veined","pos":"adj.","zh":"有纹理的；布满静脉的"},{"word":"intravenous","pos":"adj.","zh":"静脉内的；静脉注射的"},{"word":"venation","pos":"n.","zh":"脉序；（叶、翅的）脉纹分布"}],"senses":[{"no":"01","title":"Blood-return vessel","titleCN":"静脉：把血送回心脏的血管","definition":"a tube in the body that carries blood from the organs and tissues back to the heart","definitionCN":"体内把血液从器官与组织送回心脏的血管","example":"The surgeon tied off the vein to stop the bleeding.","exampleCN":"外科医生结扎了那条静脉来止血。","why":"Latin vena named any narrow channel, and anatomy kept it for the channel that returns blood, the counterpart of the artery that sends it out.","whyCN":"拉丁 vena 泛指各种狭窄的通道，解剖学沿用它来指「把血送回」的那条通道，与向外送血的动脉相对。"},{"no":"02","title":"Blue line under the skin","titleCN":"皮下可见的青筋：透过皮肤能看到的静脉","definition":"a vein that can be seen as a bluish line through the skin and is commonly used for drawing blood or giving a drip","definitionCN":"透过皮肤呈青蓝色、常用于抽血或输液的静脉","example":"The nurse found a blue vein on the back of his hand and slid the needle in.","exampleCN":"护士在他手背上找到一根青色的静脉，把针扎了进去。","why":"Because veins lie close to the surface and carry dark, oxygen-poor blood, they show through the skin as blue lines, and medicine learned to use them as ready access points.","whyCN":"静脉靠近体表、又携带缺氧的暗色血，因此透过皮肤呈现青蓝色；医学便把它们当作现成的进针口。"},{"no":"03","title":"Leaf vein","titleCN":"叶脉：贯穿叶片、输送水分与养分的脉纹","definition":"one of the strands of tissue that run through a leaf and carry water, minerals and sugar","definitionCN":"贯穿叶片、输送水分、矿物质与糖分的条状组织","example":"The leaf's veins form a net that carries water to every edge.","exampleCN":"这片叶子的叶脉构成一张网，把水送到每一个边缘。","why":"The branching lines of a leaf look exactly like the branching vessels of a body, so botany borrowed the same word for them.","whyCN":"叶片上分叉的线条与体内分叉的血管形状相同，植物学便把同一个词借去指叶脉。"},{"no":"04","title":"Ore seam in rock","titleCN":"矿脉：岩层中呈条带状分布的矿物","definition":"a layer or streak of mineral, such as gold or copper, running through surrounding rock","definitionCN":"金、铜等矿物在周围岩石中呈层状或条带状的分布","example":"Miners followed the gold vein deep into the mountain.","exampleCN":"矿工顺着金矿脉一路深入山体。","why":"A seam of ore is a thin channel of one substance inside another, the same geometry as a blood vessel, and the word was extended to mining in the Middle Ages.","whyCN":"矿脉是一种物质在另一种物质内部形成的细窄通道，与血管的几何形状相同，这个词在中世纪被延伸到采矿业。"},{"no":"05","title":"Underground water channel","titleCN":"水脉：地下汇流的细窄水道","definition":"a narrow underground course along which water flows or collects, often sought when digging a well","definitionCN":"地下水流动或聚积的细窄通道，打井时常被寻找","example":"The old well was dug where a water vein ran close to the surface.","exampleCN":"那口老井挖在水脉接近地表的地方。","why":"Water moving through soil also follows a narrow line, a sense Latin vena already carried alongside the blood-vessel one.","whyCN":"水在土中流动同样沿一条窄线，拉丁 vena 在指血管之外本就带有这个义项。"},{"no":"06","title":"Manner or tone","titleCN":"风格、口吻：延续同一种写法或说法","definition":"a particular style or manner of speaking or writing, especially when something continues in the same way","definitionCN":"说话或写作的特定风格，尤指顺着同一种方式继续","example":"She told a few more jokes in the same vein.","exampleCN":"她又讲了几个同一路数的笑话。","why":"A vein runs continuously through a body without breaking, so speech that keeps one tone is imagined as one unbroken line of the same material.","whyCN":"静脉在体内连续不断，于是保持同一基调的言语被想象成一条不中断的同质线条。"},{"no":"07","title":"A streak of a quality","titleCN":"一丝（气质）：性格或作品里隐约的一层","definition":"a small but noticeable amount of a quality, such as sadness or humour, in a person or a work","definitionCN":"一个人或一部作品中隐约可辨的一层气质，如忧伤或幽默","example":"There is a vein of melancholy in his early poems.","exampleCN":"他的早期诗作里有一丝忧郁。","why":"The mining sense supplies the picture: a thin layer of one substance is found inside another, so a thin layer of feeling is found inside a character.","whyCN":"采矿义提供了画面：一种物质以薄层夹在另一种物质里，于是某种情绪也以薄层夹在性格之中。"},{"no":"08","title":"Insect wing vein","titleCN":"翅脉：昆虫翅膀上起支撑作用的脉纹","definition":"one of the stiff ribs that support an insect's wing and carry its hemolymph","definitionCN":"支撑昆虫翅膀并输送血淋巴的坚硬脉纹","example":"Biologists count the veins in a fly's wing to identify the species.","exampleCN":"生物学家数苍蝇翅膀上的翅脉来鉴定物种。","why":"Insect wings repeat the branching-tube pattern, and entomology reused the anatomical word for these ribs in the eighteenth century.","whyCN":"昆虫翅膀重复了分叉管道这一图案，昆虫学在 18 世纪把解剖学的这个词用来指这些脉纹。"}],"etymology":{"intro":{"en":"Vein comes from Latin vena through Old French veine. Latin already used the one word for a blood vessel, a water course and a seam of ore, and English copied all three.","cn":"vein 经古法语 veine 来自拉丁 vena。拉丁语本就用同一个词指血管、水道与矿脉，英语把这三层一并继承了下来。"},"items":[{"era":"LATIN VENA","en":"Latin vena meant a blood vessel, and by extension a channel of water and a seam of metal in the earth; the shared picture is a narrow passage inside a larger body.","cn":"拉丁 vena 指血管，并引申为水道与地层中的金属脉；共同的画面是「较大物体内部的一条窄通道」。"},{"era":"OLD FRENCH VEINE","en":"Old French veine carried the anatomical sense into English around the fourteenth century, at first mainly as a medical term.","cn":"古法语 veine 大约在 14 世纪把解剖义带入英语，起初主要作为医学术语。"},{"era":"MINING AND WATER","en":"By the fifteenth and sixteenth centuries the word was routine in mining and well-digging, where a vein of ore or water was followed like a line on a map.","cn":"到 15、16 世纪，这个词在采矿与打井中已很常用，矿脉或水脉被当作地图上的一条线来追踪。"},{"era":"LEAVES AND WINGS","en":"Naturalists of the seventeenth and eighteenth centuries extended vein to the strands of a leaf and later to the ribs of an insect wing, because the shapes are visibly the same.","cn":"17、18 世纪的博物学家把 vein 延伸到叶脉，后来又用于昆虫翅脉，因为这些形状肉眼可见地相同。"},{"era":"TONE AND TEMPER","en":"The figurative sense 'tone, style, a strain of feeling' appears in the sixteenth century and survives mainly in the fixed phrase in the same vein.","cn":"「口吻、风格、一丝情绪」的比喻义出现于 16 世纪，今天主要存活在「同一口吻」这一固定搭配中。"},{"era":"UNCERTAIN ROOT","en":"Source uncertainty: the deeper origin of Latin vena is unknown, and no Indo-European root is generally accepted for it, so none is reconstructed here.","cn":"来源不确定（词根存疑）：拉丁 vena 的更早来源不明，学界没有公认的印欧词根，此处不作重构。"}]},"similar":{"note":{"en":"The first group holds sound-alikes and close relatives whose spelling or meaning is easily confused; the second holds words for tubes, seams and streaks that overlap with vein.","cn":"第一组是同音或形近、容易混淆的词与近亲；第二组是与 vein 语义重叠的「管道、矿层、条痕」类词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"vain","ipa":"/veɪn/","tag":"same sound, different root","definition":"Means 'too proud' or 'useless'; it comes from Latin vanus 'empty', not from vena.","definitionCN":"意为「自负的」或「徒劳的」，来自拉丁 vanus「空的」，与 vena 无关。"},{"word":"vane","ipa":"/veɪn/","tag":"same sound, different root","definition":"A flat blade that shows wind direction, from an Old English word for a banner; unrelated to the blood vessel.","definitionCN":"指示风向的扁平叶片，来自古英语中表「旗帜」的词，与血管无关。"},{"word":"venous","ipa":"/ˈviːnəs/","tag":"adjective of the same family","definition":"The adjective meaning 'of the veins'; it describes the vessel rather than naming it.","definitionCN":"意为「静脉的」的形容词，描述血管而不命名血管。"},{"word":"venule","ipa":"/ˈviːnjuːl/","tag":"small version","definition":"A very small vein; the diminutive suffix marks it as narrower than a vein.","definitionCN":"指小静脉；小称后缀表明它比 vein 更细。"}]},{"heading":"NEAR MEANING","entries":[{"word":"artery","ipa":"/ˈɑːtəri/","tag":"opposite direction","definition":"A tube that carries blood away from the heart; vein is the return route, so the two are defined by direction.","definitionCN":"把血从心脏送出的血管；vein 是回流路线，两者靠方向区分。"},{"word":"capillary","ipa":"/kəˈpɪləri/","tag":"smallest vessel","definition":"The thinnest blood vessel, where exchange happens; veins collect what capillaries have exchanged.","definitionCN":"最细的血管，物质交换在此发生；静脉收集毛细血管交换后的血液。"},{"word":"lode","ipa":"/ləʊd/","tag":"mining synonym","definition":"A rich seam of ore in rock, the mining sense of vein without the anatomical meaning.","definitionCN":"岩石中富集的矿层，只保留 vein 的采矿义，不含解剖义。"},{"word":"streak","ipa":"/striːk/","tag":"thin line of a quality","definition":"A long thin mark or an element in a character; it overlaps the figurative sense of vein but has no medical use.","definitionCN":"指细长的痕迹或性格中的一种成分，与 vein 的比喻义重叠，但没有医学用法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"English took one Latin word, vena, and kept all three of its senses: vessel, ore seam and water course.","cn":"英语只取了拉丁一个词 vena，却把它指血管、矿脉、水脉的三层意思全都保留下来。"},{"en":"The family runs vein, venous, venule, venation and intravenous on the same stem.","cn":"同族词 vein、venous、venule、venation、intravenous 共用同一个词干。"},{"en":"Fixed phrases mark the anatomy: jugular vein, portal vein, pulmonary vein.","cn":"固定搭配标出解剖位置：颈静脉、门静脉、肺静脉。"},{"en":"in the same vein keeps the picture of one continuous streak of talk.","cn":"「同一口吻」这一搭配保留了「一条连续不断的话语线条」这一画面。"},{"en":"a vein of humour borrows the miner's sense: a thin layer found inside something else.","cn":"「一丝幽默」这一搭配借用了矿工的义项：夹在其他东西里的一薄层。"}],"abstract":[{"en":"Picture an underground river that shows itself only as one blue line under the skin.","cn":"想象一条地下河，只在皮肤下露出一条青蓝色的线。"},{"en":"Picture a leaf held up to a lamp, its veins like a map of small rivers.","cn":"想象一片叶子对着灯举起，叶脉像一张小河的地图。"},{"en":"Picture a miner following a thin gold line through grey rock.","cn":"想象矿工沿灰色岩石中的一条细金线向前走。"}]},"examples":[{"en":"Varicose veins often appear after years of standing at work.","cn":"静脉曲张常常在多年站立工作之后出现。"},{"en":"The rock face was cut by a wide white vein of quartz.","cn":"岩壁被一条宽阔的白色石英矿脉切开。"},{"en":"He answered in a lighter vein than the earlier interview.","cn":"他回答的口吻比先前那次采访轻松。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「vein 与 vain、vane 同音」——同音词要分清：血管是 vein，徒劳是 vain，风向标是 vane → vein 静脉","word":"vein"},"root":"拉丁 vena「血管；矿脉；水道」→ 古法语 veine → 英语 vein；拉丁 vena 更早来源不明。","sensesIntro":{"en":"Eight senses follow one narrow channel: a tube returning blood, the blue line it makes under the skin, the same shape in a leaf, in rock, in water, in a manner of speech, in a streak of character, and in an insect's wing.","cn":"八个义项沿同一条窄通道展开：把血送回心脏的管道、它在皮肤下形成的青蓝线，以及它在叶、岩石、水、说话方式、性格层次和昆虫翅膀上的同形延伸。"},"semanticMap":{"core":{"en":"CORE IMAGE: a narrow channel that branches through a body, a leaf or stone.","cn":"核心意象：一条在身体、叶片或石头中分叉延伸的窄通道。"},"chain":["BLOOD RETURN","VISIBLE UNDER SKIN","LEAF STRAND","ORE SEAM","WATER CHANNEL","STYLE OR STRAIN"],"branches":[{"senses":"S1 · S2","en":"THE TUBE AND ITS BLUE LINE: the anatomical vessel, then the same vessel as it appears through the skin.","cn":"管道与青蓝线：先是解剖学上的血管，再是它透过皮肤显现的样子。"},{"senses":"S3 · S8","en":"NATURAL BRANCHING: leaves and insect wings repeat the same pattern of fine ribs.","cn":"自然分叉：叶片与昆虫翅膀重复了同样的细脉图案。"},{"senses":"S4 · S5","en":"UNDER THE GROUND: ore seams and water courses are followed like lines on a map.","cn":"地面之下：矿脉与水脉被当作地图上的线来追踪。"},{"senses":"S6","en":"ONE CONTINUOUS TONE: talk that keeps one style is imagined as an unbroken vein.","cn":"一条不断的语调：保持同一风格的言说被想象成一条不中断的脉。"},{"senses":"S7","en":"A LAYER INSIDE A PERSON: the mining sense becomes a thin layer of feeling in a character.","cn":"人身上的一层：采矿义转化为性格中薄薄的一层情绪。"}]},"affixes":{"intro":{"en":"Vein is a bare Latin stem, vena, with almost no affixation in English; its relatives grow by suffixes such as -ous, -ule and intra-.","cn":"vein 是裸露的拉丁词干 vena，英语中几乎没有附加词缀；它的同族词靠 -ous、-ule、intra- 等词缀生长。"},"latinIntro":{"en":"Latin vena and its adjective venosus, with the diminutive venula, supply the whole English family, including medical compounds built with intra-.","cn":"拉丁 vena 及其形容词 venosus、小称 venula 提供了整个英语词族，包括用 intra- 构成的医学复合词。"},"items":[{"word":"vein","structure":"vena (bare stem)","meaning":"a blood vessel; a seam","meaningCN":"静脉；矿脉","example":"The needle went into a vein.","exampleCN":"针扎进了一根静脉。"},{"word":"venous","structure":"vena + -osus (full of)","meaning":"of or full of veins","meaningCN":"静脉的；布满静脉的","example":"Venous blood returns to the right side of the heart.","exampleCN":"静脉血回到心脏右侧。"},{"word":"venule","structure":"vena + -ula (diminutive)","meaning":"a small vein","meaningCN":"小静脉","example":"A venule drains into a larger vein.","exampleCN":"小静脉汇入更大的静脉。"},{"word":"venation","structure":"vena + -atio (arrangement)","meaning":"the pattern of veins in a leaf or wing","meaningCN":"叶脉或翅脉的分布格局","example":"The venation of the leaf is net-like.","exampleCN":"这片叶子的脉序呈网状。"},{"word":"veined","structure":"vein + -ed (having)","meaning":"marked with veins","meaningCN":"带静脉纹路的","example":"The marble is heavily veined.","exampleCN":"这块大理石布满纹理。"},{"word":"intravenous","structure":"intra- (within) + venous","meaning":"inside a vein","meaningCN":"静脉内的","example":"The drug was given intravenously.","exampleCN":"药物通过静脉给药。"},{"word":"intravenously","structure":"intravenous + -ly","meaning":"by way of a vein","meaningCN":"经静脉地","example":"Fluids were given intravenously.","exampleCN":"液体经静脉输入。"},{"word":"veinlet","structure":"vein + -let (small)","meaning":"a small vein of a leaf","meaningCN":"细叶脉","example":"Water reaches the edge along tiny veinlets.","exampleCN":"水沿着细小叶脉到达叶缘。"}],"latinEntries":[{"word":"vena","structure":"vena, venae (f., first declension)","meaning":"a blood vessel; a water course; a seam of ore","meaningCN":"血管；水道；矿脉"},{"word":"venosus","structure":"venosus, -a, -um (adjective)","meaning":"full of veins; veined","meaningCN":"布满血管的；有脉纹的"},{"word":"venula","structure":"venula, venulae (f., diminutive of vena)","meaning":"a small vein","meaningCN":"小静脉"}]}},{"word":"venous","ipa_uk":"/ˈviːnəs/","ipa_us":"/ˈviːnəs/","definition_zh":"静脉的；静脉中的；（血）含氧低的；叶脉的（植物学罕用）","definition_en":"relating to the veins, or carried by them, especially blood that has given up its oxygen","core_image":"暗红色的血在薄壁静脉里缓缓流回心脏","scene":"Blood on the venous side of the heart is dark red because it carries little oxygen.","sceneCN":"这里 venous 指「静脉一侧的」（第 1 个义项：与静脉相关、位于静脉系统的）；句意：心脏静脉一侧的血液呈暗红色，因为其中含氧很少。图中可辨识物件：心脏剖面、暗红血流、蓝色箭头、静脉管壁。","pos":[{"tag":"adj.","zh":"静脉的；静脉中的；（血液）含氧低的；叶脉的（植物学罕用）"}],"collocations":[{"phrase":"venous blood","zh":"静脉血"},{"phrase":"venous return","zh":"静脉回流"},{"phrase":"venous pressure","zh":"静脉压"},{"phrase":"venous thrombosis","zh":"静脉血栓形成"},{"phrase":"venous insufficiency","zh":"静脉功能不全"},{"phrase":"venous access","zh":"静脉通路（置管）"}],"forms":[{"label":"名词（静脉）","form":"vein（静脉）"},{"label":"副词","form":"venously（经静脉地，罕用）"},{"label":"比较级","form":"more venous（较少用）"},{"label":"最高级","form":"most venous（较少用）"},{"label":"小称名词","form":"venule（小静脉）"},{"label":"反义相关形容词","form":"arterial（动脉的）"}],"derivatives":[{"word":"vein","pos":"n.","zh":"静脉；矿脉"},{"word":"venule","pos":"n.","zh":"小静脉"},{"word":"venousness","pos":"n.","zh":"静脉性（罕用）"},{"word":"intravenous","pos":"adj.","zh":"静脉内的"},{"word":"arteriovenous","pos":"adj.","zh":"动静脉的"}],"senses":[{"no":"01","title":"Relating to veins","titleCN":"静脉的：属于静脉系统或与静脉有关的","definition":"relating to a vein or to the system of veins in the body","definitionCN":"与静脉或体内静脉系统有关的","example":"Blood on the venous side of the heart is dark red because it carries little oxygen.","exampleCN":"心脏静脉一侧的血液呈暗红色，因为其中含氧很少。","why":"Latin venosus simply meant 'full of veins', and English anatomy narrowed it to 'belonging to the veins' as the adjective paired with arterial.","whyCN":"拉丁 venosus 本义只是「布满血管的」，英语解剖学把它收窄为「属于静脉的」，与 arterial 配对使用。"},{"no":"02","title":"Carried by veins","titleCN":"静脉中的：由静脉运送的（血液）","definition":"describing blood that is being carried by veins rather than by arteries","definitionCN":"描述由静脉而非动脉运送的血液","example":"The venous blood from the legs has to travel a long way back to the heart.","exampleCN":"来自腿部的静脉血要经过很长的路程才能回到心脏。","why":"The adjective marks the route, not the fluid itself: the same blood becomes arterial once it passes the lungs and is sent out again.","whyCN":"这个形容词标记的是路线而不是液体本身：同一份血经过肺之后被送出时就成了动脉血。"},{"no":"03","title":"Dark red in colour","titleCN":"暗红色的：缺氧血呈现的颜色","definition":"of the dark, slightly bluish red colour typical of oxygen-poor blood","definitionCN":"缺氧血典型的暗红偏蓝色调","example":"The wound oozed dark venous blood instead of bright arterial blood.","exampleCN":"伤口渗出的是暗色的静脉血，而不是鲜红的动脉血。","why":"Colour is the visible clue to oxygen content, so surgeons read venous darkness as a sign that the blood has already given up its oxygen.","whyCN":"颜色是含氧量的可见线索，因此外科医生把静脉血的暗色读作「血已交出氧」的标志。"},{"no":"04","title":"Of venous pressure","titleCN":"静脉压的：测量静脉内压力的","definition":"relating to the pressure inside veins, which is much lower than arterial pressure","definitionCN":"与静脉内压力有关，该压力远低于动脉压","example":"The nurse recorded the venous pressure at the central line.","exampleCN":"护士记录了中心静脉导管处的静脉压。","why":"Because veins are thin-walled and far from the pump, pressure there is low and easily changed by posture, so it is measured as its own quantity.","whyCN":"静脉壁薄、离泵血处远，压力低且易受体位影响，因此被当作一个独立的量来测量。"},{"no":"05","title":"Of venous disease","titleCN":"静脉（疾病）的：涉及静脉功能不全或血栓","definition":"describing conditions in which veins fail to return blood properly, such as insufficiency, varicosity or thrombosis","definitionCN":"描述静脉无法正常回流的状态，如功能不全、曲张或血栓形成","example":"Venous ulcers heal slowly because the skin receives poor blood flow.","exampleCN":"静脉性溃疡愈合缓慢，因为皮肤供血很差。","why":"When the return route fails, fluid and pressure build up in the tissue, so a whole group of skin and leg problems is labelled venous.","whyCN":"回流路线失败时，液体与压力在组织中积聚，于是一整组皮肤与腿部问题被标为「静脉性」。"},{"no":"06","title":"Venous return","titleCN":"静脉回流的：血液回到心脏的过程","definition":"relating to the flow of blood back to the heart, a quantity physiologists measure and manipulate","definitionCN":"与血液回到心脏的流动有关，生理学家会测量并调控这一量","example":"Standing still reduces venous return and can cause fainting.","exampleCN":"静止站立会减少静脉回流，可能引起昏厥。","why":"Physiology needed a name for the inflow side of the circulation, and venous return became a standard measure of how much blood the heart has to work with.","whyCN":"生理学需要给循环的流入侧一个名称，静脉回流便成了衡量心脏可处理血量的标准指标。"},{"no":"07","title":"Venous thrombosis","titleCN":"静脉血栓（形成）的","definition":"relating to a clot that forms inside a vein, most often in the deep veins of the leg","definitionCN":"与在静脉内形成的血块有关，最常见于腿部深静脉","example":"Long flights raise the risk of venous thrombosis.","exampleCN":"长时间飞行会增加静脉血栓的风险。","why":"Slow, low-pressure flow is exactly what allows blood to pool and clot, so the adjective attaches naturally to thrombosis.","whyCN":"缓慢低压的血流正是血液淤积并凝结的条件，因此这个形容词天然地与 thrombosis 连用。"},{"no":"08","title":"Veined, in botany","titleCN":"有脉纹的：植物学中的罕用义","definition":"in older botanical writing, describes a leaf or petal marked with veins","definitionCN":"在较早的植物学文献中，描述带脉纹的叶或花瓣","example":"The botanist described the petal as venous along its centre.","exampleCN":"那位植物学家描述这片花瓣中央带有脉纹。","why":"This is the original Latin sense surviving in a technical corner: venosus meant 'full of veins', which is exactly what a marked petal is.","whyCN":"这是拉丁本义在一个技术角落里的存活：venosus 意为「布满脉纹的」，正是一枚带纹花瓣的样子。"}],"etymology":{"intro":{"en":"Venous is Latin venosus 'full of veins', formed from vena, and it reached English through medical writing rather than through everyday French.","cn":"venous 是拉丁 venosus「布满血管的」，由 vena 构成，它经由医学文献而非日常法语进入英语。"},"items":[{"era":"LATIN VENA","en":"Vena named a blood vessel and also a seam or channel; the adjective venosus described anything full of such lines.","cn":"vena 指血管，也指矿脉或水道；形容词 venosus 描述布满这类线条的东西。"},{"era":"LATIN VENOSUS","en":"Classical venosus was broader than the modern word: it could describe a body rich in vessels, a veined stone, or a leaf.","cn":"古典拉丁的 venosus 比现代词义更宽：可形容血管丰富的身体、带纹的石头或叶子。"},{"era":"MEDICAL ENGLISH","en":"English medical texts of the seventeenth century adopted venous to pair with arterial, fixing it to the return side of the circulation.","cn":"17 世纪的英语医学文献采用 venous 与 arterial 配对，把它固定在循环的回流一侧。"},{"era":"PHYSIOLOGY","en":"As circulation was measured, venous became a label for whole quantities, such as venous pressure and venous return, rather than only for a vessel.","cn":"随着循环被量化，venous 成了整类量的标签，如静脉压与静脉回流，而不再只形容一根血管。"},{"era":"CLINICAL USE","en":"Modern medicine attaches the word to diseases of the return route, from insufficiency and varicosity to thrombosis, and keeps the botanical sense only in specialist writing.","cn":"现代医学把这个词用于回流路线的疾病，从功能不全、曲张到血栓，植物学义只保留在专业文献里。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertainty: the exact English date of venous is not firmly fixed (generally placed in the seventeenth century), and the deeper origin of vena remains unknown.","cn":"来源不确定（仅首见年代与更深词根）：venous 的英语确切首见年代无定论（一般认为在 17 世纪），vena 的更早来源仍然不明。"}]},"similar":{"note":{"en":"The first group holds look-alikes that are not about veins at all, plus the parent noun; the second holds the adjectives and vessels that occupy neighbouring territory.","cn":"第一组是形近但根本与静脉无关的词，以及它的母名词；第二组是邻近语义场里的形容词与血管名。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"venous vs. venal","ipa":"/ˈviːnəl/","tag":"one letter, different word","definition":"Venal means 'open to bribery', from Latin venum 'for sale'; venous has nothing to do with selling.","definitionCN":"venal 意为「可收买的」，来自拉丁 venum「出售」；venous 与买卖毫无关系。"},{"word":"vein","ipa":"/veɪn/","tag":"the noun behind the adjective","definition":"The vessel itself; venous is the adjective built from it, as artery stands to arterial.","definitionCN":"指血管本身；venous 是由它构成的形容词，如同 artery 与 arterial 的关系。"},{"word":"venule","ipa":"/ˈviːnjuːl/","tag":"same family, smaller","definition":"A small vein, formed with the diminutive -ule; it is a noun, not an adjective.","definitionCN":"指小静脉，由小称词缀 -ule 构成；它是名词而非形容词。"},{"word":"venation","ipa":"/viːˈneɪʃn/","tag":"same family, different abstraction","definition":"The arrangement of veins in a leaf or wing; it names a pattern, not a property.","definitionCN":"指叶或翅上脉纹的排列；它命名一种格局，而不是一种属性。"}]},{"heading":"NEAR MEANING","entries":[{"word":"arterial","ipa":"/ɑːˈtɪəriəl/","tag":"the paired opposite","definition":"Relating to arteries or to oxygen-rich blood; it is the mirror image of venous in circulation.","definitionCN":"与动脉或富氧血有关；在循环中它是 venous 的镜像对立面。"},{"word":"vascular","ipa":"/ˈvæskjələ/","tag":"the whole system","definition":"Relating to vessels of any kind; vascular covers arteries, veins and capillaries together.","definitionCN":"与任何血管有关；vascular 覆盖动脉、静脉与毛细血管整体。"},{"word":"intravenous","ipa":"/ˌɪntrəˈviːnəs/","tag":"location, not quality","definition":"Means 'inside a vein' and describes where something is placed; venous only says which system is involved.","definitionCN":"意为「静脉内的」，描述放置位置；venous 只说明涉及哪个系统。"},{"word":"venose","ipa":"/ˈviːnəʊs/","tag":"rare botanical doublet","definition":"A rare adjective meaning 'full of veins', closer to the Latin venosus than to the medical venous.","definitionCN":"罕用形容词，意为「布满脉纹的」，比医学用语的 venous 更接近拉丁 venosus。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"vena 'vein' + -osus 'full of' gives 'full of veins', which anatomy narrowed to 'of the veins'.","cn":"vena「静脉」+ -osus「充满」得出「布满静脉的」，解剖学把它收窄为「静脉的」。"},{"en":"venous and arterial are a fixed pair: one marks the return route, the other the outward route.","cn":"venous 与 arterial 是固定的一对：一个标记回流路线，一个标记送出路线。"},{"en":"The family runs vein, venous, venule, venation and intravenous.","cn":"同族词包括 vein、venous、venule、venation、intravenous。"},{"en":"Clinical phrases cluster around failure: venous insufficiency, venous thrombosis, venous ulcer.","cn":"临床搭配都围绕「失败」：静脉功能不全、静脉血栓、静脉性溃疡。"},{"en":"Do not confuse venous with venal; the second belongs to Latin venum 'for sale'.","cn":"不要把 venous 与 venal 混同；后者属于拉丁 venum「出售」。"}],"abstract":[{"en":"Picture a slow dark river with no pump of its own, pushed uphill by muscle alone.","cn":"想象一条缓慢的暗色河流，自身没有水泵，只能靠肌肉推着往上走。"},{"en":"Picture two colour-coded pipes, blue for the return, red for the outward trip.","cn":"想象两根用颜色标记的管子，蓝色走回流，红色走出程。"},{"en":"Picture a thin-walled bag that bulges when the flow behind it slows.","cn":"想象一只薄壁的口袋，在它后面的水流变慢时鼓起来。"}]},"examples":[{"en":"Venous blood is darker because it has already delivered its oxygen.","cn":"静脉血颜色更深，因为它已经把氧输送出去了。"},{"en":"Doctors measured venous pressure to judge how much fluid to give.","cn":"医生测量静脉压来判断该补多少液体。"},{"en":"The venous system of the leg relies on valves to keep blood moving upward.","cn":"腿部的静脉系统依靠瓣膜让血液向上流动。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「vein 静脉 + ous …的」——属于静脉的 → venous 静脉的（小心别写成 venal 可收买的）","word":"venous"},"root":"拉丁 vena「血管；矿脉」→ 拉丁 venosus「布满血管的」→ 英语 venous（17 世纪医学用语）。","sensesIntro":{"en":"Eight senses radiate from one adjective: it labels the vessel, the blood inside it, that blood's dark colour, the pressure, the diseases of the return route, the return flow itself, clots, and finally a veined petal in old botany.","cn":"八个义项从一个形容词辐射开来：它标记血管、其中的血、血的暗色、压力、回流路线的疾病、回流量、血栓，最后还有旧植物学中带脉纹的花瓣。"},"semanticMap":{"core":{"en":"CORE IMAGE: dark blood moving slowly back toward the heart in thin-walled tubes.","cn":"核心意象：暗色的血在薄壁管中缓慢流回心脏。"},"chain":["VEIN SYSTEM","ITS BLOOD","ITS DARK COLOUR","ITS LOW PRESSURE","ITS FAILURES","ITS FLOW BACK"],"branches":[{"senses":"S1 · S2","en":"THE ROUTE: the adjective names the system and the blood travelling in it.","cn":"路线：这个形容词既命名系统，也命名在其中的血。"},{"senses":"S3","en":"THE COLOUR: oxygen loss is visible as darkness, so colour becomes a diagnostic sign.","cn":"颜色：失氧表现为暗色，于是颜色成了诊断信号。"},{"senses":"S4 · S6","en":"TWO NUMBERS: pressure on the venous side and the volume returning to the heart are measured together.","cn":"两个数字：静脉侧压力与回到心脏的血量总被一起测量。"},{"senses":"S5 · S7","en":"WHEN THE RETURN FAILS: insufficiency, ulcers and clots all belong to the same slow-flow problem.","cn":"回流失败时：功能不全、溃疡与血栓都属于同一个慢流问题。"},{"senses":"S8","en":"THE OLD SENSE SURVIVES: the Latin 'full of veins' remains in botanical description.","cn":"旧义残留：拉丁「布满脉纹」仍留在植物学描述中。"}]},"affixes":{"intro":{"en":"Venous is a Latin adjective in -osus, 'full of', added to vena; the suffix is the same one that gives curious and dangerous their shape.","cn":"venous 是拉丁形容词，由 vena 加 -osus「充满」构成；同一个后缀也造就了 curious、dangerous 这类词的形态。"},"latinIntro":{"en":"Vena, venosus and the diminutive venula form a compact Latin family; English added prefixes such as intra- and arterio- to build clinical terms.","cn":"vena、venosus 与小称 venula 构成一个紧凑的拉丁词族；英语再加上 intra-、arterio- 等前缀来造临床术语。"},"items":[{"word":"venous","structure":"vena + -osus (full of)","meaning":"of or full of veins","meaningCN":"静脉的；布满静脉的","example":"Venous blood returns to the heart.","exampleCN":"静脉血回到心脏。"},{"word":"vein","structure":"vena (bare stem)","meaning":"a blood vessel","meaningCN":"静脉","example":"A blue vein showed on his arm.","exampleCN":"他手臂上露出一根青色的静脉。"},{"word":"venule","structure":"vena + -ula (diminutive)","meaning":"a small vein","meaningCN":"小静脉","example":"Blood leaves the capillary into a venule.","exampleCN":"血液从毛细血管进入小静脉。"},{"word":"venation","structure":"vena + -atio (arrangement)","meaning":"the vein pattern of a leaf","meaningCN":"叶脉的分布","example":"Its venation is parallel.","exampleCN":"它的脉序是平行的。"},{"word":"venousness","structure":"venous + -ness (quality)","meaning":"the quality of being venous","meaningCN":"静脉性","example":"The specimen's venousness was noted in the report.","exampleCN":"报告中注明了标本的静脉性。"},{"word":"intravenous","structure":"intra- (within) + venous","meaning":"situated or given inside a vein","meaningCN":"位于或注入静脉内的","example":"An intravenous line was placed in her arm.","exampleCN":"她手臂上置了一根静脉导管。"},{"word":"arteriovenous","structure":"arterio- (artery) + venous","meaning":"linking an artery and a vein","meaningCN":"连接动脉与静脉的","example":"A fistula creates an arteriovenous connection.","exampleCN":"瘘管形成了动静脉之间的连接。"},{"word":"venose","structure":"vena + -osus, retained in botany","meaning":"covered with veins","meaningCN":"布满脉纹的","example":"The venose leaf is typical of the genus.","exampleCN":"布满脉纹的叶子是该属的典型特征。"}],"latinEntries":[{"word":"vena","structure":"vena, venae (f., first declension)","meaning":"a blood vessel; a seam; a channel","meaningCN":"血管；矿脉；水道"},{"word":"venosus","structure":"venosus, -a, -um (adjective)","meaning":"full of veins","meaningCN":"布满血管或脉纹的"},{"word":"venula","structure":"venula, venulae (f., diminutive)","meaning":"a small vein","meaningCN":"小静脉"}]}},{"word":"capillary","ipa_uk":"/kəˈpɪləri/","ipa_us":"/ˈkæpəleri/","definition_zh":"毛细血管；毛细管；毛细现象的；细如毛发的","definition_en":"the thinnest blood vessel, or a very narrow tube through which liquid rises by surface forces","core_image":"一根细到只容一个红血球通过的管子，液体却沿着它自动上升","scene":"A red blood cell squeezes through a capillary only one cell wide.","sceneCN":"这里 capillary 指「毛细血管」（第 1 个义项：直径极小、只容一个血细胞通过的血管）；句意：一个红细胞挤过一根只有它一个细胞宽的毛细血管。图中可辨识物件：毛细血管剖面、红细胞、内皮细胞、血流方向箭头。","pos":[{"tag":"n.","zh":"毛细血管；（物理）毛细管"},{"tag":"adj.","zh":"毛细的；毛细作用的；细如毛发的"}],"collocations":[{"phrase":"capillary vessel","zh":"毛细血管"},{"phrase":"capillary bed","zh":"毛细血管床"},{"phrase":"capillary action","zh":"毛细作用"},{"phrase":"capillary tube","zh":"毛细管"},{"phrase":"capillary wall","zh":"毛细血管壁"},{"phrase":"capillary permeability","zh":"毛细血管通透性"}],"forms":[{"label":"复数","form":"capillaries"},{"label":"形容词","form":"capillary（毛细的；毛管的）"},{"label":"名词（毛细现象）","form":"capillarity（毛细现象）"},{"label":"形容词（毛细的）","form":"capillar（毛细的，罕用）"},{"label":"复合词","form":"capillary leak（毛细血管渗漏）"}],"derivatives":[{"word":"capillarity","pos":"n.","zh":"毛细现象；毛细作用"},{"word":"capillaritis","pos":"n.","zh":"毛细血管炎"},{"word":"capillaroscopy","pos":"n.","zh":"甲襞毛细血管镜检"},{"word":"capillary","pos":"adj.","zh":"毛细的；毛细血管的"},{"word":"pericapillary","pos":"adj.","zh":"毛细血管周围的"}],"senses":[{"no":"01","title":"Smallest blood vessel","titleCN":"毛细血管：最细的血管，物质交换在此进行","definition":"the smallest blood vessel, thin enough for oxygen and nutrients to pass between blood and tissue","definitionCN":"最细的血管，其管壁薄到足以让氧与养分在血液与组织之间通过","example":"A red blood cell squeezes through a capillary only one cell wide.","exampleCN":"一个红细胞挤过一根只有它一个细胞宽的毛细血管。","why":"Hair and a blood vessel look alike in one respect only: both are extremely thin, so Latin capillaris 'of hair' was borrowed for the finest vessels.","whyCN":"头发与血管只有一点相似：都极细，因此拉丁 capillaris「毛发的」被借来指最细的血管。"},{"no":"02","title":"Capillary bed","titleCN":"毛细血管床：一片交织成网的微血管","definition":"a dense network of capillaries in an organ, where gas, nutrients and waste are exchanged","definitionCN":"器官内密集交织的毛细血管网，气体、养分与废物在此交换","example":"The capillary bed of the lung covers a huge surface in a small space.","exampleCN":"肺的毛细血管床在很小的空间里铺开巨大的表面。","why":"One capillary exchanges almost nothing; a whole woven bed is what an organ needs, so the singular word is used collectively for the network.","whyCN":"单根毛细血管几乎完不成交换；器官需要的是一整片交织的床，于是这个单数名词被集合地用来指整张网。"},{"no":"03","title":"Narrow lab tube","titleCN":"毛细管：实验室与仪器中的细玻璃管","definition":"a very narrow tube used in laboratories, thermometers and instruments to hold or move small amounts of liquid","definitionCN":"实验室、温度计与仪器中盛放或移动少量液体的极细管子","example":"A few drops of serum were drawn up into a glass capillary.","exampleCN":"几滴血清被吸进一根玻璃毛细管。","why":"Glass tubing narrow enough to be called hair-like behaves differently from ordinary tubing, so the adjective became a name for the object itself.","whyCN":"细到可称「如发」的玻璃管表现得与普通管不同，于是这个形容词变成了这种物件本身的名称。"},{"no":"04","title":"Capillary action","titleCN":"毛细作用：液体在细窄空隙中自行上升","definition":"the rise or movement of a liquid in narrow spaces caused by adhesion and surface tension, without pressure from outside","definitionCN":"液体在细窄空间中因附着与表面张力而自行上升或移动，无需外部压力","example":"Capillary action pulls water up through the soil toward dry roots.","exampleCN":"毛细作用把水通过土壤向上拉到干燥的根部。","why":"In a narrow tube the liquid clings to the walls and the surface curves, and that curve pulls liquid upward; the effect is named after the tube that shows it.","whyCN":"在细管中液体贴附管壁、液面弯曲，而弯曲的液面又把液体往上拉；这一效应以展示它的管子命名。"},{"no":"05","title":"Capillary water in soil","titleCN":"土壤毛细水：保存在细小孔隙中的水","definition":"water held in the small pores of soil and able to move upward through them toward plant roots","definitionCN":"保存在土壤细小孔隙中、能沿孔隙向上移动到植物根部的水","example":"Capillary water keeps the topsoil moist for weeks after rain.","exampleCN":"雨后毛细水能让表土保持湿润数周。","why":"Soil is a mass of tiny tubes, so the same physics that lifts water in glass lifts it in earth, and agronomy borrowed the word.","whyCN":"土壤就是无数细管的集合，抬升玻璃管中水的同一套物理也抬升土中的水，农学便借用了这个词。"},{"no":"06","title":"Capillary wave","titleCN":"毛细波：表面张力主导的细小波纹","definition":"a tiny ripple on a liquid surface whose restoring force is surface tension rather than gravity","definitionCN":"液面上由表面张力而非重力主导的细微波纹","example":"Wind first raises capillary waves, which grow into larger ripples.","exampleCN":"风先掀起毛细波，再长成更大的涟漪。","why":"The smallest waves are ruled by the same surface force as narrow tubes, so oceanography applied the word to a wavelength regime rather than to a vessel.","whyCN":"最小的波与细管受同一种表面力支配，于是海洋学把这个词用到一个波长区段，而不是一件器物。"},{"no":"07","title":"Capillary permeability","titleCN":"毛细血管通透性：管壁漏出液体与细胞的能力","definition":"the property of capillary walls that allows fluid, proteins or cells to leak into surrounding tissue","definitionCN":"毛细血管壁让液体、蛋白质或细胞漏入周围组织的性质","example":"Inflammation increases capillary permeability and causes swelling.","exampleCN":"炎症会提高毛细血管通透性，引起肿胀。","why":"Because the wall is only one cell thick, its leakiness is a variable that disease can raise or drugs can lower, so it needed a name.","whyCN":"由于管壁只有一层细胞厚，它的渗漏程度是疾病可升高、药物可降低的变量，因此需要一个名称。"},{"no":"08","title":"Hair-like, slender","titleCN":"细如毛发的：本义中的「毛发状」","definition":"literally 'hair-like', a rare descriptive use of the adjective in older technical writing","definitionCN":"字面「如毛发般的」，是较早技术文献中罕见的描述用法","example":"The old text speaks of a capillary fracture, meaning a hair-thin crack.","exampleCN":"旧文献提到 capillary fracture，指的是细如发丝的裂缝。","why":"This is the literal Latin sense before anatomy took the word over: capillus is a hair, and anything thread-thin could be called capillary.","whyCN":"这是解剖学占用这个词之前的拉丁本义：capillus 是头发，任何细如线的东西都可以叫 capillary。"}],"etymology":{"intro":{"en":"Capillary is Latin capillaris 'of hair', from capillus 'hair'. It entered English as a description of hair-thin structures and was then fixed to the finest blood vessels.","cn":"capillary 是拉丁 capillaris「毛发的」，来自 capillus「头发」。它先以「细如毛发之物」进入英语，随后被固定到最细的血管上。"},"items":[{"era":"LATIN CAPILLUS","en":"Capillus meant the hair of the head. It is usually explained as a compound of caput 'head' and pilus 'hair', but that formation is a reconstruction and not a recorded derivation.","cn":"capillus 指头上的毛发。通常把它解释为 caput「头」与 pilus「毛发」的复合，但这一构成属重构，并非有记录的派生过程。"},{"era":"LATIN CAPILLARIS","en":"The adjective capillaris meant 'of hair, hair-like' and could describe anything as fine as a thread, from roots to cracks in stone.","cn":"形容词 capillaris 意为「毛发的、如毛发的」，可形容任何细如线的东西，从根须到石上的裂缝。"},{"era":"ANATOMY 17C","en":"After the fine vessels were seen under the microscope in the seventeenth century, capillary was applied to them because their bore is about the width of a hair.","cn":"17 世纪人们在显微镜下看到这些细血管后，capillary 被用于它们，因为其管径约只有一根头发那么宽。"},{"era":"PHYSICS 19C","en":"Studies of liquids in narrow tubes gave the noun and adjective a second life in physics: capillary action, capillary tube, and later capillarity as the name of the effect.","cn":"对细管中液体的研究让这个词在物理学中获得第二次生命：毛细作用、毛细管，后来还有 capillarity 这一效应名称。"},{"era":"MODERN RANGE","en":"Twentieth-century science extended it to soil water, surface ripples and wall leakiness, while medicine kept the anatomical sense as the dominant one.","cn":"20 世纪的科学把它延伸到土壤水、表面波纹与管壁渗漏，医学则让解剖义保持主导。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertainty: the caput plus pilus explanation of capillus is not proven, and the precise first English date of capillary is not firmly fixed, though it is seventeenth-century.","cn":"来源不确定（词根构成存疑，仅首见年代存疑）：capillus 等于 caput 加 pilus 的解释未获确证；capillary 的英语确切首见年代无定论，但可定在 17 世纪。"}]},"similar":{"note":{"en":"The first group holds look-alikes that share the hair idea or a similar shape; the second holds vessels and narrow-tube words that neighbour capillary in meaning.","cn":"第一组是共享「毛发」意象或形状相近的词；第二组是在语义上与 capillary 相邻的血管名与细管词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"capillus","ipa":"/kəˈpɪləs/","tag":"Latin source, not English","definition":"The Latin noun for hair, cited in etymology but not used as an English word.","definitionCN":"拉丁语中表「头发」的名词，只出现在词源说明里，不作英语词使用。"},{"word":"capillarity","ipa":"/ˌkæpɪˈlærəti/","tag":"the phenomenon, not the tube","definition":"The name of the effect by which liquid rises in narrow spaces; capillary is the tube or vessel that shows it.","definitionCN":"指液体在细窄空间上升这一效应的名称；capillary 是显示该效应的管子或血管。"},{"word":"capillaceous","ipa":"/ˌkæpɪˈleɪʃəs/","tag":"rare adjective of hair","definition":"A rare adjective meaning 'hair-like', used in botany for fine hairs; it keeps the literal Latin sense.","definitionCN":"罕用形容词，意为「如毛的」，植物学中用于细毛，保留拉丁本义。"},{"word":"capital","ipa":"/ˈkæpɪtl/","tag":"same caput, different branch","definition":"From Latin caput 'head' but through capitalis 'of the head'; the shared element is caput, not capillus.","definitionCN":"来自拉丁 caput「头」，但经由 capitalis「头的」；共享成分是 caput，而非 capillus。"}]},{"heading":"NEAR MEANING","entries":[{"word":"arteriole","ipa":"/ɑːˈtɪəriəʊl/","tag":"the other small vessel","definition":"The smallest artery, feeding a capillary bed; it is on the arterial side of the exchange.","definitionCN":"最小的动脉，为毛细血管床供血，位于交换的动脉一侧。"},{"word":"venule","ipa":"/ˈviːnjuːl/","tag":"the other small vessel","definition":"The smallest vein, collecting blood from capillaries; the mirror of the arteriole.","definitionCN":"最小的静脉，从毛细血管收集血液，与微动脉相对。"},{"word":"sinusoid","ipa":"/ˈsaɪnəsɔɪd/","tag":"a wider exchange vessel","definition":"A wider, leakier exchange vessel found in the liver and spleen, not a true capillary but doing similar work.","definitionCN":"肝与脾中更宽、更易渗漏的交换血管，并非真正的毛细血管，但承担类似功能。"},{"word":"microvessel","ipa":"/ˈmaɪkrəʊvesl/","tag":"collective term","definition":"Any very small vessel, including capillaries, arterioles and venules as one group.","definitionCN":"任何极小的血管，把毛细血管、微动脉与微静脉作为一个整体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"capillus 'hair' + -aris 'relating to' gives 'hair-like', the literal picture of the finest vessel.","cn":"capillus「头发」+ -aris「与…有关」得出「如毛的」，正是最细血管的字面画面。"},{"en":"The family runs capillary, capillaries, capillarity, capillaceous and the clinical compound capillaroscopy.","cn":"同族词包括 capillary、capillaries、capillarity、capillaceous 以及临床复合词 capillaroscopy。"},{"en":"Fixed phrases split into anatomy and physics: capillary bed versus capillary action.","cn":"固定搭配分成解剖与物理两路：毛细血管床 对 毛细作用。"},{"en":"capillary is a noun and an adjective; only the noun has the plural capillaries.","cn":"capillary 既是名词又是形容词；只有名词才有复数 capillaries。"},{"en":"The exchange trio runs arteriole, capillary, venule in that order.","cn":"交换三联按顺序是微动脉、毛细血管、微静脉。"}],"abstract":[{"en":"Picture a tunnel so narrow that a single red cell has to flatten itself to pass.","cn":"想象一条窄到红细胞必须压扁身体才能通过的隧道。"},{"en":"Picture water climbing a glass tube without any pump, only the pull of the walls.","cn":"想象水在没有泵的情况下沿玻璃管上爬，只靠管壁的拉力。"},{"en":"Picture a leaf's fine hairs and a body's fine vessels as two drawings of the same line.","cn":"想象叶上的细毛与体内的细血管，是同一根线的两幅画。"}]},"examples":[{"en":"Oxygen diffuses across the capillary wall into the muscle.","cn":"氧穿过毛细血管壁扩散进肌肉。"},{"en":"In dry soil, capillary action can move water upward from below.","cn":"在干燥土壤中，毛细作用能把水从下方往上移动。"},{"en":"The laboratory used a capillary tube to collect the sample.","cn":"实验室用一根毛细管收集样本。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「capill 毛发 + ary 的」——细得像头发丝的管子 → capillary 毛细血管／毛细管","word":"capillary"},"root":"拉丁 capillus「头发」→ 拉丁 capillaris「毛发的；如毛的」→ 英语 capillary，17 世纪起固定指最细的血管。","sensesIntro":{"en":"Eight senses follow one hair-thin bore: the finest vessel, the bed it forms, the lab tube with the same bore, the force that lifts liquid inside it, soil water, tiny surface waves, the leakiness of its wall, and the literal 'hair-like' sense.","cn":"八个义项沿一条如发丝般的管径展开：最细的血管、它构成的血管床、同样细的实验室管、在管内抬升液体的力、土壤水、表面细波、管壁的渗漏，以及字面的「如毛发」义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tube no wider than a hair, one red cell passing through it.","cn":"核心意象：一根不比头发宽的管子，一个红细胞正从中通过。"},"chain":["FINEST VESSEL","WOVEN BED","NARROW TUBE","LIQUID RISING","SOIL WATER","TINY SURFACE WAVE"],"branches":[{"senses":"S1 · S2","en":"BODY: one vessel and the network it forms inside an organ.","cn":"身体：一根血管与它在器官内构成的网。"},{"senses":"S3 · S4","en":"GLASS AND FORCE: the same bore in the laboratory, and the surface force that lifts liquid in it.","cn":"玻璃与力：实验室中同样的管径，以及在管内抬升液体的表面力。"},{"senses":"S5","en":"EARTH: soil pores act as countless small tubes for water.","cn":"大地：土壤孔隙充当无数根输水的小管。"},{"senses":"S6","en":"WATER SURFACE: the smallest ripples are ruled by the same surface force.","cn":"水面：最小的波纹受同一种表面力支配。"},{"senses":"S7 · S8","en":"THE WALL AND THE WORD ITSELF: leakiness is a property of the wall, and 'hair-like' is the literal sense underneath everything.","cn":"管壁与词本身：渗漏是管壁的属性，而「如毛发」是底下那层字面义。"}]},"affixes":{"intro":{"en":"Capillary is capill- 'hair' plus -ary 'relating to'; the same stem with -ity gives capillarity, the name of the physical effect.","cn":"capillary 是 capill-「毛发」加 -ary「与…有关的」；同一词干加 -ity 得到 capillarity，即该物理效应的名称。"},"latinIntro":{"en":"Latin capillus and its adjective capillaris supply the family; the Greek-derived prefix peri- extends it to 'around the capillary' in clinical use.","cn":"拉丁 capillus 及其形容词 capillaris 提供整个词族；希腊来源的前缀 peri- 在临床用语中把它扩展到「毛细血管周围」。"},"items":[{"word":"capillary","structure":"capill- (hair) + -ary (relating to)","meaning":"hair-like; the finest vessel","meaningCN":"如毛的；最细的血管","example":"The capillary carries one cell at a time.","exampleCN":"这根毛细血管一次只通过一个细胞。"},{"word":"capillaries","structure":"capillary + -ies (plural)","meaning":"the fine vessels, plural","meaningCN":"毛细血管（复数）","example":"The drug widens the capillaries near the skin.","exampleCN":"这种药使皮肤附近的毛细血管扩张。"},{"word":"capillarity","structure":"capill- + -ity (state)","meaning":"the rise of liquid in narrow spaces","meaningCN":"液体在细窄空间上升的性质","example":"Capillarity keeps the wick wet.","exampleCN":"毛细作用使灯芯保持湿润。"},{"word":"capillaceous","structure":"capill- + -aceous (resembling)","meaning":"hair-like, in botany","meaningCN":"植物学中「如毛的」","example":"Capillaceous hairs cover the stem.","exampleCN":"茎上覆盖着如毛的细毛。"},{"word":"capillaritis","structure":"capillary + -itis (inflammation)","meaning":"inflammation of the capillaries","meaningCN":"毛细血管炎","example":"Capillaritis leaves brown marks on the skin.","exampleCN":"毛细血管炎会在皮肤上留下褐色斑。"},{"word":"capillaroscopy","structure":"capillaro- + -scopy (examination)","meaning":"microscopic examination of capillaries","meaningCN":"毛细血管的显微镜检查","example":"Capillaroscopy shows the nail-fold vessels.","exampleCN":"甲襞毛细血管镜检可显示甲襞血管。"},{"word":"pericapillary","structure":"peri- (around) + capillary","meaning":"around a capillary","meaningCN":"毛细血管周围的","example":"Fluid gathered in the pericapillary space.","exampleCN":"液体聚集在毛细血管周围间隙。"},{"word":"capillary leak","structure":"capillary + leak","meaning":"escape of fluid from capillaries","meaningCN":"毛细血管渗漏","example":"Capillary leak causes a sudden drop in blood pressure.","exampleCN":"毛细血管渗漏会造成血压骤降。"}],"latinEntries":[{"word":"capillus","structure":"capillus, capilli (m., second declension)","meaning":"hair, especially of the head","meaningCN":"毛发，尤指头上的头发"},{"word":"capillaris","structure":"capillaris, -is, -e (adjective)","meaning":"of hair; hair-like","meaningCN":"毛发的；如毛的"},{"word":"capillamentum","structure":"capillus + -mentum (noun of means)","meaning":"a head of hair; a filament","meaningCN":"头发；细丝状物"}]}},{"word":"hemoglobin","ipa_uk":"/ˌhiːməˈɡləʊbɪn/","ipa_us":"/ˈhiːməɡloʊbɪn/","definition_zh":"血红蛋白；血红素蛋白（旧译「血色素」）","definition_en":"the iron-containing protein in red blood cells that binds oxygen in the lungs and releases it in the tissues","core_image":"四个铁原子嵌在红色的蛋白球里，各自抓住一个氧分子","scene":"Hemoglobin in the red cells picks up oxygen as the blood passes through the lungs.","sceneCN":"这里 hemoglobin 指「血红蛋白」（第 1 个义项：红细胞内结合并运输氧的含铁蛋白）；句意：血液经过肺时，红细胞里的血红蛋白把氧结合上来。图中可辨识物件：红细胞、肺毛细血管、氧分子、含铁血红素环。","pos":[{"tag":"n.","zh":"血红蛋白（红细胞内运输氧的含铁蛋白）；血红素蛋白"}],"collocations":[{"phrase":"hemoglobin level","zh":"血红蛋白水平"},{"phrase":"hemoglobin concentration","zh":"血红蛋白浓度"},{"phrase":"oxygenated hemoglobin","zh":"氧合血红蛋白"},{"phrase":"glycated hemoglobin","zh":"糖化血红蛋白"},{"phrase":"hemoglobin A","zh":"血红蛋白 A（成人主要类型）"},{"phrase":"hemoglobin synthesis","zh":"血红蛋白合成"}],"forms":[{"label":"复数（罕用）","form":"hemoglobins"},{"label":"形容词","form":"hemoglobinic（血红蛋白的，罕用）"},{"label":"美式拼写变体","form":"hemoglobin（美式常用）"},{"label":"英式拼写变体","form":"haemoglobin（英式常用）"},{"label":"相关名词（血红素）","form":"heme（血红素，美式）"},{"label":"相关名词（球蛋白）","form":"globin（珠蛋白）"}],"derivatives":[{"word":"heme","pos":"n.","zh":"血红素（含铁卟啉环）"},{"word":"globin","pos":"n.","zh":"珠蛋白"},{"word":"hemoglobinopathy","pos":"n.","zh":"血红蛋白病"},{"word":"hemoglobinuria","pos":"n.","zh":"血红蛋白尿"},{"word":"hemoglobinometer","pos":"n.","zh":"血红蛋白计"}],"senses":[{"no":"01","title":"Oxygen carrier","titleCN":"血红蛋白：红细胞内运氧的含铁蛋白","definition":"the iron-containing protein inside red blood cells that binds oxygen and carries it from the lungs to the tissues","definitionCN":"红细胞内含铁、能结合氧并把氧从肺运到组织的蛋白质","example":"Hemoglobin in the red cells picks up oxygen as the blood passes through the lungs.","exampleCN":"血液经过肺时，红细胞里的血红蛋白把氧结合上来。","why":"The name says exactly what the molecule is: a heme group plus a globin protein. The heme holds the iron, and iron is what grips the oxygen.","whyCN":"这个名字把分子构成说得一清二楚：一个血红素加一个珠蛋白。血红素装着铁，而抓住氧的正是铁。"},{"no":"02","title":"Haemoglobin count in blood","titleCN":"血红蛋白（指标）：化验单上的浓度数值","definition":"the measured concentration of this protein in blood, reported as grams per litre or decilitre and used to judge anaemia","definitionCN":"血液中该蛋白的测定浓度，以克每升或每分升报告，用于判断贫血","example":"Her hemoglobin was 9 grams per decilitre, well below normal.","exampleCN":"她的血红蛋白是每分升 9 克，明显低于正常值。","why":"Because the protein carries almost all the blood's oxygen, its concentration is a compact measure of how much oxygen the blood can deliver, so the number stands for the function.","whyCN":"由于血中几乎全部氧都由这个蛋白携带，它的浓度就是血液送氧能力的浓缩指标，于是数值本身代表了功能。"},{"no":"03","title":"Oxygenated form","titleCN":"氧合血红蛋白：已经装上氧的形态","definition":"the form of the protein that has bound oxygen, which makes arterial blood look bright red","definitionCN":"已经结合氧的蛋白形态，使动脉血呈鲜红色","example":"Oxygenated hemoglobin reflects red light, which is why arterial blood looks bright.","exampleCN":"氧合血红蛋白反射红光，所以动脉血看起来鲜亮。","why":"Binding oxygen changes the shape of the iron complex slightly, and that change alters which wavelengths it absorbs, so the same molecule has two visible colours.","whyCN":"结合氧会轻微改变铁络合物的形状，进而改变它吸收的波长，因此同一个分子有两种可见颜色。"},{"no":"04","title":"Glycated hemoglobin","titleCN":"糖化血红蛋白：长期血糖的化验指标","definition":"hemoglobin to which glucose has attached, used to estimate average blood sugar over the previous months","definitionCN":"已与葡萄糖结合的血红蛋白，用于估计过去数月的平均血糖","example":"Doctors check glycated hemoglobin every three months in diabetes care.","exampleCN":"糖尿病管理中医生每三个月查一次糖化血红蛋白。","why":"Red cells live about four months, so sugar stuck to their hemoglobin records the average glucose of that whole period rather than a single moment.","whyCN":"红细胞约存活四个月，因此粘在血红蛋白上的糖记录的是整段时间的平均血糖，而非某一瞬间。"},{"no":"05","title":"Fetal hemoglobin","titleCN":"胎儿血红蛋白：更易夺取氧的变体","definition":"a variant form produced before birth that binds oxygen more tightly than the adult form","definitionCN":"出生前产生的变体，比成人型更牢固地结合氧","example":"Fetal hemoglobin lets the unborn baby take oxygen from its mother's blood.","exampleCN":"胎儿血红蛋白让胎儿能从母体的血液中取得氧。","why":"The fetus must pull oxygen across the placenta from blood that already holds it, so its hemoglobin is built to grip oxygen harder than the adult type.","whyCN":"胎儿必须从已经带着氧的血液里把氧穿过胎盘夺过来，因此它的血红蛋白被造得更牢固地抓住氧。"},{"no":"06","title":"Abnormal variant","titleCN":"异常血红蛋白：结构变异导致的疾病","definition":"a structurally altered form of the protein produced by a mutation, often causing disease such as sickle cell anaemia","definitionCN":"由突变产生的结构变异型，常引起镰状细胞贫血等疾病","example":"A single amino acid change makes the abnormal hemoglobin clump together.","exampleCN":"一个氨基酸的改变就让这种异常血红蛋白聚集成团。","why":"One letter of the gene changes one bead of the protein chain, and if that bead sits on the surface, molecules stick to each other instead of carrying oxygen quietly.","whyCN":"基因中一个字母的改变换掉蛋白链上的一颗珠子，若这颗珠子位于表面，分子就会互相粘住，而不是安静地运氧。"},{"no":"07","title":"Free hemoglobin in plasma","titleCN":"游离血红蛋白：跑出红细胞后的状态","definition":"hemoglobin released into the plasma when red cells break apart, normally cleared by the body","definitionCN":"红细胞破裂后释放进血浆的血红蛋白，通常由身体清除","example":"Massive hemolysis leaves free hemoglobin in the plasma and turns the urine dark.","exampleCN":"大量溶血会让血浆中出现游离血红蛋白，并使尿液变暗。","why":"The protein is built to work inside a cell; outside it, it splits into dimers that the kidneys try to filter, which is why its presence is a sign of cell damage.","whyCN":"这个蛋白本是为在细胞内工作而造；到了细胞外它会拆成二聚体，肾脏试图把它滤掉，因此它的出现是细胞受损的标志。"},{"no":"08","title":"Textbook protein","titleCN":"教科书式的蛋白：研究结构与功能的范本","definition":"in teaching and research, the standard example used to explain protein structure, allostery and cooperativity","definitionCN":"教学与研究中解释蛋白结构、变构与协同效应的标准范例","example":"Every biochemistry course begins with hemoglobin as the model of cooperativity.","exampleCN":"每门生物化学课都以血红蛋白作为协同效应的模型开篇。","why":"It is abundant, easy to obtain, and its oxygen binding changes shape in a way students can follow, so the molecule became the teaching standard rather than merely a substance.","whyCN":"它含量高、易获取，且结合氧时形状的变化学生能跟得上，于是这个分子成了教学标准，而不仅是一种物质。"}],"etymology":{"intro":{"en":"Hemoglobin is a hybrid coined in nineteenth-century chemistry: Greek haima 'blood' plus globin, the protein part named from Latin globus 'ball'. The spelling differs between American hemoglobin and British haemoglobin.","cn":"hemoglobin 是 19 世纪化学造出的混合词：希腊 haima「血」加 globin，后者因蛋白呈球状而取自拉丁 globus「球」。美式拼 hemoglobin，英式拼 haemoglobin。"},"items":[{"era":"GREEK HAIMA","en":"Greek haima meant blood, and the combining form haimato- supplied a whole series of medical terms about blood.","cn":"希腊 haima 意为血，组合形式 haimato- 派生出一整批与血有关的医学术语。"},{"era":"LATIN GLOBUS","en":"Latin globus meant a ball or sphere. Chemists of the nineteenth century used globulin for proteins that coagulate into round masses, and globin for the protein part of this pigment.","cn":"拉丁 globus 意为球。19 世纪化学家用 globulin 指能凝成圆团的蛋白，用 globin 指这种色素中的蛋白部分。"},{"era":"GERMAN COINAGE","en":"The compound was formed in German as Hämoglobin in the mid-nineteenth century, when the red substance of blood was shown to be a protein carrying an iron pigment.","cn":"这个复合词于 19 世纪中期在德语中形成，作 Hämoglobin，当时人们证明了血液中的红色物质是一种携带铁色素的蛋白质。"},{"era":"ENGLISH ADOPTION","en":"English took the word as hemoglobin in the later nineteenth century; British usage kept the ae spelling haemoglobin to mark the Greek source.","cn":"英语于 19 世纪后期以 hemoglobin 引入；英式用法保留 ae 拼写 haemoglobin 以标记希腊来源。"},{"era":"MOLECULAR ERA","en":"In the twentieth century the molecule became the first protein whose structure was solved by X-ray crystallography, which fixed it as the standard example of protein function.","cn":"20 世纪它成为第一批由 X 射线晶体学解出结构的蛋白，从而被固定为蛋白功能的标准范例。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertainty: the first exact date of the German and English forms is not firmly fixed, and the date usually given, the 1860s, is an approximation rather than a documented first citation.","cn":"来源不确定（仅首见年代存疑）：德语与英语形式的确切首见年代无定论，通常所说的 1860 年代只是约数，并非有文献确证的首条书证。"}]},"similar":{"note":{"en":"The first group holds the component words and look-alikes built from the same pieces; the second holds the blood proteins and pigments that are often confused with hemoglobin.","cn":"第一组是构成它的成分词与用同样部件造的形近词；第二组是常与血红蛋白混淆的血蛋白与色素。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"globin","ipa":"/ˈɡləʊbɪn/","tag":"one half of the word","definition":"The protein chain alone, without the iron-containing heme; hemoglobin is heme plus globin.","definitionCN":"只有蛋白链、不含铁血红素的部分；血红蛋白等于血红素加珠蛋白。"},{"word":"globulin","ipa":"/ˈɡlɒbjəlɪn/","tag":"same ball image, other proteins","definition":"A class of globe-shaped blood proteins such as antibodies; it is not the oxygen carrier.","definitionCN":"一类球状血蛋白，如抗体；它不是运氧蛋白。"},{"word":"heme","ipa":"/hiːm/","tag":"the iron-bearing ring","definition":"The iron-containing porphyrin ring that binds oxygen; the pigment without its protein wrapper.","definitionCN":"结合氧的含铁卟啉环，即去掉蛋白外壳的色素部分。"},{"word":"haemoglobin","ipa":"/ˌhiːməˈɡləʊbɪn/","tag":"British spelling","definition":"The British spelling with ae; the pronunciation and meaning are identical to the American form.","definitionCN":"带 ae 的英式拼写，读音与词义与美式完全相同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"myoglobin","ipa":"/ˌmaɪəˈɡləʊbɪn/","tag":"one heme, not four","definition":"The oxygen-storing protein of muscle; it holds a single heme and stores oxygen locally instead of transporting it.","definitionCN":"肌肉中的储氧蛋白，只含一个血红素，就地储存氧而非运输氧。"},{"word":"hemocyanin","ipa":"/ˌhiːməˈsaɪənɪn/","tag":"copper instead of iron","definition":"The oxygen-carrying protein of many molluscs and crustaceans, built on copper and blue when oxygenated.","definitionCN":"许多软体与甲壳动物的运氧蛋白，以铜为核心，结合氧后呈蓝色。"},{"word":"erythrocyte","ipa":"/ɪˈrɪθrəsaɪt/","tag":"the cell, not the protein","definition":"A red blood cell, the container in which hemoglobin is packed.","definitionCN":"红细胞，即装载血红蛋白的容器。"},{"word":"hematocrit","ipa":"/ˈhiːməkrɪt/","tag":"the proportion, not the protein","definition":"The percentage of blood volume occupied by red cells; it measures the cells, while hemoglobin measures the pigment inside them.","definitionCN":"红细胞占血容量的百分比；它测的是细胞，血红蛋白测的是细胞内的色素。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"haemo- 'blood' + globin 'ball-shaped protein' gives 'the blood's ball protein'.","cn":"haemo-「血」+ globin「球状蛋白」得出「血中的球状蛋白」。"},{"en":"The family runs heme, globin, globulin, hemoglobinopathy and hemoglobinuria.","cn":"同族词包括 heme、globin、globulin、hemoglobinopathy、hemoglobinuria。"},{"en":"Fixed phrases mark the lab: hemoglobin level, glycated hemoglobin, oxygenated hemoglobin.","cn":"固定搭配标出化验场景：血红蛋白水平、糖化血红蛋白、氧合血红蛋白。"},{"en":"Four hemes per molecule, one iron in each, one oxygen held by each iron.","cn":"每个分子有四个血红素，每个血红素含一个铁，每个铁抓住一个氧。"},{"en":"British writes haemoglobin, American writes hemoglobin; the ae is only a spelling marker.","cn":"英式写 haemoglobin，美式写 hemoglobin；ae 只是拼写标记。"}],"abstract":[{"en":"Picture four small iron hooks inside a red ball, each lifting one oxygen parcel.","cn":"想象一个红色球体里有四个小铁钩，每个钩起一个氧包裹。"},{"en":"Picture a colour that flips from dark to bright the moment the cargo is loaded.","cn":"想象一种颜色，在货物装上的那一刻由暗转亮。"},{"en":"Picture a four-month diary written in sugar on the surface of a red cell.","cn":"想象一本写在红细胞表面的四个月糖日记。"}]},"examples":[{"en":"Low hemoglobin is the first sign the doctor looks for in anaemia.","cn":"血红蛋白偏低是医生诊断贫血时最先寻找的迹象。"},{"en":"Sickle cell disease is caused by one altered hemoglobin molecule.","cn":"镰状细胞病由一个改变了的血红蛋白分子引起。"},{"en":"The laboratory measured glycated hemoglobin to assess long-term glucose control.","cn":"实验室测定糖化血红蛋白以评估长期血糖控制情况。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「hemo 血 + globin 球状蛋白」——血里装着铁的球状蛋白 → hemoglobin 血红蛋白","word":"hemoglobin"},"root":"希腊 haima「血」→ 组合形式 haemo-「血」+ 拉丁 globus「球」→ globin「珠蛋白」→ 德语 Hämoglobin → 英语 hemoglobin。","sensesIntro":{"en":"Eight senses follow one iron-bearing ball: the molecule that carries oxygen, the number that stands for its function, its oxygenated and glycated forms, its fetal and mutant variants, the free form outside the cell, and its role as the textbook protein.","cn":"八个义项沿一个含铁球体展开：运氧的分子、代表其功能的数值、氧合型与糖化型、胎儿型与突变型、细胞外的游离型，以及它作为教科书范例的角色。"},"semanticMap":{"core":{"en":"CORE IMAGE: four iron hooks inside a red protein ball, each holding one oxygen molecule.","cn":"核心意象：红色蛋白球里的四个铁钩，每个钩住一个氧分子。"},"chain":["OXYGEN CARRIER","MEASURED LEVEL","LOADED WITH OXYGEN","GLYCATED FORM","FETAL VARIANT","FREE IN PLASMA"],"branches":[{"senses":"S1 · S2","en":"MOLECULE AND NUMBER: what the protein does, and the lab value that reports how well it does it.","cn":"分子与数字：蛋白做什么，以及报告它做得如何的化验值。"},{"senses":"S3 · S4","en":"TWO CHEMICAL MARKS: oxygen changes its colour, glucose leaves a record of time.","cn":"两种化学标记：氧改变它的颜色，葡萄糖留下时间的记录。"},{"senses":"S5 · S6","en":"BUILT DIFFERENTLY: the fetal form grips oxygen harder, the mutant form sticks to itself.","cn":"造得不同：胎儿型更紧地抓氧，突变型则互相粘连。"},{"senses":"S7","en":"OUT OF PLACE: free in the plasma, the protein signals that cells have broken.","cn":"不在原位：游离在血浆中时，这个蛋白提示细胞已经破裂。"},{"senses":"S8","en":"THE MODEL: abundance and clear behaviour made it the standard teaching protein.","cn":"作为范例：含量高、行为清晰，使它成为标准教学蛋白。"}]},"affixes":{"intro":{"en":"Hemoglobin joins a Greek combining form for blood to a protein name built on Latin globus; its relatives attach -pathy, -uria and -meter to the same stem.","cn":"hemoglobin 把希腊语「血」的组合形式与基于拉丁 globus 的蛋白名连在一起；同族词用 -pathy、-uria、-meter 接在同一词干上。"},"latinIntro":{"en":"The Greek element haima supplies heme, hemorrhage and hemophilia; the Latin element globus supplies globin, globulin and globe.","cn":"希腊成分 haima 提供了 heme、hemorrhage、hemophilia；拉丁成分 globus 提供了 globin、globulin、globe。"},"items":[{"word":"hemoglobin","structure":"haemo- (blood) + globin (ball protein)","meaning":"the oxygen-carrying blood protein","meaningCN":"运氧的血蛋白","example":"Hemoglobin gives red cells their colour.","exampleCN":"血红蛋白赋予红细胞颜色。"},{"word":"heme","structure":"Greek haima (blood)","meaning":"the iron-containing pigment ring","meaningCN":"含铁色素环","example":"Each heme holds one iron atom.","exampleCN":"每个血红素含一个铁原子。"},{"word":"globin","structure":"Latin globus (ball) + -in (protein)","meaning":"the protein chain of hemoglobin","meaningCN":"血红蛋白的蛋白链","example":"Globin wraps around the heme.","exampleCN":"珠蛋白包裹着血红素。"},{"word":"globulin","structure":"globus + -ulin (protein class)","meaning":"a globe-shaped serum protein","meaningCN":"一类球状血清蛋白","example":"Antibodies belong to the globulins.","exampleCN":"抗体属于球蛋白类。"},{"word":"hemoglobinopathy","structure":"hemoglobin + -pathy (disease)","meaning":"a disease of hemoglobin","meaningCN":"血红蛋白病","example":"Thalassaemia is a common hemoglobinopathy.","exampleCN":"地中海贫血是一种常见的血红蛋白病。"},{"word":"hemoglobinuria","structure":"hemoglobin + -uria (urine condition)","meaning":"hemoglobin in the urine","meaningCN":"血红蛋白尿","example":"Hemoglobinuria followed the transfusion reaction.","exampleCN":"输血反应之后出现了血红蛋白尿。"},{"word":"hemoglobinometer","structure":"hemoglobin + -meter (measuring device)","meaning":"an instrument for measuring hemoglobin","meaningCN":"血红蛋白测定仪","example":"The hemoglobinometer gave a reading of 12.","exampleCN":"血红蛋白计读数为 12。"},{"word":"myoglobin","structure":"myo- (muscle) + globin","meaning":"the oxygen-storing protein of muscle","meaningCN":"肌肉中的储氧蛋白","example":"Myoglobin keeps muscle supplied between beats.","exampleCN":"肌红蛋白在两次收缩之间为肌肉供氧。"}],"latinEntries":[{"word":"globus","structure":"globus, globi (m., second declension)","meaning":"a ball, a sphere, a round mass","meaningCN":"球；球体；圆团"},{"word":"globulus","structure":"globulus, globuli (m., diminutive of globus)","meaning":"a small ball","meaningCN":"小球"},{"word":"haema","structure":"Greek haima, haimatos (neuter, third declension)","meaning":"blood","meaningCN":"血（希腊语，非拉丁语，此处列作构词来源）"}]}},{"word":"immunity","ipa_uk":"/ɪˈmjuːnəti/","ipa_us":"/ɪˈmjuːnəti/","definition_zh":"免疫力；豁免（权）；免除；（对批评等的）不受影响","definition_en":"the body's ability to resist a disease, or a legal freedom from a duty, a charge or a penalty","core_image":"一道门把要闯进来的东西挡在外面，同时一张纸写着「免于追究」","scene":"Vaccination gives children immunity to measles before they ever meet the virus.","sceneCN":"这里 immunity 指「免疫力」（第 1 个义项：身体对特定病原体产生的抵抗能力）；句意：接种让儿童在遇到麻疹病毒之前就获得了对它的免疫力。图中可辨识物件：疫苗注射器、抗体、病毒颗粒、防护屏障示意。","pos":[{"tag":"n.","zh":"免疫力；（法律）豁免权；免除（义务、费用、处罚）；（对批评、影响的）不受影响"}],"collocations":[{"phrase":"acquired immunity","zh":"获得性免疫"},{"phrase":"innate immunity","zh":"先天免疫"},{"phrase":"herd immunity","zh":"群体免疫"},{"phrase":"diplomatic immunity","zh":"外交豁免权"},{"phrase":"immunity from prosecution","zh":"免于起诉"},{"phrase":"build up immunity","zh":"建立免疫力"}],"forms":[{"label":"复数","form":"immunities"},{"label":"形容词（免疫的）","form":"immune（免疫的；豁免的）"},{"label":"动词（使免疫）","form":"immunize（使免疫；接种）"},{"label":"名词（接种）","form":"immunization（免疫接种）"},{"label":"动词（使免除）","form":"immunify（使免除，罕用）"},{"label":"副词","form":"immunely（免疫地，罕用）"}],"derivatives":[{"word":"immune","pos":"adj.","zh":"免疫的；不受影响的；豁免的"},{"word":"immunize","pos":"v.","zh":"使免疫；给…接种"},{"word":"immunization","pos":"n.","zh":"免疫接种"},{"word":"immunology","pos":"n.","zh":"免疫学"},{"word":"immunodeficiency","pos":"n.","zh":"免疫缺陷"}],"senses":[{"no":"01","title":"Biological resistance","titleCN":"免疫力：身体抵抗特定病原体的能力","definition":"the ability of the body to resist a particular infection or toxin, usually because it has met the agent before or been vaccinated","definitionCN":"身体抵抗特定感染或毒素的能力，通常因曾接触该病原或已接种而产生","example":"Vaccination gives children immunity to measles before they ever meet the virus.","exampleCN":"接种让儿童在遇到麻疹病毒之前就获得了对它的免疫力。","why":"The biological sense is a metaphor from law: the body is treated as a citizen granted exemption from a disease's demands.","whyCN":"生物学义是从法律借来的比喻：身体被当作一个公民，被授予「免于该病索取」的豁免。"},{"no":"02","title":"Legal exemption","titleCN":"豁免：法律上免于某项义务或处罚","definition":"a legal freedom from a duty, a tax, a charge or a penalty that others are subject to","definitionCN":"法律上免于他人须承担的义务、税负、费用或处罚","example":"The treaty grants immunity from taxation to embassy staff.","exampleCN":"条约给予使馆人员免税的豁免。","why":"This is the oldest sense: Latin immunitas named a grant that freed a person or a town from public burdens, and English law kept it.","whyCN":"这是最古老的义项：拉丁 immunitas 指免除个人或城镇公共负担的授予，英国法把它保留了下来。"},{"no":"03","title":"Diplomatic immunity","titleCN":"外交豁免权：外交人员免受当地司法管辖","definition":"the protection that keeps diplomatic staff from being prosecuted or sued in the country where they serve","definitionCN":"使外交人员在驻在国免受起诉或诉讼的保护","example":"He claimed diplomatic immunity after the traffic accident.","exampleCN":"交通事故后他主张外交豁免权。","why":"Envoys cannot do their work if the host state can arrest them, so a narrow legal exemption was made permanent by treaty and given its own name.","whyCN":"若驻在国能逮捕使节，使节便无法履职，于是这项狭窄的法律豁免通过条约被永久化，并有了专名。"},{"no":"04","title":"Immunity from prosecution","titleCN":"免于起诉：以作证换取不起诉","definition":"a formal promise that a witness's testimony cannot be used to prosecute that witness","definitionCN":"正式承诺证人所作证词不能用于起诉该证人","example":"The witness was offered immunity in exchange for testifying.","exampleCN":"该证人以获得免于起诉为条件出庭作证。","why":"Courts need testimony more than they need this one conviction, so the state trades a legal exemption for information.","whyCN":"法院需要证词甚于需要这一桩定罪，于是国家用一项法律豁免来换取信息。"},{"no":"05","title":"Herd immunity","titleCN":"群体免疫：足够多人免疫后间接保护他人","definition":"the indirect protection that reaches unvaccinated people when a large enough share of the population is immune","definitionCN":"当足够比例的人群免疫时，未接种者获得的间接保护","example":"Herd immunity protects newborns who are too young for the vaccine.","exampleCN":"群体免疫保护那些太小、还不能接种的新生儿。","why":"A germ needs a chain of susceptible hosts to keep spreading; when most links in the chain are immune, the chain breaks and even the unprotected are safer.","whyCN":"病原需要一串易感宿主才能持续传播；当链上多数环节免疫时，链条就断了，连未受保护者也更安全。"},{"no":"06","title":"Innate versus acquired","titleCN":"先天免疫与获得性免疫的分野","definition":"either the fast, non-specific defence present from birth or the slower, specific defence learned after exposure","definitionCN":"或指出生即有的快速非特异性防御，或指接触后学到的较慢特异性防御","example":"Innate immunity stops most germs within hours, long before acquired immunity is ready.","exampleCN":"先天免疫在数小时内就挡住大多数病原，远早于获得性免疫就绪。","why":"Medicine split one word into two mechanisms because they differ in speed and memory, and both are described as exemption from disease.","whyCN":"医学把这一个词分成两种机制，因为它们在速度与记忆上不同，而两者都被描述为「免于疾病」。"},{"no":"07","title":"Freedom from a burden","titleCN":"免除负担：不必承担某种费用或责任","definition":"a formal relief from a payment or obligation, as in immunity from rent, fees or service","definitionCN":"对某项付款或义务的正式免除，如免租、免费、免服役","example":"The old charter gave the town immunity from tolls.","exampleCN":"旧特许状给予该镇免缴通行费的权利。","why":"Immunitas in Latin meant 'not performing public service', and the concrete burdens it lifted, money and labour, were the original content of the word.","whyCN":"拉丁 immunitas 意为「不服公共劳役」，它所解除的具体负担——钱与劳役——才是这个词最初的内容。"},{"no":"08","title":"Not affected by criticism","titleCN":"不受影响：对批评、压力等无动于衷","definition":"the state of being unaffected by criticism, persuasion or pressure, often used ironically","definitionCN":"不受批评、劝说或压力影响的状态，常带反讽意味","example":"His immunity to criticism made the interviews difficult.","exampleCN":"他对批评刀枪不入，这让采访很难进行。","why":"The legal image is reused for the mind: a person is pictured as shielded from the demands that words make, as if criticism were a charge in court.","whyCN":"法律意象被挪用到心理层面：人被描绘成对言语的索取有屏障，仿佛批评是法庭上的一项指控。"}],"etymology":{"intro":{"en":"Immunity is Latin immunitas, from immunis 'free from public service', built on in- 'not' plus munus 'duty, service'. The medical sense is a later borrowing of the legal one.","cn":"immunity 来自拉丁 immunitas，源于 immunis「免于公共劳役」，由 in-「不」加 munus「义务、公务」构成。医学义是对法律义的后来借用。"},"items":[{"era":"LATIN MUNUS","en":"Munus meant a duty, a service, an office, and also a gift or a public show; the underlying idea is something owed or performed for others.","cn":"munus 指义务、公务、职位，也指礼物或公演；底层概念是「为他人所欠或所做的事」。"},{"era":"LATIN IMMUNIS","en":"Immunis meant 'not performing a duty, free from a burden', and was applied to persons and to towns exempted from taxes or garrison duty.","cn":"immunis 意为「不服义务、免于负担」，用于被免除税负或驻防义务的个人与城镇。"},{"era":"LEGAL IMMUNITAS","en":"Immunitas named the privilege itself: the exemption from public charges and services granted by a ruler or by law.","cn":"immunitas 指这种特权本身：由统治者或法律授予的、免于公共负担与劳役的豁免。"},{"era":"ENGLISH LAW","en":"English took immunity in the fifteenth century as a legal term for exemption from service, tax or penalty, and the phrase immunity from prosecution grew from it.","cn":"英语于 15 世纪引入 immunity，作为免服劳役、免税、免罚的法律术语，「免于起诉」这一说法由此生长出来。"},{"era":"MEDICAL SHIFT","en":"In the late nineteenth century, as germs were identified, physicians borrowed the legal word for the body's exemption from a disease, and immunity became mainly medical.","cn":"19 世纪后期病原被识别后，医生借用了这个法律词来指身体「免于某病」，immunity 从此主要以医学义通行。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertainty: an older explanation linking immunis to munire 'to fortify' is repeated in some references but is not generally accepted; the munus explanation is the standard one. The exact first English date is also not firmly fixed.","cn":"来源不确定（词根解释存疑，仅首见年代存疑）：部分资料把 immunis 与 munire「筑防」联系起来，但这不被普遍接受；学界标准解释是 munus。英语确切首见年代亦无定论。"}]},"similar":{"note":{"en":"The first group holds look-alikes and same-family words that differ in part of speech or scope; the second holds legal and medical terms that overlap with immunity.","cn":"第一组是形近词与同族词，区别在词性或范围；第二组是与 immunity 语义重叠的法律与医学术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"immune","ipa":"/ɪˈmjuːn/","tag":"adjective, not noun","definition":"The adjective meaning 'protected or exempt'; it describes a person or state, while immunity names the state itself.","definitionCN":"意为「有免疫力的、被豁免的」形容词；它描述人或状态，immunity 则是该状态本身的名词。"},{"word":"immunize","ipa":"/ˈɪmjunaɪz/","tag":"the verb that produces it","definition":"To make someone immune, usually by vaccine; it names the action, not the resulting condition.","definitionCN":"使人获得免疫，通常通过疫苗；它命名动作，而非结果状态。"},{"word":"immunology","ipa":"/ˌɪmjəˈnɒlədʒi/","tag":"the field, not the state","definition":"The science that studies immune responses; it is a discipline, not a personal protection.","definitionCN":"研究免疫反应的学科，是一门学问，而非个人所受的保护。"},{"word":"munificent","ipa":"/mjuːˈnɪfɪsnt/","tag":"same Latin root, opposite direction","definition":"From munus 'gift' plus -ficus 'making': generous. It shares the root but not the sense of exemption.","definitionCN":"来自 munus「礼物」加 -ficus「造成」，意为「慷慨的」；共享词根，但没有豁免义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"exemption","ipa":"/ɪɡˈzempʃn/","tag":"legal near-synonym","definition":"A formal release from a duty others must perform; it is the everyday legal word where immunity is the privileged one.","definitionCN":"免于他人须履行的义务的正式解除；它是日常法律用词，immunity 则更带特权色彩。"},{"word":"resistance","ipa":"/rɪˈzɪstəns/","tag":"biological near-synonym","definition":"The capacity to withstand an infection or a drug; resistance can be partial and need not involve an immune response.","definitionCN":"抵抗感染或药物的能力；抗性可以是部分的，且不必涉及免疫反应。"},{"word":"tolerance","ipa":"/ˈtɒlərəns/","tag":"immune, but not protective","definition":"In immunology, the failure to attack a particular antigen, including the body's own tissue; it is not the same as defence.","definitionCN":"免疫学中指不对特定抗原发动攻击，包括自身组织；它与防御不是同一件事。"},{"word":"privilege","ipa":"/ˈprɪvəlɪdʒ/","tag":"general legal term","definition":"A special right granted to a person or group; immunity is one kind of privilege, specific to obligations and liability.","definitionCN":"授予个人或群体的特殊权利；immunity 是特权的一种，专指针对义务与责任。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"in- 'not' + munus 'duty' gives immunis 'not performing duty', hence 'exempt'.","cn":"in-「不」+ munus「义务」得出 immunis「不服义务」，进而表示「被豁免的」。"},{"en":"The family runs immune, immunity, immunize, immunization, immunology and immunodeficiency.","cn":"同族词包括 immune、immunity、immunize、immunization、immunology、immunodeficiency。"},{"en":"Legal phrases and medical phrases use the same word: diplomatic immunity beside herd immunity.","cn":"法律搭配与医学搭配共用同一个词：外交豁免权 与 群体免疫 并列。"},{"en":"Latin munus also gives municipal, munificent and common; the same root, other directions.","cn":"拉丁 munus 还衍生出 municipal、munificent、common；同根，方向不同。"},{"en":"immunity is the noun; immune is the adjective; do not write 'immunity from' as a verb.","cn":"immunity 是名词，immune 是形容词；不要把 immunity 当动词用。"}],"abstract":[{"en":"Picture a gate that lets the body's own traffic through but stops every foreign cart.","cn":"想象一道门，放行身体自己的车流，却拦下每一辆外来车。"},{"en":"Picture a stamped paper that says 'this person owes nothing'.","cn":"想象一张盖了章的文件，上面写着「此人无欠」。"},{"en":"Picture a chain of people where most links cannot catch the germ, so the germ cannot walk along it.","cn":"想象一串人，多数环节都抓不住病原，于是病原无法沿链走下去。"}]},"examples":[{"en":"Immunity after infection may fade faster than immunity after vaccination.","cn":"感染后获得的免疫力可能比接种后获得的消退得更快。"},{"en":"The court ruled that his parliamentary immunity did not cover the charge.","cn":"法院裁定他的议会豁免权不覆盖这项指控。"},{"en":"Years of practice gave her a curious immunity to stage fright.","cn":"多年练习让她对怯场产生了一种奇怪的免疫力。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「immune 免疫的 + ity 名词」——被免除、被挡住的状态 → immunity 免疫力／豁免权","word":"immunity"},"root":"拉丁 munus「义务；公务」→ in-「不」+ munus → immunis「免于公共劳役的」→ 拉丁 immunitas → 英语 immunity（15 世纪法律义，19 世纪起医学义为主）。","sensesIntro":{"en":"Eight senses follow one grant of exemption: the body exempted from a disease, the citizen exempted from a tax or a suit, the envoy exempted from local law, the witness exempted from prosecution, the herd that shields others, the two mechanisms of defence, relief from a concrete burden, and a mind shielded from criticism.","cn":"八个义项沿同一份「豁免」展开：身体免于某病、公民免于税负或诉讼、使节免于当地司法、证人免于起诉、群体为他人挡住传播、两种防御机制、具体负担的解除，以及心灵对批评的屏障。"},"semanticMap":{"core":{"en":"CORE IMAGE: a door that keeps something out, and a stamped paper that says 'not liable'.","cn":"核心意象：一扇把某物挡在外的门，以及一张写着「不予追究」的盖章文件。"},"chain":["RESIST DISEASE","LEGAL EXEMPTION","DIPLOMATIC SHIELD","NO PROSECUTION","HERD PROTECTION","UNTOUCHED BY WORDS"],"branches":[{"senses":"S1 · S6","en":"THE BODY: immunity as resistance, split into the fast innate and the learned acquired forms.","cn":"身体：作为抵抗力的免疫，分为快速的先天型与习得的获得型。"},{"senses":"S2 · S3","en":"THE LAW: exemption from burdens, then the narrower treaty shield of envoys.","cn":"法律：免于负担，然后是更狭窄的使节条约屏障。"},{"senses":"S4","en":"THE COURTROOM TRADE: testimony is bought with a promise not to prosecute.","cn":"法庭交易：用不起诉的承诺换取证词。"},{"senses":"S5","en":"THE POPULATION: enough immune links break the chain of transmission.","cn":"人群层面：足够多的免疫环节打断了传播链。"},{"senses":"S7 · S8","en":"THE ORIGINAL BURDEN AND THE MIND: relief from payment, and a person shielded from criticism.","cn":"最初的负担与心理：免于付款，以及一个人对批评的屏障。"}]},"affixes":{"intro":{"en":"Immunity is in- 'not' plus munus 'duty' plus -itas, the suffix that turns an adjective into a state; English later rebuilt the family with -ize, -ization and -ology.","cn":"immunity 是 in-「不」加 munus「义务」再加 -itas（把形容词变成状态的名词后缀）；英语后来用 -ize、-ization、-ology 重建了整个词族。"},"latinIntro":{"en":"Latin immunis and immunitas supply the core; munus also yields municipal, munificent and remuneration, all built on the idea of something owed or given.","cn":"拉丁 immunis 与 immunitas 提供核心；munus 还衍生出 municipal、munificent、remuneration，都建立在「所欠或所给」这一概念上。"},"items":[{"word":"immunity","structure":"in- (not) + munus (duty) + -itas (state)","meaning":"the state of being exempt","meaningCN":"被免除的状态","example":"The law grants immunity to witnesses.","exampleCN":"法律给予证人豁免。"},{"word":"immune","structure":"in- + munis (performing duty)","meaning":"exempt; protected against disease","meaningCN":"被豁免的；有免疫力的","example":"Most adults are immune to this virus.","exampleCN":"多数成年人对这种病毒有免疫力。"},{"word":"immunize","structure":"immune + -ize (to make)","meaning":"to make immune","meaningCN":"使免疫；接种","example":"The clinic immunized the whole village.","exampleCN":"诊所给全村人做了接种。"},{"word":"immunization","structure":"immunize + -ation (process)","meaning":"the act of making immune","meaningCN":"免疫接种过程","example":"Childhood immunization saves millions of lives.","exampleCN":"儿童免疫接种挽救了数百万生命。"},{"word":"immunology","structure":"immuno- + -logia (study)","meaning":"the study of immune responses","meaningCN":"研究免疫反应的学科","example":"Immunology grew fast after the discovery of antibodies.","exampleCN":"抗体发现后免疫学迅速发展。"},{"word":"immunodeficiency","structure":"immuno- + deficiency (lack)","meaning":"a weakened immune system","meaningCN":"免疫系统功能不足","example":"The patient has a rare immunodeficiency.","exampleCN":"这位患者患有罕见的免疫缺陷。"},{"word":"autoimmunity","structure":"auto- (self) + immunity","meaning":"immune attack on the body's own tissue","meaningCN":"免疫系统攻击自身组织","example":"Autoimmunity explains the joint damage.","exampleCN":"自身免疫可以解释关节损伤。"},{"word":"immunosuppression","structure":"immuno- + suppression (pressing down)","meaning":"deliberate or disease-caused lowering of immunity","meaningCN":"有意或因病造成的免疫力下降","example":"Transplant patients need immunosuppression.","exampleCN":"移植患者需要免疫抑制。"}],"latinEntries":[{"word":"munus","structure":"munus, muneris (n., third declension)","meaning":"a duty, an office, a gift","meaningCN":"义务；公职；礼物"},{"word":"immunis","structure":"in- + munis (adjective)","meaning":"free from service or burden","meaningCN":"免于劳役或负担的"},{"word":"immunitas","structure":"immunis + -itas (f., third declension)","meaning":"exemption from public duties","meaningCN":"免除公共义务；豁免"}]}},{"word":"immune","ipa_uk":"/ɪˈmjuːn/","ipa_us":"/ɪˈmjuːn/","definition_zh":"有免疫力的；不受影响的；豁免的，免于…的","definition_en":"protected from a disease, or not affected by something harmful, unpleasant or demanding","core_image":"一个人站在屏障后面，外面的东西撞上来却伤不到他","scene":"Once you have had chickenpox you are usually immune to it for life.","sceneCN":"这里 immune 指「有免疫力的」（第 1 个义项：因曾感染或接种而对某病具有抵抗力）；句意：一旦得过水痘，通常就会终身对它免疫。图中可辨识物件：皮肤、病毒颗粒、抗体、屏障示意。","pos":[{"tag":"adj.","zh":"有免疫力的；不受影响的；豁免的，免于（义务、处罚）的"},{"tag":"n.","zh":"免疫者（罕用，多见于「the immune」）"}],"collocations":[{"phrase":"immune system","zh":"免疫系统"},{"phrase":"immune response","zh":"免疫反应"},{"phrase":"immune to disease","zh":"对疾病有免疫力"},{"phrase":"immune from prosecution","zh":"免于起诉"},{"phrase":"immune deficiency","zh":"免疫缺陷"},{"phrase":"immune to criticism","zh":"对批评无动于衷"}],"forms":[{"label":"名词（免疫力；豁免）","form":"immunity（免疫力；豁免）"},{"label":"动词（使免疫）","form":"immunize（使免疫）"},{"label":"比较级","form":"more immune（较少用）"},{"label":"最高级","form":"most immune（较少用）"},{"label":"副词","form":"immunely（免疫地，罕用）"},{"label":"名词（免疫者，集合）","form":"the immune（免疫人群）"}],"derivatives":[{"word":"immunity","pos":"n.","zh":"免疫力；豁免权"},{"word":"immunize","pos":"v.","zh":"使免疫；接种"},{"word":"immunization","pos":"n.","zh":"免疫接种"},{"word":"immunology","pos":"n.","zh":"免疫学"},{"word":"immunocompromised","pos":"adj.","zh":"免疫功能受损的"}],"senses":[{"no":"01","title":"Protected against disease","titleCN":"有免疫力的：对某种病具有抵抗力","definition":"protected from a particular disease, usually because the body has met the germ before or has been vaccinated","definitionCN":"对某种疾病有抵抗力，通常因身体曾遇该病原或已接种","example":"Once you have had chickenpox you are usually immune to it for life.","exampleCN":"一旦得过水痘，通常就会终身对它免疫。","why":"The adjective describes a person in the legal position of immunis: exempt from a demand, here the demand a germ makes on the body.","whyCN":"这个形容词描述的是处于 immunis 法律地位的人：被免于某项索取，此处即病原对身体提出的索取。"},{"no":"02","title":"Not susceptible to infection","titleCN":"不易感染的：天生就不易被该病原侵入的物种或个体","definition":"naturally unable to be infected by a particular organism, as some species are to diseases that affect others","definitionCN":"天生不能被某种生物感染，如某些物种对影响他者的疾病不敏感","example":"The disease kills cattle, but sheep appear to be immune.","exampleCN":"这种病能致死牛，但羊似乎不受感染。","why":"The barrier need not come from antibodies; a species can be immune because the germ simply cannot attach or enter its cells.","whyCN":"屏障未必来自抗体；一个物种可以因病原根本无法附着或进入其细胞而免疫。"},{"no":"03","title":"Immune system","titleCN":"免疫系统的：身体防御机制的","definition":"used before a noun to name the body's defence apparatus, as in immune system, immune cell, immune response","definitionCN":"用于名词前，指身体的防御装置，如免疫系统、免疫细胞、免疫反应","example":"The immune response peaked about a week after the injection.","exampleCN":"免疫反应在注射后约一周达到高峰。","why":"Once the adjective named a property, it could also label the machinery that produces it, so it became an attributive word in anatomy and physiology.","whyCN":"当这个形容词命名了一种属性后，也可以标签产生该属性的机制，于是成了解剖与生理中的定语词。"},{"no":"04","title":"Exempt from a legal duty","titleCN":"豁免的：免于某项法律义务或处罚","definition":"legally exempt from a duty, a tax, a charge or a penalty","definitionCN":"法律上免于某项义务、税负、费用或处罚","example":"Foreign diplomats are immune from local prosecution.","exampleCN":"外国外交官免受当地起诉。","why":"This is the original legal sense, still used with from: the person is not held liable where others would be.","whyCN":"这是最初的法律义，仍与 from 连用：在他人须负责之处，此人不受追究。"},{"no":"05","title":"Unaffected by criticism","titleCN":"不受批评影响的：听不进也伤不到","definition":"not affected or hurt by criticism, persuasion or pressure, often with a hint of irony","definitionCN":"不受批评、劝说或压力影响或伤害，常带一点反讽","example":"He seemed immune to every warning the coaches gave.","exampleCN":"教练的每一次警告似乎都对他无效。","why":"Criticism is imagined as an attack that the protected person simply does not receive, extending the legal shield into character.","whyCN":"批评被想象成一次攻击，而受保护者干脆接收不到，于是法律屏障被延伸到性格层面。"},{"no":"06","title":"Not subject to a rule","titleCN":"不受规则约束的：规则管不到","definition":"not subject to a rule, a trend or a force that governs others","definitionCN":"不受支配他人的规则、趋势或力量所约束","example":"No industry is immune to the law of supply and demand.","exampleCN":"没有哪个行业能不受供需规律约束。","why":"The word works as a general negative of 'subject to': whatever normally acts on others is said to find no purchase here.","whyCN":"这个词充当「受制于」的通用否定：凡通常作用于他者的力量，在这里都无从着力。"},{"no":"07","title":"Immune to a fault or error","titleCN":"不会出错的：系统或方法不受某类错误影响","definition":"describing a system or method that cannot be damaged by a particular fault or attack","definitionCN":"描述系统或方法不会被某类故障或攻击损害","example":"The design is immune to a single point of failure.","exampleCN":"这个设计不会因单点故障而失效。","why":"Engineering borrowed the medical and legal word because both describe a body that survives what would harm another body.","whyCN":"工程学借用了这个医学与法律词，因为两者都描述一个能在伤害他者之物下存活的系统。"},{"no":"08","title":"The immune, as a group","titleCN":"免疫人群：作为集合名词的罕用用法","definition":"as a plural collective, the people who are protected against a disease","definitionCN":"作集合名词，指对该病有保护的人群","example":"The immune were allowed to travel while others stayed home.","exampleCN":"已免疫者被允许出行，其他人则留在家中。","why":"English allows an adjective with the definite article to stand for a class of people, and public health writing uses this form for the protected share of a population.","whyCN":"英语允许「the + 形容词」代表一类人，公共卫生文献用这一形式指人群中被保护的那部分。"}],"etymology":{"intro":{"en":"Immune is Latin immunis 'free from public service', from in- 'not' plus munus 'duty'. It entered English as a legal word long before it became a medical one.","cn":"immune 是拉丁 immunis「免于公共劳役」，由 in-「不」加 munus「义务」构成。它先作为法律词进入英语，很久以后才成为医学词。"},"items":[{"era":"LATIN MUNUS","en":"Munus meant a duty, an office or a gift; munis as an adjective described one who performs duties.","cn":"munus 指义务、公职或礼物；形容词 munis 描述履行义务的人。"},{"era":"LATIN IMMUNIS","en":"Immunis, 'not performing duty', described persons and communities excused from taxes, garrison service or public office.","cn":"immunis「不服义务」描述被免除税负、驻防或公职的个人与共同体。"},{"era":"LEGAL ENGLISH","en":"English immune appears in the fifteenth century in legal contexts, meaning exempt from a service, a payment or a liability.","cn":"英语 immune 于 15 世纪出现在法律语境中，意为免于某项劳役、付款或责任。"},{"era":"MEDICAL BORROWING","en":"In the late nineteenth century the word was applied to persons and animals that a disease could not touch, and immune system followed in the twentieth.","cn":"19 世纪后期这个词被用于疾病碰不到的人与动物，20 世纪又出现了 immune system。"},{"era":"GENERAL EXTENSION","en":"From the twentieth century the adjective spread beyond medicine and law to mean 'not affected by' almost anything, from criticism to market forces.","cn":"从 20 世纪起，这个形容词越出医学与法律，泛指「不受……影响」，从批评到市场力量皆可。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertainty: the older derivation from munire 'to fortify' is still repeated in some sources but is not accepted by standard references; the munus explanation is preferred. The exact first English date is not firmly fixed.","cn":"来源不确定（词根解释存疑，仅首见年代存疑）：部分资料仍沿用来自 munire「筑防」的旧解释，但标准辞书不予采纳，学界倾向 munus 说。英语确切首见年代亦无定论。"}]},"similar":{"note":{"en":"The first group holds words from the same Latin root or the same spelling family; the second holds adjectives that overlap with immune in medicine, law and general use.","cn":"第一组是同出拉丁词根或同一拼写家族的词；第二组是在医学、法律与日常用法中与 immune 重叠的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"immunity","ipa":"/ɪˈmjuːnəti/","tag":"the noun","definition":"The state of being immune; the adjective describes a person, the noun names the condition or the legal right.","definitionCN":"指免疫或豁免的状态；形容词描述人，名词命名状态或法律权利。"},{"word":"immunize","ipa":"/ˈɪmjunaɪz/","tag":"the verb","definition":"To make someone immune by vaccine; it is an action, not a description.","definitionCN":"通过疫苗使人免疫；它是动作，不是描述。"},{"word":"munificent","ipa":"/mjuːˈnɪfɪsnt/","tag":"same root, generous","definition":"Built on munus 'gift' with -ficus 'making', meaning generous; it shares the root but not the exemption.","definitionCN":"由 munus「礼物」加 -ficus「造成」构成，意为慷慨；共享词根，但无豁免义。"},{"word":"immune vs. immutable","ipa":"/ɪˈmjuːtəbl/","tag":"similar shape, different root","definition":"Immutable means 'unchangeable', from mutare 'to change'; it is not related to munus.","definitionCN":"immutable 意为「不可改变的」，来自 mutare「改变」，与 munus 无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"resistant","ipa":"/rɪˈzɪstənt/","tag":"partial protection","definition":"Able to withstand something, often partially; resistant to a drug does not imply immune to it.","definitionCN":"能抵抗某物，通常只是部分的；对药物有抗性并不等于对它免疫。"},{"word":"exempt","ipa":"/ɪɡˈzempt/","tag":"legal near-synonym","definition":"Freed from a duty or payment by rule; it is the everyday legal adjective where immune is the privileged one.","definitionCN":"依规定免除义务或付款；它是日常法律形容词，immune 更带特权色彩。"},{"word":"invulnerable","ipa":"/ɪnˈvʌlnərəbl/","tag":"cannot be hurt at all","definition":"Literally 'cannot be wounded'; it is a stronger claim than immune, which usually concerns one specific threat.","definitionCN":"字面「不会受伤」；比 immune 更强，后者通常只针对某一种威胁。"},{"word":"unaffected","ipa":"/ˌʌnəˈfektɪd/","tag":"no change observed","definition":"Showing no change or reaction; it describes the result, while immune explains why no result appeared.","definitionCN":"没有表现出变化或反应；它描述结果，immune 则解释为何没有反应。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"in- 'not' + munus 'duty' = 'not liable to the duty', which covers both disease and law.","cn":"in-「不」+ munus「义务」=「不负该义务」，同时覆盖疾病与法律。"},{"en":"immune takes from for law and to for disease: immune from prosecution, immune to measles.","cn":"immune 在法律上用 from，在疾病上用 to：法律上「免于起诉」，疾病上「对麻疹免疫」。"},{"en":"The family runs immune, immunity, immunize, immunization, immunology, immunocompromised.","cn":"同族词包括 immune、immunity、immunize、immunization、immunology、immunocompromised。"},{"en":"Attributive uses name the machinery: immune system, immune response, immune cell.","cn":"定语用法命名机制：免疫系统、免疫反应、免疫细胞。"},{"en":"Do not confuse immune with immutable or with immunize; only the last is a verb.","cn":"不要把 immune 与 immutable 或 immunize 混同；只有最后一个是动词。"}],"abstract":[{"en":"Picture a coat that a germ cannot grip, no matter how it tries.","cn":"想象一件外衣，病原怎么试都抓不住。"},{"en":"Picture a wall that words bounce off without leaving a mark.","cn":"想象一堵墙，言语撞上去也不留痕迹。"},{"en":"Picture a machine that keeps running after one part fails.","cn":"想象一台机器，某个零件坏了仍然继续运转。"}]},"examples":[{"en":"Adults who had the infection as children are now immune.","cn":"小时候感染过的人现在已有免疫力。"},{"en":"No economy is immune to a sudden rise in energy prices.","cn":"没有哪个经济体能不受能源价格骤升的影响。"},{"en":"The witness was declared immune from prosecution in exchange for testimony.","cn":"该证人以作证为条件被宣布免于起诉。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「im 不 + mune 义务」——不负这项义务、不被它伤到 → immune 免疫的／豁免的","word":"immune"},"root":"拉丁 munus「义务；公务」→ in-「不」+ munis → immunis「免于劳役的」→ 英语 immune（15 世纪法律义，19 世纪起医学义）。","sensesIntro":{"en":"Eight senses follow one shield: protection from a disease, natural non-susceptibility, the machinery that produces it, legal exemption, immunity to criticism, to rules, to system failure, and the protected people taken as a group.","cn":"八个义项沿同一面屏障展开：对疾病的保护、天然不易感、产生保护的机制、法律豁免、对批评无感、对规则无感、对系统故障无感，以及作为群体的受保护者。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person behind a shield that the outside world cannot get through.","cn":"核心意象：一个人站在屏障之后，外面的东西过不来。"},"chain":["PROTECTED FROM DISEASE","NOT SUSCEPTIBLE","DEFENCE MACHINERY","LEGALLY EXEMPT","UNTOUCHED BY WORDS","UNBOUND BY RULES"],"branches":[{"senses":"S1 · S2","en":"THE BODY: acquired protection after meeting a germ, and natural protection a species simply has.","cn":"身体：接触病原后获得的保护，以及物种天生就有的保护。"},{"senses":"S3","en":"THE MACHINERY: the adjective becomes a label for the system and its cells.","cn":"机制：形容词变成系统与其细胞的标签。"},{"senses":"S4","en":"THE LAW: exemption from prosecution and from local jurisdiction.","cn":"法律：免于起诉、免于当地管辖。"},{"senses":"S5 · S6","en":"THE MIND AND THE RULEBOOK: words and rules are pictured as forces that find no hold.","cn":"心理与规则：言语与规则被想象成无从着力的力量。"},{"senses":"S7 · S8","en":"MACHINES AND GROUPS: systems survive a fault, and a whole protected class is named by the adjective.","cn":"机器与群体：系统能在故障中存活，整个受保护人群也用这个形容词命名。"}]},"affixes":{"intro":{"en":"Immune is in- 'not' plus munis 'performing duty'; the family adds -ity for the state, -ize for the action, and -ology for the science.","cn":"immune 是 in-「不」加 munis「履行义务」；词族再加 -ity 表状态、-ize 表动作、-ology 表学科。"},"latinIntro":{"en":"Latin immunis and its noun immunitas are the base; munus also gives municipal, munificent and remuneration, all built on duties, gifts and payments.","cn":"拉丁 immunis 及其名词 immunitas 是基础；munus 还衍生出 municipal、munificent、remuneration，都围绕义务、礼物与付款。"},"items":[{"word":"immune","structure":"in- (not) + munis (performing duty)","meaning":"exempt; protected","meaningCN":"被豁免的；受保护的","example":"She is immune to the virus.","exampleCN":"她对这种病毒有免疫力。"},{"word":"immunity","structure":"immunis + -itas (state)","meaning":"the state of exemption","meaningCN":"豁免或免疫的状态","example":"Immunity lasts for years after infection.","exampleCN":"感染后免疫力可持续数年。"},{"word":"immunize","structure":"immune + -ize (to make)","meaning":"to make immune","meaningCN":"使免疫","example":"They immunized every child in the camp.","exampleCN":"他们给营地里的每个孩子做了接种。"},{"word":"immunization","structure":"immunize + -ation (process)","meaning":"vaccination","meaningCN":"疫苗接种","example":"Immunization coverage rose to ninety percent.","exampleCN":"免疫接种覆盖率升至九成。"},{"word":"immunology","structure":"immuno- + -logia (study)","meaning":"the science of immunity","meaningCN":"免疫科学","example":"Immunology explains transplant rejection.","exampleCN":"免疫学解释了移植排斥。"},{"word":"immunocompromised","structure":"immuno- + compromised (weakened)","meaning":"having a weakened immune system","meaningCN":"免疫系统受损的","example":"Immunocompromised patients need extra care.","exampleCN":"免疫功能受损的患者需要额外照护。"},{"word":"autoimmune","structure":"auto- (self) + immune","meaning":"directed against the body's own tissue","meaningCN":"针对自身组织的","example":"An autoimmune disease attacks the joints.","exampleCN":"自身免疫病会攻击关节。"},{"word":"nonimmune","structure":"non- (not) + immune","meaning":"not protected against a disease","meaningCN":"对该病无免疫力的","example":"Nonimmune travellers should be vaccinated.","exampleCN":"无免疫力的旅行者应当接种。"}],"latinEntries":[{"word":"munus","structure":"munus, muneris (n., third declension)","meaning":"duty, office, gift","meaningCN":"义务；公职；礼物"},{"word":"munis","structure":"munis, munis, mune (adjective)","meaning":"performing a duty or service","meaningCN":"履行义务或公务的"},{"word":"immunis","structure":"in- + munis (adjective)","meaning":"free from service, exempt","meaningCN":"免于劳役的；被豁免的"}]}},{"word":"immunology","ipa_uk":"/ˌɪmjəˈnɒlədʒi/","ipa_us":"/ˌɪmjəˈnɑːlədʒi/","definition_zh":"免疫学；免疫系统（研究或临床语境）；免疫学检验","definition_en":"the branch of biology and medicine that studies the immune system, its responses and its disorders","core_image":"实验室里一排抗体检测板，旁边是一张画满细胞相互识别的图","scene":"She studied immunology to understand why some patients reject a transplanted organ.","sceneCN":"这里 immunology 指「免疫学」（第 1 个义项：研究免疫系统及其反应的学科）；句意：她学习免疫学，是为了弄明白为什么有些病人会排斥移植器官。图中可辨识物件：显微镜、抗体检测板、免疫细胞示意图、器官移植示意图。","pos":[{"tag":"n.","zh":"免疫学；（医院的）免疫学科室；免疫学检验（集合用法）"}],"collocations":[{"phrase":"clinical immunology","zh":"临床免疫学"},{"phrase":"basic immunology","zh":"基础免疫学"},{"phrase":"transplant immunology","zh":"移植免疫学"},{"phrase":"tumour immunology","zh":"肿瘤免疫学"},{"phrase":"allergy and immunology","zh":"变态反应与免疫学"},{"phrase":"department of immunology","zh":"免疫学系；免疫科"}],"forms":[{"label":"名词（免疫学家）","form":"immunologist（免疫学家）"},{"label":"形容词","form":"immunological（免疫学的；免疫的）"},{"label":"副词","form":"immunologically（从免疫学角度）"},{"label":"形容词（免疫的）","form":"immune（免疫的）"},{"label":"名词（免疫力）","form":"immunity（免疫力）"},{"label":"复合词","form":"immunohistochemistry（免疫组织化学）"}],"derivatives":[{"word":"immunologist","pos":"n.","zh":"免疫学家"},{"word":"immunological","pos":"adj.","zh":"免疫学的；免疫性的"},{"word":"immunologically","pos":"adv.","zh":"在免疫学上"},{"word":"immunopathology","pos":"n.","zh":"免疫病理学"},{"word":"immunogenetics","pos":"n.","zh":"免疫遗传学"}],"senses":[{"no":"01","title":"The science of immunity","titleCN":"免疫学：研究免疫系统如何识别与反应的学科","definition":"the scientific study of the immune system, including how the body recognises foreign material and responds to it","definitionCN":"研究免疫系统、包括身体如何识别异物并作出反应的学科","example":"She studied immunology to understand why some patients reject a transplanted organ.","exampleCN":"她学习免疫学，是为了弄明白为什么有些病人会排斥移植器官。","why":"The word is built like any other science: the object of study, immunity, plus -logia, 'the study of'. Immunology began when immunity stopped being a legal idea and became a measurable bodily state.","whyCN":"这个词按科学名词的常规构成：研究对象 immunity 加 -logia「研究」。当免疫从法律概念变成可测量的身体状态，免疫学就诞生了。"},{"no":"02","title":"Clinical specialty","titleCN":"临床免疫学：诊治免疫相关疾病的专科","definition":"the medical specialty that diagnoses and treats diseases caused by a faulty or overactive immune system","definitionCN":"诊断与治疗由免疫系统缺陷或过度反应所致疾病的医学专科","example":"The immunology clinic follows patients with repeated severe infections.","exampleCN":"免疫科门诊随访那些反复发生严重感染的患者。","why":"Once diseases were traced to the immune system itself, a hospital needed a department to manage them, and the name of the science became the name of the service.","whyCN":"当疾病被追到免疫系统本身，医院就需要一个科室来管理它们，学科的名字于是成了服务的名字。"},{"no":"03","title":"The immunology laboratory","titleCN":"免疫学检验：用抗体、细胞等做的实验诊断","definition":"in hospital usage, the laboratory service that runs antibody, antigen and cell tests","definitionCN":"医院语境中指运行抗体、抗原与细胞检测的实验室服务","example":"Immunology reported that her antibody levels were low.","exampleCN":"免疫学实验室报告她的抗体水平偏低。","why":"The tests depend on the same antibody-antigen reactions the science describes, so the ward uses the discipline's name for the bench that performs them.","whyCN":"这些检测依赖的正是该学科所描述的抗原抗体反应，于是病房用学科之名来指执行检测的实验室台。"},{"no":"04","title":"Transplant immunology","titleCN":"移植免疫学：研究排斥与耐受的分支","definition":"the branch that studies why a body rejects or accepts transplanted tissue, and how to prevent rejection","definitionCN":"研究身体为何排斥或接受移植组织、以及如何防止排斥的分支","example":"Transplant immunology made kidney grafting a routine operation.","exampleCN":"移植免疫学使肾移植成为常规手术。","why":"A graft is the clearest test of self versus non-self, so the field grew around surgery and produced both matching tests and anti-rejection drugs.","whyCN":"移植物是「自我与非我」最清楚的试验，因此这一分支围绕外科生长，既产出了配型检验，也产出了抗排斥药物。"},{"no":"05","title":"Tumour immunology","titleCN":"肿瘤免疫学：研究免疫系统与肿瘤的对抗","definition":"the branch that studies how the immune system recognises or fails to recognise cancer cells","definitionCN":"研究免疫系统如何识别癌细胞、或为何识别失败的分支","example":"Tumour immunology produced drugs that release the brakes on immune cells.","exampleCN":"肿瘤免疫学造出了能解除免疫细胞刹车的药物。","why":"Cancer arises from the body's own cells, so the immune system must be taught to see a difference that is almost invisible; this paradox created its own subfield.","whyCN":"癌来自身体自身的细胞，免疫系统必须被教会看见一种几乎看不见的差别；这一悖论催生了独立的分支。"},{"no":"06","title":"Allergy and immunology","titleCN":"变态反应与免疫学：合并设置的专科","definition":"the combined specialty that treats allergies, asthma and immune disorders as one clinical field","definitionCN":"把变态反应、哮喘与免疫疾病作为一个临床领域来诊治的合并专科","example":"She is board certified in allergy and immunology.","exampleCN":"她获得了变态反应与免疫学的专科认证。","why":"Allergy is an immune response aimed at a harmless target, so the two subjects share patients, tests and drugs and are usually taught and practised together.","whyCN":"变态反应是免疫系统对无害目标发起的反应，两者共享病人、检测与药物，因此通常一起教学与执业。"},{"no":"07","title":"Comparative immunology","titleCN":"比较免疫学：跨物种研究防御系统","definition":"the branch that compares immune systems across animals and plants to trace how defence evolved","definitionCN":"比较不同动物与植物免疫系统、追溯防御如何演化的分支","example":"Comparative immunology shows that insects have their own forms of immune memory.","exampleCN":"比较免疫学显示昆虫有自己形式的免疫记忆。","why":"If immunity is a general problem of living things, then comparing species reveals which solutions are ancient and which are recent inventions.","whyCN":"如果免疫是生物普遍面临的问题，那么比较物种就能看出哪些方案古老、哪些是新近的发明。"},{"no":"08","title":"Immunology of infection","titleCN":"感染免疫学：病原与宿主防御的相互作用","definition":"the study of how a specific pathogen and the host's immune response act on each other during infection","definitionCN":"研究特定病原与宿主免疫反应在感染过程中如何相互作用","example":"The immunology of tuberculosis explains why the disease can stay dormant for years.","exampleCN":"结核病的免疫学解释了这种病为何能潜伏多年。","why":"The subject can be attached to a disease, because each germ has evolved its own way of evading or provoking the response, and that interaction needs its own account.","whyCN":"这门学科可以接到具体疾病上，因为每种病原都演化出各自逃避或激起反应的方式，而这种互动需要单独的说明。"}],"etymology":{"intro":{"en":"Immunology joins immunity to the Greek suffix -logia 'the study of'. The word could only appear after immunity had become a biological phenomenon with measurable mechanisms.","cn":"immunology 把 immunity 接到希腊后缀 -logia「研究」上。只有当免疫成为具有可测机制的生命现象之后，这个词才可能出现。"},"items":[{"era":"LATIN IMMUNITAS","en":"Immunitas first meant exemption from public duties; the medical sense of protection from disease developed only in the late nineteenth century.","cn":"immunitas 最初指免除公共义务；医学上「免于疾病」的意思要到 19 世纪后期才发展出来。"},{"era":"GREEK LOGOS","en":"Greek logos meant word, account, reason; the suffix -logia named a reasoned account of a subject, and English uses it for every -ology.","cn":"希腊 logos 意为言说、论述、理性；后缀 -logia 指对某主题的系统论述，英语用它构成所有 -ology。"},{"era":"BACTERIOLOGY 1880S","en":"When germ theory identified specific microbes, researchers began to ask why one animal survived an infection and another died, and the question became a science.","cn":"当病菌学说识别出具体微生物后，研究者开始追问为何一只动物在感染中存活、另一只死亡，这个问题于是成为一门科学。"},{"era":"THE WORD","en":"English immunology is recorded from the late nineteenth century, alongside immunologist; the first citations are usually placed in the 1890s.","cn":"英语 immunology 记录于 19 世纪后期，与 immunologist 同时出现；通常把最早书证定在 1890 年代。"},{"era":"TWENTIETH-CENTURY SPLIT","en":"As the field grew, immunology divided into clinical, transplant, tumour and comparative branches, and each branch kept the same name with a prefix.","cn":"随着领域扩大，免疫学分成临床、移植、肿瘤与比较等分支，每一支都在同一个名字前加一个前缀。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertainty: the exact year of the first English use of immunology is not firmly fixed, and the attribution to a single coiner is not established; the 1890s dating is an approximation.","cn":"来源不确定（仅首见年代存疑）：immunology 英语首见的确切年份无定论，也无法确证由某一人独造；1890 年代之说只是约数。"}]},"similar":{"note":{"en":"The first group holds words built from the same stem or the same -ology pattern; the second holds neighbouring disciplines and the people who practise them.","cn":"第一组是用同一词干或同一 -ology 模式造的形近词；第二组是相邻学科与从业者称谓。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"immunologist","ipa":"/ˌɪmjəˈnɒlədʒɪst/","tag":"the person","definition":"A scientist or doctor who practises immunology; -logist marks the person where -logy marks the field.","definitionCN":"从事免疫学的科学家或医生；-logist 指人，-logy 指学科。"},{"word":"immunological","ipa":"/ˌɪmjəˈnɒlədʒɪkl/","tag":"the adjective","definition":"Meaning 'relating to immunology or to immune reactions', as in immunological memory.","definitionCN":"意为「免疫学的、免疫反应的」，如免疫记忆。"},{"word":"immunity","ipa":"/ɪˈmjuːnəti/","tag":"the object, not the study","definition":"The bodily or legal state itself; immunology studies it but does not name it.","definitionCN":"指身体或法律上的状态本身；immunology 研究它，但不命名它。"},{"word":"immunochemistry","ipa":"/ˌɪmjənəʊˈkemɪstri/","tag":"sister field with another suffix","definition":"The chemistry of immune reactions; it shares the immuno- prefix but names a method rather than the whole discipline.","definitionCN":"研究免疫反应的化学；共享 immuno- 前缀，但命名的是一种方法而非整门学科。"}]},{"heading":"NEAR MEANING","entries":[{"word":"serology","ipa":"/sɪˈrɒlədʒi/","tag":"the older test science","definition":"The study of blood serum and its antibodies; much of what immunology now explains began as serology.","definitionCN":"研究血清及其抗体的学科；免疫学如今解释的许多内容最初属于血清学。"},{"word":"microbiology","ipa":"/ˌmaɪkrəʊbaɪˈɒlədʒi/","tag":"the germs, not the defence","definition":"The study of microorganisms; microbiology looks at the invader, immunology at the response.","definitionCN":"研究微生物的学科；微生物学看入侵者，免疫学看反应。"},{"word":"virology","ipa":"/vaɪˈrɒlədʒi/","tag":"one class of pathogen","definition":"The study of viruses; immunology overlaps with it wherever the host response to a virus is at issue.","definitionCN":"研究病毒的学科；凡是涉及宿主对病毒的反应之处，免疫学与它重叠。"},{"word":"allergology","ipa":"/ˌæləˈɡɒlədʒi/","tag":"one clinical branch","definition":"The study of allergies, often practised together with immunology but naming only one kind of immune disorder.","definitionCN":"研究变态反应的学科，常与免疫学合并执业，但只命名一类免疫疾病。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"immuno- 'immunity' + -logy 'the study of' gives 'the study of immunity'.","cn":"immuno-「免疫」+ -logy「研究」得出「研究免疫的学科」。"},{"en":"The family runs immunology, immunologist, immunological, immunologically, immunopathology.","cn":"同族词包括 immunology、immunologist、immunological、immunologically、immunopathology。"},{"en":"Branches are made by adding a prefix: clinical, transplant, tumour, comparative immunology.","cn":"分支靠加前缀构成：临床、移植、肿瘤、比较免疫学。"},{"en":"The ward says immunology for the lab that runs antibody tests.","cn":"病房用 immunology 指运行抗体检测的实验室。"},{"en":"-logy is the field, -logist the person, -logical the adjective.","cn":"-logy 指学科，-logist 指人，-logical 是形容词。"}],"abstract":[{"en":"Picture a border guard who must decide, in seconds, whether a face is familiar.","cn":"想象一名边检员必须在几秒内判断一张面孔是否熟悉。"},{"en":"Picture a lab plate where tiny dots show which antibody has found its match.","cn":"想象一块实验板，上面的小点显示哪个抗体找到了对手。"},{"en":"Picture two nearly identical cells, one welcomed and one rejected.","cn":"想象两个几乎一模一样的细胞，一个被接纳，一个被排斥。"}]},"examples":[{"en":"Modern immunology began with the study of how animals resist infection.","cn":"现代免疫学始于对动物如何抵抗感染的研究。"},{"en":"The immunology department runs tests for autoimmune disease.","cn":"免疫科开展自身免疫病的检测。"},{"en":"Her lecture traced the split between immunology and serology.","cn":"她的讲座梳理了免疫学与血清学的分家过程。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「immun 免疫 + ology 学科」——研究免疫的学问 → immunology 免疫学","word":"immunology"},"root":"拉丁 immunis「免于劳役的」→ immunity「免疫」+ 希腊 -logia「研究」→ 英语 immunology（19 世纪后期）。","sensesIntro":{"en":"Eight senses follow one discipline: the science itself, the hospital specialty, the testing bench, then four branches defined by what they study, and finally the immunology of a single disease.","cn":"八个义项沿一门学科展开：学科本身、医院的专科、检验台，随后是四个按研究对象划分的分支，最后是某种具体疾病的免疫学。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bench of antibody tests beside a diagram of cells recognising one another.","cn":"核心意象：一排抗体检测板，旁边是细胞相互识别的示意图。"},"chain":["STUDY OF IMMUNITY","CLINICAL SPECIALTY","TEST LABORATORY","TRANSPLANT BRANCH","TUMOUR BRANCH","DISEASE-SPECIFIC STUDY"],"branches":[{"senses":"S1","en":"THE DISCIPLINE: immunity becomes an object of systematic study.","cn":"学科：免疫成为系统研究的对象。"},{"senses":"S2 · S3","en":"THE HOSPITAL: the same name covers the clinic and the bench that serves it.","cn":"医院：同一个名字既指门诊，也指服务门诊的检验台。"},{"senses":"S4 · S5","en":"SURGERY AND CANCER: two fields where the self/non-self decision is hardest.","cn":"外科与肿瘤：自我与非我判断最艰难的两个领域。"},{"senses":"S6","en":"ALLERGY: an immune response aimed at a harmless target.","cn":"变态反应：瞄准无害目标的免疫反应。"},{"senses":"S7 · S8","en":"COMPARISON AND INFECTION: the same questions asked across species and across one germ.","cn":"比较与感染：同样的问题，跨越物种来问，也针对单一病原来问。"}]},"affixes":{"intro":{"en":"Immunology is immuno- plus -logy, the standard pattern for a science; its relatives swap -logy for -logist, -logical and -pathology.","cn":"immunology 是 immuno- 加 -logy，这是科学名词的标准模式；同族词把 -logy 换成 -logist、-logical、-pathology。"},"latinIntro":{"en":"The first element is Latin immunis; the second is Greek -logia. The word is therefore a Latin-Greek hybrid, like many scientific names.","cn":"第一部分是拉丁 immunis，第二部分是希腊 -logia。因此这个词像许多科学名词一样，是拉丁与希腊的混合体。"},"items":[{"word":"immunology","structure":"immuno- (immunity) + -logia (study)","meaning":"the study of immunity","meaningCN":"研究免疫的学科","example":"Immunology explains vaccine memory.","exampleCN":"免疫学解释了疫苗记忆。"},{"word":"immunologist","structure":"immuno- + -logist (one who studies)","meaning":"a specialist in immunology","meaningCN":"免疫学专家","example":"The immunologist reviewed the biopsy.","exampleCN":"免疫学家复核了活检结果。"},{"word":"immunological","structure":"immunology + -ical (relating to)","meaning":"relating to immunology","meaningCN":"与免疫学有关的","example":"The two samples are immunologically identical.","exampleCN":"这两个样本在免疫学上是同一的。"},{"word":"immunologically","structure":"immunological + -ly (adverb)","meaning":"in immunological terms","meaningCN":"从免疫学角度","example":"The tissue was immunologically inert.","exampleCN":"该组织在免疫学上无活性。"},{"word":"immunopathology","structure":"immuno- + -pathology (disease study)","meaning":"the study of immune-caused damage","meaningCN":"研究免疫所致损伤的学科","example":"Immunopathology found deposits in the kidney.","exampleCN":"免疫病理学在肾脏发现了沉积物。"},{"word":"immunogenetics","structure":"immuno- + genetics","meaning":"the genetics of immune molecules","meaningCN":"免疫分子的遗传学","example":"Immunogenetics maps the antibody genes.","exampleCN":"免疫遗传学绘制抗体基因图谱。"},{"word":"immunohistochemistry","structure":"immuno- + histochemistry","meaning":"antibody-based staining of tissue","meaningCN":"用抗体对组织进行染色","example":"Immunohistochemistry marked the tumour cells.","exampleCN":"免疫组化标记出了肿瘤细胞。"},{"word":"immunotherapy","structure":"immuno- + therapy","meaning":"treatment that uses immune mechanisms","meaningCN":"利用免疫机制的治疗","example":"Immunotherapy extended her remission.","exampleCN":"免疫治疗延长了她的缓解期。"}],"latinEntries":[{"word":"immunis","structure":"in- + munis (adjective)","meaning":"exempt, free from service","meaningCN":"被豁免的；免于劳役的"},{"word":"immunitas","structure":"immunis + -itas (f., third declension)","meaning":"exemption; immunity","meaningCN":"豁免；免疫"},{"word":"munus","structure":"munus, muneris (n., third declension)","meaning":"duty, service, gift","meaningCN":"义务；公务；礼物"}]}},{"word":"antibody","ipa_uk":"/ˈæntɪbɒdi/","ipa_us":"/ˈæntɪbɑːdi/","definition_zh":"抗体；免疫球蛋白","definition_en":"a protein made by the immune system that recognises and binds to a specific foreign substance","core_image":"一个 Y 形的蛋白分子用两个臂抓住一个病毒表面的突起","scene":"The antibody binds to the virus and marks it for destruction.","sceneCN":"这里 antibody 指「抗体」（第 1 个义项：免疫系统产生、能识别并结合特定异物的蛋白）；句意：抗体结合到病毒上，并把它标记为待清除对象。图中可辨识物件：Y 形蛋白分子、病毒颗粒、结合位点、免疫细胞。","pos":[{"tag":"n.","zh":"抗体；免疫球蛋白（能识别并结合特定抗原的蛋白）"}],"collocations":[{"phrase":"monoclonal antibody","zh":"单克隆抗体"},{"phrase":"neutralizing antibody","zh":"中和抗体"},{"phrase":"antibody response","zh":"抗体反应"},{"phrase":"antibody titre","zh":"抗体滴度"},{"phrase":"autoantibody","zh":"自身抗体"},{"phrase":"antibody test","zh":"抗体检测"}],"forms":[{"label":"复数","form":"antibodies"},{"label":"形容词","form":"antibody-mediated（抗体介导的，复合词）"},{"label":"同义学术语","form":"immunoglobulin（免疫球蛋白）"},{"label":"相关名词","form":"antigen（抗原）"},{"label":"相关形容词","form":"antigenic（抗原性的）"}],"derivatives":[{"word":"antigen","pos":"n.","zh":"抗原"},{"word":"autoantibody","pos":"n.","zh":"自身抗体"},{"word":"antibody","pos":"n.","zh":"抗体（本词）"},{"word":"immunoglobulin","pos":"n.","zh":"免疫球蛋白"},{"word":"antiserum","pos":"n.","zh":"抗血清"}],"senses":[{"no":"01","title":"Immune binding protein","titleCN":"抗体：免疫系统产生、能特异结合的蛋白","definition":"a protein produced by immune cells that recognises a specific foreign molecule and binds to it","definitionCN":"免疫细胞产生、能识别特定异物分子并与之结合的蛋白质","example":"The antibody binds to the virus and marks it for destruction.","exampleCN":"抗体结合到病毒上，并把它标记为待清除对象。","why":"The name is a literal translation of German Antikörper, 'against-body': the substance made against the foreign body that entered.","whyCN":"这个名字是德语 Antikörper「对抗外来体」的直译：针对进入体内的异物而造出的物质。"},{"no":"02","title":"A specific antibody","titleCN":"某一种抗体：针对某一抗原的那一个","definition":"one particular antibody directed at one antigen, often named after its target","definitionCN":"针对某一抗原的一种抗体，常以其目标命名","example":"Doctors looked for antibodies to the measles virus in her blood.","exampleCN":"医生在她的血液中寻找针对麻疹病毒的抗体。","why":"Each antibody has a unique binding site, so the general word is constantly used for a single member of the family, named by its target.","whyCN":"每个抗体都有独特的结合位点，因此这个总称常被用来指家族中的一个具体成员，并以目标命名。"},{"no":"03","title":"Neutralizing antibody","titleCN":"中和抗体：结合后使病原失去感染力","definition":"an antibody that blocks a virus or toxin from entering cells or doing harm","definitionCN":"结合后阻止病毒或毒素进入细胞或造成伤害的抗体","example":"A neutralizing antibody can stop the virus before it enters a cell.","exampleCN":"中和抗体能在病毒进入细胞之前把它拦住。","why":"Binding alone is not always enough; some antibodies physically cover the entry site, and that functional result earned its own name.","whyCN":"仅仅结合未必够用；有些抗体物理地遮住进入位点，这一功能结果便获得了专名。"},{"no":"04","title":"Monoclonal antibody","titleCN":"单克隆抗体：来自单一细胞系、结构一致","definition":"a laboratory-made antibody produced from one cell line, so that every copy is identical","definitionCN":"由单一细胞系产生的实验室抗体，每一份拷贝都相同","example":"The monoclonal antibody is used in both tests and cancer treatment.","exampleCN":"这种单克隆抗体既用于检测，也用于癌症治疗。","why":"Natural antibodies are a mixture; cloning one cell line makes a single reagent, and industry needed a term for that uniformity.","whyCN":"天然抗体是混合物；克隆一个细胞系可得到单一试剂，产业需要为这种一致性造一个术语。"},{"no":"05","title":"Polyclonal antibody","titleCN":"多克隆抗体：来自多种细胞、识别多个位点","definition":"an antibody preparation containing many different antibodies that recognise different parts of the same target","definitionCN":"含多种抗体、识别同一目标不同部位的抗体制品","example":"The polyclonal antibody still works when the virus mutates.","exampleCN":"即使病毒变异，这种多克隆抗体仍然有效。","why":"An animal immunised against a whole germ makes many antibodies at once, and that breadth is useful precisely where a single clone would fail.","whyCN":"用整个病原免疫动物会一次产生许多抗体，这种广度恰在单一克隆失效之处有用。"},{"no":"06","title":"Autoantibody","titleCN":"自身抗体：攻击自身组织的抗体","definition":"an antibody that recognises the body's own tissue and attacks it, causing autoimmune disease","definitionCN":"识别并攻击自身组织的抗体，引起自身免疫病","example":"Autoantibodies against the thyroid explain her fatigue.","exampleCN":"针对甲状腺的自身抗体解释了她的疲乏。","why":"The mechanism is the same as against a germ; only the target is wrong, so a prefix rather than a new word marks the pathology.","whyCN":"机制与对抗病原完全相同，只是目标错了，因此用前缀而不是新词来标记这种病理。"},{"no":"07","title":"Antibody titre","titleCN":"抗体滴度：以稀释倍数表示的抗体浓度","definition":"the amount of a particular antibody in the blood, usually expressed as the highest dilution that still gives a positive test","definitionCN":"血中某种抗体的量，通常以仍呈阳性结果的最高稀释倍数表示","example":"Her antibody titre rose sharply after the second dose.","exampleCN":"第二剂之后她的抗体滴度大幅上升。","why":"Because antibodies act by binding, their usefulness is a matter of how much is present, and dilution is the practical way to measure that.","whyCN":"抗体的作用靠结合，因此其有用性取决于存在多少，而稀释是测量这个量的实用方法。"},{"no":"08","title":"Antibody as reagent","titleCN":"抗体试剂：检测中用来抓取目标分子","definition":"an antibody used in the laboratory as a tool to detect, label or separate the molecule it binds","definitionCN":"实验室中用来检测、标记或分离其所结合分子的抗体工具","example":"The antibody was conjugated to a dye for the pregnancy test.","exampleCN":"这种抗体被接上染料，用于妊娠检测。","why":"Specific binding is a targeting mechanism, so the same molecule that defends a body can be used to find a substance on a plastic strip.","whyCN":"特异结合是一种定位机制，因此同一个保卫身体的分子也能被用来在塑料试纸条上找到某种物质。"}],"etymology":{"intro":{"en":"Antibody is an English loan translation of German Antikörper, coined in the age of serum research: anti- 'against' plus body, the foreign body that the substance works against.","cn":"antibody 是德语 Antikörper 的英语仿译，造于血清研究时代：anti-「对抗」加 body，即该物质所对抗的外来体。"},"items":[{"era":"GREEK ANTI","en":"Greek anti meant 'against, instead of', and English uses it in hundreds of words for opposition or counteraction.","cn":"希腊 anti 意为「对抗、代替」，英语用它造出大量表示对抗或反作用的词。"},{"era":"SERUM RESEARCH","en":"In the 1890s researchers found that blood serum could neutralise toxins and bacteria, and that the effect could be transferred from one animal to another.","cn":"1890 年代研究者发现血清能中和毒素与细菌，而且这种效应可从一只动物转移到另一只。"},{"era":"GERMAN ANTIKÖRPER","en":"Paul Ehrlich and others described the active substances as substances formed against a foreign body, and German named them Antikörper.","cn":"保罗·埃利希等人把这些活性物质描述为针对外来体而形成的物质，德语称之为 Antikörper。"},{"era":"ENGLISH LOAN TRANSLATION","en":"English rendered the German compound piece by piece as antibody, first in the 1890s, keeping the literal structure of the original.","cn":"英语把德语复合词逐部件译成 antibody，最早见于 1890 年代，保留了原词的字面结构。"},{"era":"IMMUNOGLOBULIN","en":"When the chemistry of these proteins was worked out in the twentieth century, the neutral term immunoglobulin was added, and the two words now name the same class from different angles.","cn":"20 世纪弄清这些蛋白的化学结构后，又加入了中性的 immunoglobulin 一词；今天两个词从不同角度命名同一类分子。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertainty: the exact English first date and the precise share of credit between Ehrlich and his contemporaries are not firmly fixed; the 1891 attribution usually given is approximate.","cn":"来源不确定（仅首见年代与归属存疑）：antibody 的英语确切首见年代、以及埃利希与同代人之间应得的贡献比例都无定论；通常所说的 1891 年只是约数。"}]},"similar":{"note":{"en":"The first group holds the partner terms and look-alikes built from anti-; the second holds the immune proteins and preparations that are easily mistaken for an antibody.","cn":"第一组是配对术语与用 anti- 构成的形近词；第二组是容易与抗体混淆的免疫蛋白与制品。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"antigen","ipa":"/ˈæntɪdʒən/","tag":"the target, not the defender","definition":"The foreign substance that an antibody binds; antigen ends in -gen 'producing', antibody ends in body.","definitionCN":"抗体所结合的异物；antigen 以 -gen「产生」结尾，antibody 以 body 结尾。"},{"word":"antibiotic","ipa":"/ˌæntibaɪˈɒtɪk/","tag":"same prefix, different war","definition":"A drug that kills bacteria, from anti- plus Greek bios 'life'; it acts on the germ, not on the immune system.","definitionCN":"杀灭细菌的药物，来自 anti- 加希腊 bios「生命」；它作用于病原而非免疫系统。"},{"word":"antiserum","ipa":"/ˈæntɪsɪərəm/","tag":"the preparation, not the molecule","definition":"Blood serum containing antibodies, used as a treatment; it is a container of antibodies, not one antibody.","definitionCN":"含抗体的血清制品，用作治疗；它是抗体的容器，而不是单个抗体。"},{"word":"immunoglobulin","ipa":"/ˌɪmjənəʊˈɡlɒbjəlɪn/","tag":"the chemical name","definition":"The protein class to which antibodies belong; the two words overlap almost completely but differ in register.","definitionCN":"抗体所属的蛋白类别；两个词几乎完全重叠，只是语体不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"immunity","ipa":"/ɪˈmjuːnəti/","tag":"the state, not the molecule","definition":"The protection itself; antibodies are one of the means by which immunity is achieved.","definitionCN":"指保护状态本身；抗体是实现免疫的手段之一。"},{"word":"vaccine","ipa":"/ˈvæksiːn/","tag":"the teacher, not the soldier","definition":"A preparation that trains the body to make antibodies; it contains antigens rather than antibodies.","definitionCN":"训练身体产生抗体的制品；它含的是抗原而不是抗体。"},{"word":"T cell","ipa":"/tiː sel/","tag":"the other arm of immunity","definition":"A white blood cell that kills infected cells directly; it acts by contact rather than by secreted binding proteins.","definitionCN":"直接杀死受感染细胞的白细胞；它靠接触而非分泌结合蛋白发挥作用。"},{"word":"receptor","ipa":"/rɪˈseptə/","tag":"binding, but not antibody","definition":"A molecule on a cell surface that binds a specific substance; it shares the binding function but is not made against a germ.","definitionCN":"细胞表面结合特定物质的分子；共享结合功能，但不是针对病原而造。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"anti- 'against' + body 'foreign body' gives 'the thing made against the invader'.","cn":"anti-「对抗」+ body「外来体」得出「针对入侵者造出的东西」。"},{"en":"The pair is fixed: antigen is the target, antibody is the defender.","cn":"这一对是固定的：antigen 是目标，antibody 是防御者。"},{"en":"The family runs antibody, antigen, antiserum, autoantibody and immunoglobulin.","cn":"同族词包括 antibody、antigen、antiserum、autoantibody、immunoglobulin。"},{"en":"Y-shaped with two arms: each arm is one binding site, which is why one antibody can grip two targets.","cn":"Y 形有两个臂，每个臂一个结合位点，因此一个抗体能抓住两个目标。"},{"en":"monoclonal means one clone, polyclonal means many clones.","cn":"monoclonal 指单一克隆，polyclonal 指多克隆。"}],"abstract":[{"en":"Picture a molecular hand that fits one lock and no other.","cn":"想象一只分子之手，只配一把锁，别的一概不配。"},{"en":"Picture a tag attached to an intruder so the guards can see it.","cn":"想象一张标签贴到入侵者身上，让守卫看得见。"},{"en":"Picture a factory line where every copy of one tool is identical.","cn":"想象一条生产线，同一件工具的每一份都一模一样。"}]},"examples":[{"en":"Antibodies appear in the blood a week or two after infection.","cn":"感染后一两周，血液中会出现抗体。"},{"en":"Monoclonal antibodies are grown in tanks rather than taken from people.","cn":"单克隆抗体在罐中培养，而不是从人体中提取。"},{"en":"The antibody test shows past exposure, not current infection.","cn":"抗体检测显示的是既往接触，而不是当前感染。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「anti 对抗 + body 身体（外来体）」——针对外来体造出的蛋白 → antibody 抗体","word":"antibody"},"root":"希腊 anti「对抗」+ 英语 body「体」→ 仿译德语 Antikörper → 英语 antibody（1890 年代）。","sensesIntro":{"en":"Eight senses follow one Y-shaped grip: the class of binding proteins, one member of it, the neutralizing and monoclonal and polyclonal forms, the misdirected autoantibody, its measured amount, and its use as a lab reagent.","cn":"八个义项沿一个 Y 形抓握展开：这一类结合蛋白、其中一个成员、中和型与单克隆型及多克隆型、瞄错目标的自身抗体、它的测定量，以及它作为实验室试剂的用途。"},"semanticMap":{"core":{"en":"CORE IMAGE: a Y-shaped protein whose two arms lock onto a germ's surface.","cn":"核心意象：一个 Y 形蛋白，两个臂锁住病原表面。"},"chain":["BINDING PROTEIN","ONE SPECIFIC ANTIBODY","NEUTRALIZING FORM","MONOCLONAL TOOL","MISDIRECTED FORM","MEASURED AND USED"],"branches":[{"senses":"S1 · S2","en":"CLASS AND MEMBER: the whole family of binding proteins, then a single named one.","cn":"类别与成员：整个结合蛋白家族，然后是单个有名字的成员。"},{"senses":"S3 · S4","en":"FUNCTION AND MANUFACTURE: some antibodies block entry, others are grown as identical reagents.","cn":"功能与制造：有些抗体封住入口，有些则被培养成一致的试剂。"},{"senses":"S5","en":"BREADTH: a polyclonal mixture covers many sites where one clone cannot.","cn":"广度：多克隆混合物覆盖单一克隆覆盖不了的多个位点。"},{"senses":"S6 · S7","en":"WRONG TARGET AND NUMBER: against the self it causes disease, and its amount is measured by dilution.","cn":"错误目标与数量：针对自身时致病，其多少用稀释测定。"},{"senses":"S8","en":"OUT OF THE BODY: specific binding becomes a detection tool on a test strip.","cn":"离开身体：特异结合变成试纸条上的检测工具。"}]},"affixes":{"intro":{"en":"Antibody is a two-word compound fused into one: anti- 'against' plus body. Its relatives are built by adding prefixes such as auto- and mono-.","cn":"antibody 是两个词融合成的复合词：anti-「对抗」加 body。同族词靠加 auto-、mono- 等前缀构成。"},"latinIntro":{"en":"The anti- element is Greek; the body element is English. The word is a modern scientific compound rather than a Latin inheritance, and it mirrors German Antikörper.","cn":"anti- 成分来自希腊语，body 成分是英语。这个词是现代科学复合词，而非拉丁语继承，它对应德语 Antikörper。"},"items":[{"word":"antibody","structure":"anti- (against) + body","meaning":"a protein made against a foreign substance","meaningCN":"针对异物而造的蛋白","example":"One antibody can bind two virus particles.","exampleCN":"一个抗体能结合两个病毒颗粒。"},{"word":"antibodies","structure":"antibody + -ies (plural)","meaning":"the class, in plural","meaningCN":"抗体（复数）","example":"Antibodies persist for years after measles.","exampleCN":"麻疹后抗体可持续多年。"},{"word":"antigen","structure":"anti- + -gen (producing)","meaning":"the substance that makes antibodies be produced","meaningCN":"促使抗体产生的物质","example":"The spike protein is the main antigen.","exampleCN":"刺突蛋白是主要抗原。"},{"word":"autoantibody","structure":"auto- (self) + antibody","meaning":"an antibody against the self","meaningCN":"针对自身的抗体","example":"Autoantibodies damage the joint lining.","exampleCN":"自身抗体损伤关节内衬。"},{"word":"monoclonal","structure":"mono- (one) + clonal (clone)","meaning":"from a single cell line","meaningCN":"来自单一细胞系的","example":"Monoclonal antibodies are identical copies.","exampleCN":"单克隆抗体是完全相同的拷贝。"},{"word":"polyclonal","structure":"poly- (many) + clonal","meaning":"from many cell lines","meaningCN":"来自多个细胞系的","example":"Polyclonal sera contain many antibodies.","exampleCN":"多克隆血清含多种抗体。"},{"word":"antiserum","structure":"anti- + serum","meaning":"serum containing antibodies","meaningCN":"含抗体的血清","example":"Antiserum was given against the snake venom.","exampleCN":"针对蛇毒给予了抗血清。"},{"word":"immunoglobulin","structure":"immuno- + globulin","meaning":"the protein class of antibodies","meaningCN":"抗体所属的蛋白类别","example":"IgG is the most common immunoglobulin.","exampleCN":"IgG 是最常见的免疫球蛋白。"}],"latinEntries":[{"word":"corpus","structure":"corpus, corporis (n., third declension)","meaning":"body; a physical substance","meaningCN":"身体；实体（英语 body 的拉丁对应词，用于说明 body 一词的来源）"},{"word":"contra","structure":"preposition with accusative","meaning":"against, opposite","meaningCN":"对抗；相对（拉丁语中与希腊 anti 语义对应）"},{"word":"immunis","structure":"in- + munis (adjective)","meaning":"exempt, protected","meaningCN":"被豁免的；受保护的"}]}},{"word":"antigen","ipa_uk":"/ˈæntɪdʒən/","ipa_us":"/ˈæntɪdʒən/","definition_zh":"抗原；抗原物质（能引发免疫应答并被抗体识别的物质）","definition_en":"a substance that the immune system recognises as foreign and responds to by making antibodies","core_image":"病毒表面一个突出的分子结构被抗体牢牢认出","scene":"The antigen on the surface of the virus is what the body first recognises.","sceneCN":"这里 antigen 指「抗原」（第 1 个义项：能被免疫系统识别并引发应答的异物）；句意：病毒表面的抗原是身体最先认出的东西。图中可辨识物件：病毒颗粒、表面蛋白、抗体结合位点、识别箭头。","pos":[{"tag":"n.","zh":"抗原；抗原物质（能引发免疫应答、被抗体或 T 细胞识别的物质）"}],"collocations":[{"phrase":"surface antigen","zh":"表面抗原"},{"phrase":"tumour antigen","zh":"肿瘤抗原"},{"phrase":"blood group antigen","zh":"血型抗原"},{"phrase":"antigen presentation","zh":"抗原提呈"},{"phrase":"rapid antigen test","zh":"抗原快速检测"},{"phrase":"self-antigen","zh":"自身抗原"}],"forms":[{"label":"复数","form":"antigens"},{"label":"形容词","form":"antigenic（抗原性的）"},{"label":"名词（抗原性）","form":"antigenicity（抗原性）"},{"label":"相关名词","form":"antibody（抗体）"},{"label":"复合词","form":"alloantigen（同种抗原）"},{"label":"复合词","form":"autoantigen（自身抗原）"}],"derivatives":[{"word":"antigenic","pos":"adj.","zh":"抗原性的"},{"word":"antigenicity","pos":"n.","zh":"抗原性"},{"word":"autoantigen","pos":"n.","zh":"自身抗原"},{"word":"alloantigen","pos":"n.","zh":"同种抗原"},{"word":"antigenemia","pos":"n.","zh":"抗原血症"}],"senses":[{"no":"01","title":"Immune trigger","titleCN":"抗原：能被免疫系统识别并引发应答的异物","definition":"a substance that the immune system treats as foreign and answers by producing antibodies or activating cells","definitionCN":"被免疫系统视为异物、并通过产生抗体或激活细胞来应答的物质","example":"The antigen on the surface of the virus is what the body first recognises.","exampleCN":"病毒表面的抗原是身体最先认出的东西。","why":"The word is short for antibody-generator: the substance is named by what it makes the body do, not by what it is made of.","whyCN":"这个词是 antibody generator（抗体生成物）的缩写：它按「让身体产生什么」来命名，而不是按自身由什么构成来命名。"},{"no":"02","title":"The recognised structure","titleCN":"抗原决定簇：抗体实际抓住的那一小块结构","definition":"the small part of a molecule that an antibody or a T cell receptor actually recognises and binds","definitionCN":"分子中被抗体或 T 细胞受体实际识别并结合的一小块结构","example":"Only a few amino acids of the protein form the antigen the antibody sees.","exampleCN":"这个蛋白中只有几个氨基酸构成了抗体所见的抗原。","why":"An antibody grips a patch, not a whole molecule, so in laboratory speech the antigen is often the epitope rather than the entire substance.","whyCN":"抗体抓的是一小块而不是整个分子，因此在实验室口语中，抗原常指表位而非整份物质。"},{"no":"03","title":"Surface antigen","titleCN":"表面抗原：病原外表面的识别标记","definition":"an antigen located on the outer surface of a virus or bacterium, often the first target of the immune response","definitionCN":"位于病毒或细菌外表面的抗原，常是免疫应答的首要目标","example":"The surface antigen of the hepatitis B virus is used in the vaccine.","exampleCN":"乙型肝炎病毒表面抗原被用于疫苗。","why":"Whatever sits on the outside is what a cell or antibody meets first, so surface antigens dominate both diagnosis and vaccine design.","whyCN":"外表面的东西是细胞与抗体最先遇到的，因此表面抗原在诊断与疫苗设计中都占主导。"},{"no":"04","title":"Tumour antigen","titleCN":"肿瘤抗原：癌细胞上可被识别的异常分子","definition":"a molecule produced by cancer cells that the immune system can recognise as abnormal and attack","definitionCN":"癌细胞产生、能被免疫系统识别为异常并攻击的分子","example":"Tumour antigens let the immune system tell cancer from normal tissue.","exampleCN":"肿瘤抗原让免疫系统能把癌与正常组织区分开。","why":"A tumour is the body's own tissue altered, so any antigen it presents must be a difference within self, which makes the search difficult and the term important.","whyCN":"肿瘤是被改变的自体组织，因此它呈现的任何抗原都必须是「自我之内的差异」，这使搜索艰难，也使这个术语重要。"},{"no":"05","title":"Blood group antigen","titleCN":"血型抗原：决定输血相容性的红细胞标记","definition":"a carbohydrate or protein marker on red cells that determines blood group and must match in transfusion","definitionCN":"红细胞上决定血型、输血时必须匹配的糖或蛋白标记","example":"The A antigen on her red cells made type O blood dangerous for her.","exampleCN":"她红细胞上的 A 抗原使 O 型血对她有危险。","why":"Blood groups were the first antigens found in humans, and the rules of matching made the idea of a harmless self-marker widely known.","whyCN":"血型是人类最先发现的抗原，配型规则让「无害的自身标记」这一观念广为人知。"},{"no":"06","title":"Self-antigen","titleCN":"自身抗原：被免疫系统误认为目标的自身分子","definition":"a normal molecule of the body's own tissue that the immune system mistakenly treats as foreign","definitionCN":"自身组织中的正常分子，被免疫系统误当作异物","example":"In type 1 diabetes the immune system attacks a self-antigen in the pancreas.","exampleCN":"在 1 型糖尿病中，免疫系统攻击胰腺的一种自身抗原。","why":"The word normally implies foreignness, so attaching self- to it marks the exception: a target that should have been tolerated.","whyCN":"这个词通常意味着异物，因此在它前面加 self- 就标记了例外：一个本应被容忍的目标。"},{"no":"07","title":"Antigen presentation","titleCN":"抗原提呈：把抗原片段展示给免疫细胞","definition":"the process by which a cell displays fragments of an antigen on its surface for immune cells to inspect","definitionCN":"细胞把抗原片段展示在表面、供免疫细胞检查的过程","example":"Antigen presentation is how a dendritic cell shows the enemy to a T cell.","exampleCN":"抗原提呈就是树突状细胞把敌人展示给 T 细胞的方式。","why":"The immune system cannot see inside cells, so it needs a display mechanism; the fixed phrase names that act rather than the molecule.","whyCN":"免疫系统看不进细胞内部，因此需要一套展示机制；这个固定搭配命名的是展示行为，而非分子。"},{"no":"08","title":"Rapid antigen test","titleCN":"抗原快检：直接在样本中检出病原蛋白","definition":"a test that detects a pathogen's antigen directly in a sample, giving a result in minutes","definitionCN":"直接在样本中检出病原抗原、数分钟内出结果的检测","example":"The rapid antigen test was positive before the PCR result arrived.","exampleCN":"抗原快检在核酸检测结果出来之前就已呈阳性。","why":"Detecting the antigen means detecting the germ itself, which is faster than waiting for antibodies, so the word entered everyday medical language.","whyCN":"检出抗原就是检出病原本身，比等抗体出现更快，因此这个词进入了日常医疗语言。"}],"etymology":{"intro":{"en":"Antigen is a German scientific coinage of the 1890s: anti- 'against' plus -gen 'producing', short for 'antibody generator'. English borrowed it almost unchanged.","cn":"antigen 是 19 世纪 90 年代的德语科学新造词：anti-「对抗」加 -gen「产生」，是「抗体生成物」的缩写。英语几乎原样借入。"},"items":[{"era":"GREEK GENES","en":"Greek -genes meant 'born of, produced by', from gignesthai 'to be born'; English uses -gen for things that produce or generate.","cn":"希腊 -genes 意为「由…所生、由…产生」，来自 gignesthai「出生」；英语用 -gen 表示产生某物者。"},{"era":"ANTIBODY RESEARCH","en":"After antibodies were named in the 1890s, researchers needed a word for the substances that provoke their production, especially bacterial toxins and proteins.","cn":"1890 年代抗体得名之后，研究者需要给「促使抗体产生之物」一个词，尤其是细菌毒素与蛋白。"},{"era":"GERMAN ANTIGEN","en":"German coined Antigen as a shortening of 'antibody generator', formed on the model of Antikörper.","cn":"德语造出 Antigen，作为「抗体生成物」的缩略，仿照 Antikörper 的模式构成。"},{"era":"ENGLISH ADOPTION","en":"English took antigen in the late 1890s, and the pair antigen and antibody fixed the two roles: the target and the defender.","cn":"英语于 1890 年代后期引入 antigen，antigen 与 antibody 这一对固定了两种角色：目标与防御者。"},{"era":"CLINICAL EXPANSION","en":"In the twentieth century the word spread to blood groups, tumours, transplantation and rapid tests, always keeping the idea of a target the immune system can see.","cn":"20 世纪这个词扩展到血型、肿瘤、移植与快检，始终保留「免疫系统能看见的目标」这一核心。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertainty: the exact year and the individual coiner of Antigen are not firmly established; the usual late-1890s dating is an approximation.","cn":"来源不确定（仅首见年代与首创者存疑）：Antigen 的确切年份与个人首创者都无定论；通常所说的 1890 年代后期只是约数。"}]},"similar":{"note":{"en":"The first group holds terms built from the same anti- plus -gen pattern; the second holds the immune targets and markers that overlap with antigen.","cn":"第一组是用同样的 anti- 加 -gen 模式构成的词；第二组是与 antigen 语义重叠的免疫目标与标记。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"antibody","ipa":"/ˈæntɪbɒdi/","tag":"the partner","definition":"The protein that binds the antigen; one is the target, the other the responder.","definitionCN":"结合抗原的蛋白；一个是目标，一个是应答者。"},{"word":"antigenic","ipa":"/ˌæntɪˈdʒenɪk/","tag":"the adjective","definition":"Meaning 'able to act as an antigen', as in antigenic drift; it describes a property, not a substance.","definitionCN":"意为「能作为抗原的」，如抗原漂移；它描述属性，而非物质。"},{"word":"pathogen","ipa":"/ˈpæθədʒən/","tag":"the whole germ","definition":"An organism that causes disease; a pathogen carries many antigens but is not itself an antigen.","definitionCN":"引起疾病的生物；病原携带许多抗原，但它本身不是抗原。"},{"word":"antigene","ipa":"/ˈæntɪdʒiːn/","tag":"obsolete spelling","definition":"An older spelling of antigen found in early twentieth-century texts; it is not a different word.","definitionCN":"20 世纪早期文献中的旧拼法，并非另一个词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"epitope","ipa":"/ˈepɪtəʊp/","tag":"the precise patch","definition":"The exact small site on an antigen that an antibody binds; antigen is the whole substance, epitope the part.","definitionCN":"抗原上被抗体结合的确切小位点；antigen 是整份物质，epitope 是其中的一部分。"},{"word":"allergen","ipa":"/ˈælədʒən/","tag":"an antigen that triggers allergy","definition":"A normally harmless substance that provokes an allergic immune response; it is a kind of antigen in effect.","definitionCN":"通常无害却引发过敏性免疫应答的物质；在效应上属于一类抗原。"},{"word":"toxin","ipa":"/ˈtɒksɪn/","tag":"a poison, often antigenic","definition":"A poison produced by an organism; many toxins are antigens, but a toxin is defined by harm rather than by immune recognition.","definitionCN":"生物产生的毒物；许多毒素是抗原，但毒素按危害定义，而非按免疫识别定义。"},{"word":"hapten","ipa":"/ˈhæptən/","tag":"too small alone","definition":"A small molecule that becomes antigenic only after binding to a larger carrier protein.","definitionCN":"只有结合到较大的载体蛋白后才具抗原性的小分子。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"anti- 'against' + -gen 'producing' = 'the thing that produces the against-response'.","cn":"anti-「对抗」+ -gen「产生」=「引发对抗反应的东西」。"},{"en":"antigen and antibody are a fixed pair: target and defender.","cn":"antigen 与 antibody 是固定一对：目标与防御者。"},{"en":"The family runs antigen, antigenic, antigenicity, autoantigen, alloantigen.","cn":"同族词包括 antigen、antigenic、antigenicity、autoantigen、alloantigen。"},{"en":"Fixed phrases mark the setting: surface antigen, tumour antigen, rapid antigen test.","cn":"固定搭配标出场景：表面抗原、肿瘤抗原、抗原快检。"},{"en":"An antigen is what an antibody is against; the prefix anti- appears in both.","cn":"抗原就是抗体所对抗的东西；前缀 anti- 在两个词中都出现。"}],"abstract":[{"en":"Picture a flag on the outside of a germ that the body reads before anything else.","cn":"想象病原外面插着一面旗，身体最先读到的就是它。"},{"en":"Picture a keyhole that exists only so that one particular key can be made for it.","cn":"想象一个锁孔，它存在的意义就是让人为它配一把特定的钥匙。"},{"en":"Picture a photocopied fragment held up for inspection because the cell is too large to open.","cn":"想象一张复印的碎片被举起来供人检查，因为整座细胞大得打不开。"}]},"examples":[{"en":"The vaccine contains an antigen but no live virus.","cn":"疫苗含有抗原，但不含活病毒。"},{"en":"Blood group antigens decide which donor blood a patient can receive.","cn":"血型抗原决定病人能接受哪种供血。"},{"en":"The antigen test turned positive two days after exposure.","cn":"接触两天后抗原检测转为阳性。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「anti 对抗 + gen 产生」——让身体产生对抗物质的东西 → antigen 抗原","word":"antigen"},"root":"希腊 anti「对抗」+ 希腊 -genes「产生」→ 德语 Antigen（抗体生成物）→ 英语 antigen（1890 年代）。","sensesIntro":{"en":"Eight senses follow one visible target: the substance that triggers the response, the small patch actually bound, the surface, tumour and blood-group forms, the misread self-marker, its display to immune cells, and its direct detection in a rapid test.","cn":"八个义项沿一个可见目标展开：触发应答的物质、实际被结合的小块、表面型与肿瘤型及血型型、被误读的自身标记、向免疫细胞的展示，以及快检中的直接检出。"},"semanticMap":{"core":{"en":"CORE IMAGE: a molecule sticking out of a germ, gripped by an antibody.","cn":"核心意象：从病原表面突出的一个分子，被抗体牢牢抓住。"},"chain":["IMMUNE TRIGGER","BOUND PATCH","SURFACE MARKER","TUMOUR MARKER","SELF MARKER","TEST TARGET"],"branches":[{"senses":"S1 · S2","en":"TRIGGER AND PATCH: the whole substance, then the few amino acids an antibody actually touches.","cn":"触发物与小块：整份物质，然后是抗体真正接触到的几个氨基酸。"},{"senses":"S3","en":"THE OUTSIDE: surface antigens are the first things a cell meets.","cn":"外表面：表面抗原是细胞最先遇到的东西。"},{"senses":"S4 · S5","en":"TWO SPECIAL CASES: cancer's altered self, and red cells' group markers.","cn":"两个特例：癌的被改变的自体，以及红细胞的血型标记。"},{"senses":"S6 · S7","en":"SELF AND DISPLAY: a self-antigen is a mistake, and presentation is how a cell shows what it holds.","cn":"自身与展示：自身抗原是一种错误，提呈则是细胞展示所持内容的方式。"},{"senses":"S8","en":"DETECTION: the antigen itself becomes the target of a rapid test.","cn":"检测：抗原本身成为快检的目标。"}]},"affixes":{"intro":{"en":"Antigen is anti- plus -gen, 'producing'; the suffix also builds oxygen, hydrogen and allergen, all words for things that generate something.","cn":"antigen 是 anti- 加 -gen「产生」；这个后缀也构成 oxygen、hydrogen、allergen，都是「产生某物者」的词。"},"latinIntro":{"en":"The anti- element is Greek, and -gen comes from Greek -genes 'born of'; the compound is modern scientific Greek rather than Latin.","cn":"anti- 成分来自希腊语，-gen 来自希腊 -genes「由…所生」；这个复合词是现代科学希腊语，而非拉丁语。"},"items":[{"word":"antigen","structure":"anti- (against) + -gen (producing)","meaning":"an antibody-producing substance","meaningCN":"促使抗体产生的物质","example":"The antigen was purified from the virus.","exampleCN":"抗原从病毒中提纯。"},{"word":"antigens","structure":"antigen + -s (plural)","meaning":"the class, in plural","meaningCN":"抗原（复数）","example":"A single germ carries many antigens.","exampleCN":"一个病原携带许多抗原。"},{"word":"antigenic","structure":"antigen + -ic (relating to)","meaning":"acting as an antigen","meaningCN":"起抗原作用的","example":"The protein is strongly antigenic.","exampleCN":"这种蛋白抗原性很强。"},{"word":"antigenicity","structure":"antigenic + -ity (quality)","meaning":"the power to provoke an immune response","meaningCN":"引发免疫应答的能力","example":"Adjuvants raise antigenicity.","exampleCN":"佐剂能提高抗原性。"},{"word":"autoantigen","structure":"auto- (self) + antigen","meaning":"an antigen from the body itself","meaningCN":"来自自身的抗原","example":"Autoantigens drive lupus.","exampleCN":"自身抗原驱动狼疮。"},{"word":"alloantigen","structure":"allo- (other) + antigen","meaning":"an antigen from another member of the species","meaningCN":"来自同种另一成员的抗原","example":"Alloantigens cause graft rejection.","exampleCN":"同种抗原引起移植物排斥。"},{"word":"antigenemia","structure":"antigen + -emia (blood condition)","meaning":"antigen present in the blood","meaningCN":"血中出现抗原","example":"Antigenemia confirms active infection.","exampleCN":"抗原血症证实活动性感染。"},{"word":"allergen","structure":"allergy + -gen (producing)","meaning":"a substance that produces allergy","meaningCN":"引起变态反应的物质","example":"Pollen is a common allergen.","exampleCN":"花粉是常见的过敏原。"}],"latinEntries":[{"word":"contra","structure":"preposition with accusative","meaning":"against","meaningCN":"对抗（拉丁语中与希腊 anti 语义对应）"},{"word":"generare","structure":"generare (verb, first conjugation)","meaning":"to beget, to produce","meaningCN":"生育；产生"},{"word":"genus","structure":"genus, generis (n., third declension)","meaning":"birth, origin, kind","meaningCN":"出生；来源；种类"}]}},{"word":"infection","ipa_uk":"/ɪnˈfekʃn/","ipa_us":"/ɪnˈfekʃn/","definition_zh":"感染；传染；传染病；感染部位；（计算机）感染","definition_en":"the entry and growth of a germ inside the body, or a disease caused by such a germ","core_image":"一群微小的病原穿过伤口，进入身体并开始繁殖","scene":"The wound became red and swollen because an infection had set in.","sceneCN":"这里 infection 指「感染」（第 1 个义项：病原进入体内并繁殖的过程）；句意：伤口变得红肿，因为感染已经发生。图中可辨识物件：伤口、红肿皮肤、病原颗粒、白细胞。","pos":[{"tag":"n.","zh":"感染；传染；传染病；感染部位；（计算机）病毒感染；思想的感染（比喻）"}],"collocations":[{"phrase":"bacterial infection","zh":"细菌感染"},{"phrase":"viral infection","zh":"病毒感染"},{"phrase":"risk of infection","zh":"感染风险"},{"phrase":"source of infection","zh":"传染源"},{"phrase":"fight off an infection","zh":"抵抗感染"},{"phrase":"hospital-acquired infection","zh":"医院获得性感染"}],"forms":[{"label":"复数","form":"infections"},{"label":"动词","form":"infect（感染；传染）"},{"label":"形容词","form":"infectious（传染的；有感染力的）"},{"label":"形容词","form":"infected（受感染的）"},{"label":"名词（感染性）","form":"infectivity（感染性；感染力）"},{"label":"动词（消毒）","form":"disinfect（消毒）"}],"derivatives":[{"word":"infect","pos":"v.","zh":"感染；传染；使受影响"},{"word":"infectious","pos":"adj.","zh":"传染的；有感染力的"},{"word":"infected","pos":"adj.","zh":"受感染的"},{"word":"infectivity","pos":"n.","zh":"感染性；感染力"},{"word":"disinfect","pos":"v.","zh":"消毒；杀灭病原"}],"senses":[{"no":"01","title":"Invasion by a germ","titleCN":"感染：病原进入体内并繁殖的过程","definition":"the process by which a germ enters the body, settles in a tissue and multiplies there","definitionCN":"病原进入身体、定位于某一组织并在其中繁殖的过程","example":"The wound became red and swollen because an infection had set in.","exampleCN":"伤口变得红肿，因为感染已经发生。","why":"Latin inficere meant 'to put into, to dye', and the medical sense keeps that picture: something is put into the body and spreads through it like dye through cloth.","whyCN":"拉丁 inficere 意为「放入、染色」，医学义保留了这幅画面：某物被放进身体，像染料浸透布一样在其中扩散。"},{"no":"02","title":"A disease so caused","titleCN":"传染病：由病原引起的一种疾病","definition":"a disease caused by a germ, especially one that can be treated or must be reported","definitionCN":"由病原引起的疾病，尤指需要治疗或必须上报的疾病","example":"She missed two weeks of school with a chest infection.","exampleCN":"她因胸部感染缺课两周。","why":"English uses the process word for the illness itself because the cause and the condition are hard to separate in ordinary speech.","whyCN":"英语用表示过程的词来指疾病本身，因为在日常语言中病因与病况很难分开。"},{"no":"03","title":"Transmission event","titleCN":"传染：病原从一个人传到另一个人的事件","definition":"the passing of a germ from one person, animal or surface to another","definitionCN":"病原从一个人、动物或物体表面传到另一处的过程","example":"The infection spread through the ward within a week.","exampleCN":"感染在一周内传遍了整个病房。","why":"Spread is the most visible part of the process, so the same noun names the event of passing on as well as the state of being invaded.","whyCN":"扩散是这一过程最可见的部分，因此同一个名词既指被侵入的状态，也指传播这一事件。"},{"no":"04","title":"A localised site","titleCN":"感染灶：局限在某一部位的感染","definition":"a confined infection in one place, such as a wound, the bladder or a joint","definitionCN":"局限于某一处的感染，如伤口、膀胱或关节","example":"The doctor drained the infection in his knee.","exampleCN":"医生把他膝部的感染引流了。","why":"Once a site can be examined and drained, the abstract process becomes a countable object, and clinicians speak of 'an infection' in a place.","whyCN":"当一个部位可以被检查与引流，抽象过程就变成了可数对象，临床医生便说「某处有一个感染」。"},{"no":"05","title":"Systemic infection","titleCN":"全身性感染：病原或其产物进入血液","definition":"an infection that has spread beyond its starting point into the blood or the whole body","definitionCN":"已超出起始部位、进入血液或波及全身的感染","example":"A local infection can become systemic if it is left untreated.","exampleCN":"局部感染若不治疗，可能变成全身性感染。","why":"The body is treated as a space with a boundary; when the germ crosses that boundary, the same word gains a severity it did not have before.","whyCN":"身体被看作一个有边界的空间；当病原越过这个边界，同一个词就获得了此前没有的严重程度。"},{"no":"06","title":"Hospital-acquired infection","titleCN":"医院获得性感染：住院期间新发生的感染","definition":"an infection a patient acquires during medical care that was not present on arrival","definitionCN":"患者在接受医疗期间新获得、入院时并不存在的感染","example":"Hand washing sharply reduced hospital-acquired infections.","exampleCN":"勤洗手大幅减少了医院获得性感染。","why":"Hospitals concentrate sick people and invasive devices, so transmission there became a distinct problem with its own name.","whyCN":"医院集中了病人与侵入性器械，因此那里的传播成了有专名的独立问题。"},{"no":"07","title":"Computer infection","titleCN":"计算机感染：恶意程序潜入系统并扩散","definition":"the entry and spread of malicious software in a computer system, named by analogy with disease","definitionCN":"恶意软件进入计算机系统并扩散，借用疾病传播的比喻命名","example":"The lab lost a week of data to a computer infection.","exampleCN":"实验室因一次计算机感染损失了一周的数据。","why":"A program that copies itself inside a host and spreads to others behaves like a germ, so the medical vocabulary was borrowed wholesale.","whyCN":"一个在宿主内自我复制并传给其他系统的程序，行为像病原，于是医学术语被整套借走。"},{"no":"08","title":"Contagion of ideas","titleCN":"思想的感染：观念、情绪在人群中蔓延","definition":"the spread of an idea, a mood or a habit through a group, pictured as a disease passing between people","definitionCN":"观念、情绪或习惯在群体中扩散，被想象为疾病在人际间传递","example":"Panic is an infection that travels faster than any virus.","exampleCN":"恐慌是一种传播得比任何病毒都快的感染。","why":"The metaphor works because both germs and ideas need carriers and both spread faster in close contact, so 'infection' became a word for social contagion.","whyCN":"这个比喻成立，是因为病原与观念都需要载体，且都在密切接触中传得更快，于是 infection 成了社会性传染的词。"}],"etymology":{"intro":{"en":"Infection comes from Latin infectio, a dyeing or staining, from inficere 'to put into, to dip, to taint'. The modern medical sense grew out of the idea of a body being stained from within.","cn":"infection 来自拉丁 infectio「染色、污染」，源于 inficere「放入、浸入、使染污」。现代医学义正是从「身体从内部被染污」这一意象生长出来的。"},"items":[{"era":"LATIN FACERE","en":"Facere meant 'to make, to do, to put'; it is the verb behind factory, effect and defect, and its past participle factus shaped a large family.","cn":"facere 意为「做、造、放置」；它是 factory、effect、defect 背后的动词，其过去分词 factus 塑造了一个庞大的词族。"},{"era":"LATIN INFICERE","en":"In- 'into' plus facere gave inficere, literally 'to put into'. It was used for dipping cloth into dye, and from that for staining, tainting and poisoning.","cn":"in-「进入」加 facere 得 inficere，字面即「放入」。它用于把布浸入染料，由此引申为染色、污染、下毒。"},{"era":"LATIN INFECTIO","en":"The noun infectio named the act of dyeing or staining, and by extension a taint or contamination, including contamination of the body.","cn":"名词 infectio 指染色或污染的动作，并引申为沾染、污损，包括身体受到污染。"},{"era":"MEDIEVAL AND EARLY MODERN ENGLISH","en":"English infection appears in the fourteenth century; plague writing of the sixteenth and seventeenth centuries made it a common word for a disease passed between people.","cn":"英语 infection 出现于 14 世纪；16、17 世纪的瘟疫文献使它成为指人际传播疾病的常用词。"},{"era":"GERM THEORY","en":"In the nineteenth century, when specific microbes were shown to cause specific diseases, infection was fixed to the entry and growth of those organisms.","cn":"19 世纪，当特定微生物被证明引起特定疾病后，infection 被固定为这些生物进入并繁殖的过程。"},{"era":"MODERN EXTENSION","en":"Twentieth-century computing and social writing extended the word to malicious code and to the spread of ideas, both still felt as metaphors.","cn":"20 世纪的计算机与社会写作把这个词扩展到恶意代码与观念传播，两者至今仍被感觉是比喻。"}]},"similar":{"note":{"en":"The first group holds words built on the same Latin verb or differing only in ending; the second holds medical and figurative terms that overlap with infection.","cn":"第一组是建立在同一拉丁动词上、或只差词尾的词；第二组是与 infection 语义重叠的医学与比喻术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"infect","ipa":"/ɪnˈfekt/","tag":"the verb","definition":"To give a germ to someone or something; infection is the process or the resulting state.","definitionCN":"把病原传给某人或某物；infection 是过程或由此形成的状态。"},{"word":"infectious","ipa":"/ɪnˈfekʃəs/","tag":"the adjective","definition":"Able to be passed on to others; it describes a disease or a person, not the invasion itself.","definitionCN":"能够传给他人；它描述疾病或人，而非侵入过程本身。"},{"word":"infestation","ipa":"/ˌɪnfeˈsteɪʃn/","tag":"large animals, not germs","definition":"The presence of parasites such as lice or insects on a body or in a place; it is not a microbial infection.","definitionCN":"虱、昆虫等较大寄生虫在身体或某处的存在；它不是微生物感染。"},{"word":"inflammation","ipa":"/ˌɪnfləˈmeɪʃn/","tag":"the response, not the cause","definition":"The body's reaction to injury or infection, marked by heat, pain and swelling; it can occur without a germ.","definitionCN":"身体对损伤或感染的反应，表现为热、痛、肿；它可以没有病原而发生。"}]},{"heading":"NEAR MEANING","entries":[{"word":"contagion","ipa":"/kənˈteɪdʒən/","tag":"spread by contact","definition":"The passing of a disease by direct or indirect contact; infection is the broader term for invasion itself.","definitionCN":"疾病经直接或间接接触传播；infection 是更宽泛的「侵入」术语。"},{"word":"disease","ipa":"/dɪˈziːz/","tag":"the condition, not the cause","definition":"An abnormal condition of the body with a definite set of signs; a disease may or may not be caused by infection.","definitionCN":"具有一组明确体征的身体异常状态；疾病可能由感染引起，也可能不。"},{"word":"sepsis","ipa":"/ˈsepsɪs/","tag":"the dangerous stage","definition":"A life-threatening whole-body response to infection; it is the severe end of the infection spectrum.","definitionCN":"对感染产生的危及生命的全身反应；它是感染谱系中最严重的一端。"},{"word":"colonisation","ipa":"/ˌkɒlənaɪˈzeɪʃn/","tag":"presence without harm","definition":"The stable presence of germs on or in a body without invasion or symptoms; infection implies damage or response.","definitionCN":"微生物在体表或体内稳定存在而无侵入或症状；infection 则意味着损害或反应。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"in- 'into' + facere 'put' gives inficere 'put into', the literal origin of infection.","cn":"in-「进入」+ facere「放」得 inficere「放入」，这就是 infection 的字面来源。"},{"en":"The family runs infect, infection, infectious, infected, infectivity, disinfect.","cn":"同族词包括 infect、infection、infectious、infected、infectivity、disinfect。"},{"en":"Fixed phrases name the source: bacterial infection, viral infection, source of infection.","cn":"固定搭配命名来源：细菌感染、病毒感染、传染源。"},{"en":"infection is the noun, infect is the verb, infectious is the adjective: choose by grammar, not by sound.","cn":"infection 是名词，infect 是动词，infectious 是形容词：按语法而非读音选用。"},{"en":"Same word, new hosts: computer infection and the infection of panic.","cn":"同一个词，新的宿主：计算机感染与恐慌的感染。"}],"abstract":[{"en":"Picture a drop of dye entering a cloth and slowly taking over the whole square.","cn":"想象一滴染料落进布中，慢慢占满整块方形。"},{"en":"Picture a small fire spreading along a floor that has not been cleaned.","cn":"想象一点火沿未清理的地面蔓延。"},{"en":"Picture a mood moving across a crowded room without anyone touching.","cn":"想象一种情绪穿过拥挤的房间，没有人接触却都染上了。"}]},"examples":[{"en":"Wash your hands to lower the risk of infection.","cn":"洗手以降低感染风险。"},{"en":"The infection responded quickly to antibiotics.","cn":"感染对抗生素反应很快。"},{"en":"The company called the leak an infection of its network.","cn":"公司把这次泄露称为其网络的感染。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「in 进入 + fect 做／放」——有东西被放进了身体并在里面繁殖 → infection 感染","word":"infection"},"root":"拉丁 in-「进入」+ facere「放；做」→ inficere「浸入、染污」→ infectio「染色；污染」→ 英语 infection（14 世纪）。","sensesIntro":{"en":"Eight senses follow one entry: the germ entering and growing, the illness it causes, the passing from person to person, a confined site, a whole-body spread, a hospital form, a computer form, and finally an idea spreading like a mood.","cn":"八个义项沿同一次进入展开：病原进入并繁殖、由此引起的疾病、人际传播、局限的感染灶、全身扩散、医院内的形式、计算机形式，最后是像情绪一样扩散的观念。"},"semanticMap":{"core":{"en":"CORE IMAGE: germs crossing a break in the skin and settling inside.","cn":"核心意象：病原越过皮肤的破口，落脚在身体内部。"},"chain":["GERM ENTERS","ILLNESS FOLLOWS","PASSES TO OTHERS","SETTLES IN ONE SITE","SPREADS SYSTEMIC","SPREADS BEYOND BODY"],"branches":[{"senses":"S1 · S2","en":"PROCESS AND RESULT: the invasion itself, then the disease it leaves behind.","cn":"过程与结果：侵入本身，然后是它留下的疾病。"},{"senses":"S3","en":"BETWEEN PEOPLE: the same noun names the event of transmission.","cn":"人与人之间：同一个名词也命名传播事件。"},{"senses":"S4 · S5","en":"FROM A POINT TO THE WHOLE: a wound or bladder can hold it, or it can enter the blood.","cn":"从一点到全身：它可局限于伤口或膀胱，也可进入血液。"},{"senses":"S6","en":"THE HOSPITAL: crowded care creates its own pattern of spread.","cn":"医院：密集的照护造出自身的传播模式。"},{"senses":"S7 · S8","en":"NEW HOSTS: code and ideas are infected in the same grammar as bodies.","cn":"新的宿主：代码与观念用与身体相同的语法被「感染」。"}]},"affixes":{"intro":{"en":"Infection is in- 'into' plus facere 'put' plus -tio, a noun of action; the same pieces build inflect and inject with different verbs.","cn":"infection 是 in-「进入」加 facere「放」再加 -tio（动作名词后缀）；同样的部件配不同动词还造出 inflect、inject。"},"latinIntro":{"en":"Latin inficere, infectio and infectus supply the family; dis- and re- build disinfect and reinfect from the same stem.","cn":"拉丁 inficere、infectio、infectus 提供词族；dis- 与 re- 在同一词干上造出 disinfect、reinfect。"},"items":[{"word":"infection","structure":"in- (into) + facere (put) + -tio (action noun)","meaning":"the act of putting something in; invasion by germs","meaningCN":"放入的动作；病原侵入","example":"The infection cleared after ten days.","exampleCN":"感染在十天后消退。"},{"word":"infect","structure":"in- + facere (verb)","meaning":"to give a germ to","meaningCN":"使感染；传染","example":"The virus infects the cells of the throat.","exampleCN":"病毒感染喉部细胞。"},{"word":"infectious","structure":"infectio + -osus (full of)","meaning":"able to be passed on","meaningCN":"能传播的","example":"The patient was infectious for five days.","exampleCN":"该病人有五天具有传染性。"},{"word":"infected","structure":"infect + -ed (past participle)","meaning":"having received a germ","meaningCN":"已受感染的","example":"The infected tissue was removed.","exampleCN":"受感染的组织被切除。"},{"word":"infectivity","structure":"infective + -ity (quality)","meaning":"the power to infect","meaningCN":"感染能力","example":"Infectivity varies between strains.","exampleCN":"不同毒株的感染力不同。"},{"word":"disinfect","structure":"dis- (apart, away) + infect","meaning":"to remove or kill germs","meaningCN":"消毒；杀灭病原","example":"Disinfect the bench before you start.","exampleCN":"开始前先给工作台消毒。"},{"word":"disinfectant","structure":"disinfect + -ant (agent)","meaning":"a germ-killing substance","meaningCN":"消毒剂","example":"The disinfectant smelled of chlorine.","exampleCN":"消毒剂有股氯味。"},{"word":"reinfect","structure":"re- (again) + infect","meaning":"to infect once more","meaningCN":"再次感染","example":"The same strain can reinfect a person.","exampleCN":"同一毒株可使人再次感染。"}],"latinEntries":[{"word":"facere","structure":"facere (verb, third conjugation; passive fieri)","meaning":"to make, to do, to put","meaningCN":"做；造；放置"},{"word":"inficere","structure":"in- + facere (verb, third conjugation)","meaning":"to dip in, to dye, to stain, to taint","meaningCN":"浸入；染色；污染"},{"word":"infectio","structure":"inficere + -tio (f., third declension)","meaning":"a dyeing; a staining; infection","meaningCN":"染色；污染；感染"}]}},{"word":"infectious","ipa_uk":"/ɪnˈfekʃəs/","ipa_us":"/ɪnˈfekʃəs/","definition_zh":"传染的；传染性的；有感染力的；易传播的","definition_en":"able to be passed from one person or organism to another, or able to spread quickly to other people","core_image":"一个人咳嗽，看不见的病原随空气飘向周围的人","scene":"Measles is highly infectious, so the whole class was sent home.","sceneCN":"这里 infectious 指「传染性的」（第 1 个义项：疾病能在人际间传播的性质）；句意：麻疹传染性很强，所以全班都被遣送回家。图中可辨识物件：咳嗽的人、空气飞沫、周围同学、隔离标志。","pos":[{"tag":"adj.","zh":"传染的；传染性的；（病人）能传播病原的；有感染力的；易传播的"}],"collocations":[{"phrase":"infectious disease","zh":"传染病"},{"phrase":"highly infectious","zh":"传染性很强"},{"phrase":"infectious agent","zh":"传染性病原"},{"phrase":"infectious period","zh":"传染期"},{"phrase":"infectious laughter","zh":"有感染力的笑声"},{"phrase":"infectious waste","zh":"感染性废弃物"}],"forms":[{"label":"名词（感染）","form":"infection（感染）"},{"label":"动词","form":"infect（感染）"},{"label":"名词（传染性）","form":"infectiousness（传染性）"},{"label":"副词","form":"infectiously（有感染力地）"},{"label":"比较级","form":"more infectious（较少用）"},{"label":"最高级","form":"most infectious（较少用）"}],"derivatives":[{"word":"infection","pos":"n.","zh":"感染；传染病"},{"word":"infect","pos":"v.","zh":"感染；传染"},{"word":"infectiousness","pos":"n.","zh":"传染性"},{"word":"infectiously","pos":"adv.","zh":"有感染力地"},{"word":"noninfectious","pos":"adj.","zh":"非传染性的"}],"senses":[{"no":"01","title":"Able to be transmitted","titleCN":"传染的：能在人际或个体间传播的","definition":"describing a disease or germ that can pass from one person or organism to another","definitionCN":"描述能在人或生物个体之间传递的疾病或病原","example":"Measles is highly infectious, so the whole class was sent home.","exampleCN":"麻疹传染性很强，所以全班都被遣送回家。","why":"The suffix -ous turns infection into a property, and the property is simply transmissibility: can this disease leave one body and enter another?","whyCN":"后缀 -ous 把 infection 变成一种属性，而这种属性就是可传播性：这种病能否离开一个身体进入另一个身体？"},{"no":"02","title":"Caused by a germ","titleCN":"感染性的：由病原引起的（疾病）","definition":"describing a disease caused by a germ, as opposed to one caused by genetics, diet or injury","definitionCN":"描述由病原引起的疾病，与遗传、饮食或损伤所致者相对","example":"Cholera is an infectious disease, not a poisoning.","exampleCN":"霍乱是一种传染病，而不是中毒。","why":"Once the cause was known, doctors needed to separate diseases by origin, and infectious became a category label rather than only a warning.","whyCN":"病因被弄清后，医生需要按来源区分疾病，infectious 便从警告语变成分类标签。"},{"no":"03","title":"Able to pass it on","titleCN":"有传染性的：病人当下能把病原传出去","definition":"describing a person or animal that is currently able to transmit a germ to others","definitionCN":"描述当前能把病原传给他人的人或动物","example":"He stayed home while he was still infectious.","exampleCN":"他仍有传染性时留在家里。","why":"The adjective moves easily from the disease to its carrier, because what matters in a household is whether this person can give it to someone else today.","whyCN":"这个形容词很自然地从疾病转到携带者，因为在一个家庭里真正要紧的是：这个人今天能不能把它传给别人。"},{"no":"04","title":"Infectious agent or dose","titleCN":"具感染力的：指病原本身或所需剂量","definition":"used of the germ or the amount needed, as in infectious agent, infectious dose, infectious clone","definitionCN":"用于病原本身或所需剂量，如传染性病原、感染剂量、感染性克隆","example":"Even a very small infectious dose can start an outbreak.","exampleCN":"极小的感染剂量就能引发一次暴发。","why":"Laboratory work needs to say whether a preparation can actually start an infection, so the adjective attaches to the material rather than to a person.","whyCN":"实验室工作需要说明某份材料是否真能引发感染，因此这个形容词附着在材料上，而不是人身上。"},{"no":"05","title":"Spreading laughter","titleCN":"有感染力的：笑声、打哈欠等会传给旁人","definition":"describing a laugh, a yawn or a mood that spreads spontaneously to other people","definitionCN":"描述笑声、哈欠或情绪自发地传给他人","example":"Her laugh was so infectious that the whole room joined in.","exampleCN":"她的笑声太有感染力，整个房间的人都跟着笑了。","why":"The medical metaphor is so natural that it survived the loss of any germ: something passes from person to person without being seen, exactly like an infection.","whyCN":"这个医学比喻自然到即使没有任何病原也依然成立：某物在人与人之间无形地传递，正如感染。"},{"no":"06","title":"Infectious enthusiasm","titleCN":"有感染力的热情：情绪带动他人","definition":"describing enthusiasm, energy or optimism that makes other people feel the same","definitionCN":"描述能让他人产生同样感受的热情、活力或乐观","example":"The coach's infectious enthusiasm lifted the whole team.","exampleCN":"教练那有感染力的热情鼓舞了整支队伍。","why":"Emotion is the clearest case of social contagion: no contact is needed, yet the state is copied, so the word fits without strain.","whyCN":"情绪是社会传染最清楚的例子：无需接触，状态却被复制，因此这个词用得毫不勉强。"},{"no":"07","title":"Infectious waste or material","titleCN":"感染性的：可能传播病原的废弃物或物品","definition":"describing waste, laundry or equipment that may carry a germ and must be handled specially","definitionCN":"描述可能携带病原、须特殊处理的废弃物、织物或器械","example":"Infectious waste is burned in a separate incinerator.","exampleCN":"感染性废弃物在单独的焚化炉中焚烧。","why":"Hospital rules need a label for objects, not people, and 'may transmit a germ' is exactly what the adjective already says.","whyCN":"医院规章需要给物品而非人一个标签，而「可能传播病原」正是这个形容词已有的意思。"},{"no":"08","title":"Infectious clone","titleCN":"感染性克隆：由实验室重建、仍能引发感染的病毒","definition":"in virology, a laboratory-made copy of a virus genome that is still able to start an infection","definitionCN":"病毒学中指实验室重建、仍能引发感染的病毒基因组拷贝","example":"The team built an infectious clone to study the virus safely.","exampleCN":"团队构建了一个感染性克隆，以便安全地研究该病毒。","why":"A synthetic genome that produces no virus is useless for experiments, so the adjective marks the crucial test: does it still infect?","whyCN":"不能产生病毒的合成基因组对实验毫无用处，因此这个形容词标记了关键检验：它还能感染吗？"}],"etymology":{"intro":{"en":"Infectious is Latin infectiosus 'contagious', formed from infectio with the suffix -osus 'full of'. It reached English in the sixteenth century as a medical adjective.","cn":"infectious 是拉丁 infectiosus「有传染性的」，由 infectio 加后缀 -osus「充满」构成。它于 16 世纪作为医学形容词进入英语。"},"items":[{"era":"LATIN INFECTIO","en":"Infectio named a dyeing, a staining or a contamination; the word carried the image of something spreading through a material.","cn":"infectio 指染色、污染或沾染；这个词带着「某物在材料中扩散」的画面。"},{"era":"LATIN INFECTIOSUS","en":"The adjective infectiosus meant 'full of infection, contagious', and was used of diseases and of air believed to carry them.","cn":"形容词 infectiosus 意为「充满感染、有传染性的」，用于疾病，也用于被认为携带疾病的空气。"},{"era":"ENGLISH 16C","en":"English infectious is recorded in the sixteenth century, in medical and plague writing, where it described both diseases and the sick people who spread them.","cn":"英语 infectious 记录于 16 世纪的医学与瘟疫文献，既描述疾病，也描述传播疾病的病人。"},{"era":"GERM THEORY","en":"In the nineteenth century the adjective was tied to specific microbes, and public health began to use it for people, waste and materials as well as for diseases.","cn":"19 世纪这个形容词与具体微生物绑定，公共卫生开始用它描述人、废弃物与物品，而不仅是疾病。"},{"era":"FIGURATIVE EXTENSION","en":"The sense 'spreading to other people' is old but expanded in modern English: laughter, enthusiasm and moods are now routinely called infectious.","cn":"「传给他人」的义项本已存在，但在现代英语中扩大：笑声、热情与情绪如今常被称为有感染力。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertainty: the exact sixteenth-century first citation of infectious is not firmly fixed, and the dating of the figurative sense is only approximate.","cn":"来源不确定（仅首见年代存疑）：infectious 在 16 世纪的确切首条书证无定论，比喻义的出现年代也只是约数。"}]},"similar":{"note":{"en":"The first group holds words from the same stem or with a similar ending; the second holds adjectives and nouns that overlap with infectious in medicine and in general use.","cn":"第一组是同词干或词尾相近的词；第二组是在医学与日常用法中与 infectious 重叠的形容词与名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"infection","ipa":"/ɪnˈfekʃn/","tag":"the noun","definition":"The invasion or the disease itself; infectious is the property of being able to pass it on.","definitionCN":"指侵入过程或疾病本身；infectious 是「能够传播」这一属性。"},{"word":"infective","ipa":"/ɪnˈfektɪv/","tag":"technical doublet","definition":"A more technical synonym meaning 'able to cause infection', used of agents and doses; infectious is the everyday word.","definitionCN":"更技术化的同义词，意为「能引起感染的」，用于病原与剂量；infectious 是日常用词。"},{"word":"infectious vs. infective","ipa":"/ɪnˈfektɪv/","tag":"one letter apart","definition":"Infectious usually means transmissible between hosts; infective stresses the capacity to enter a host at all.","definitionCN":"infectious 通常指宿主间可传播；infective 强调能进入宿主这一能力。"},{"word":"infected","ipa":"/ɪnˈfektɪd/","tag":"the state, not the ability","definition":"Having a germ inside; an infected person may or may not be infectious.","definitionCN":"体内带病原；受感染者可能具传染性，也可能不具。"}]},{"heading":"NEAR MEANING","entries":[{"word":"contagious","ipa":"/kənˈteɪdʒəs/","tag":"spread by contact","definition":"Spread by direct or indirect contact; it is narrower than infectious, which includes airborne and vector-borne spread.","definitionCN":"经直接或间接接触传播；比 infectious 窄，后者包括空气与媒介传播。"},{"word":"transmissible","ipa":"/trænzˈmɪsəbl/","tag":"the neutral technical term","definition":"Able to be transmitted, used in regulation and research without the emotional colour of infectious.","definitionCN":"能被传播的，用于法规与研究，不带 infectious 的情绪色彩。"},{"word":"communicable","ipa":"/kəˈmjuːnɪkəbl/","tag":"public health term","definition":"A public health word for a disease that can pass from person to person; it often appears in official lists.","definitionCN":"公共卫生用语，指可在人际传播的疾病，常见于官方名录。"},{"word":"catching","ipa":"/ˈkætʃɪŋ/","tag":"informal","definition":"The everyday word for 'easy to catch', used in speech; it is informal where infectious is clinical.","definitionCN":"口语中表示「容易染上」的日常词；infectious 则偏临床。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"infection + -ous 'full of' gives 'full of the ability to pass on'.","cn":"infection + -ous「充满」得出「充满传播能力」。"},{"en":"The family runs infect, infection, infectious, infectiousness, infectiously, noninfectious.","cn":"同族词包括 infect、infection、infectious、infectiousness、infectiously、noninfectious。"},{"en":"Fixed phrases mark public health: infectious disease, infectious period, infectious agent.","cn":"固定搭配标出公共卫生语境：传染病、传染期、传染性病原。"},{"en":"infectious is said of both the disease and the person: the disease is infectious, the patient is infectious.","cn":"infectious 既可说病，也可说人：疾病有传染性，病人有传染性。"},{"en":"The figurative use is fixed: infectious laughter, infectious enthusiasm.","cn":"比喻用法是固定的：有感染力的笑声、有感染力的热情。"}],"abstract":[{"en":"Picture a laugh jumping from table to table without anyone carrying it.","cn":"想象一阵笑声在桌子之间跳跃，却没有人搬运它。"},{"en":"Picture a room where one cough changes the air for everyone.","cn":"想象一个房间，一声咳嗽改变了所有人的空气。"},{"en":"Picture a label on a bag that says 'handle me as if I could speak'.","cn":"想象一只袋子上的标签写着「请当作它会说话那样处理我」。"}]},"examples":[{"en":"The infectious period begins before the rash appears.","cn":"传染期在皮疹出现之前就已开始。"},{"en":"Her enthusiasm for the project was infectious.","cn":"她对这个项目的热情很有感染力。"},{"en":"Infectious waste must be separated from ordinary rubbish.","cn":"感染性废弃物必须与普通垃圾分开。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「infection 感染 + ous …的」——带着能传出去的感染 → infectious 传染的","word":"infectious"},"root":"拉丁 infectio「染色；污染」→ 拉丁 infectiosus「有传染性的」→ 英语 infectious（16 世纪）。","sensesIntro":{"en":"Eight senses follow one property: a disease that can pass on, a disease caused by germs, a person who can pass it on, the agent or dose that starts it, laughter and enthusiasm that spread, waste that must be handled with care, and a rebuilt virus that still infects.","cn":"八个义项沿同一种属性展开：可传播的疾病、由病原引起的疾病、能传播的病人、能引发感染的病原或剂量、会扩散的笑声与热情、须谨慎处理的废弃物，以及仍能感染的实验室重建病毒。"},"semanticMap":{"core":{"en":"CORE IMAGE: an invisible germ leaving one body and entering another.","cn":"核心意象：看不见的病原离开一个身体，进入另一个身体。"},"chain":["CAN BE PASSED ON","CAUSED BY GERMS","PERSON PASSES IT ON","AGENT OR DOSE","LAUGHTER SPREADS","MATERIAL WITH GERMS"],"branches":[{"senses":"S1 · S2","en":"THE DISEASE: transmissibility, and the category of germ-caused illness.","cn":"疾病：可传播性，以及由病原引起的疾病类别。"},{"senses":"S3","en":"THE CARRIER: a person who can give it away today.","cn":"携带者：今天能把病传出去的人。"},{"senses":"S4 · S8","en":"THE MATERIAL: the germ, the dose, and the rebuilt genome all answer the same test.","cn":"材料：病原、剂量与重建基因组都要通过同一项检验。"},{"senses":"S5 · S6","en":"SOCIAL SPREAD: laughter and enthusiasm pass without any germ at all.","cn":"社会传播：笑声与热情在完全没有病原的情况下传递。"},{"senses":"S7","en":"OBJECTS: waste and equipment can carry what a person carries.","cn":"物品：废弃物与器械能携带人所能携带的东西。"}]},"affixes":{"intro":{"en":"Infectious is infectio plus -osus 'full of'; the adjective has an adverb in -ly, a noun in -ness, and a negative in non-.","cn":"infectious 是 infectio 加 -osus「充满」；这个形容词有 -ly 副词、-ness 名词，以及 non- 否定形式。"},"latinIntro":{"en":"The Latin base inficere 'to stain, to taint' is shared with infection, infect and disinfect; -osus is the same suffix seen in dangerous and curious.","cn":"拉丁词基 inficere「染色、污染」与 infection、infect、disinfect 共享；-osus 与 dangerous、curious 中的后缀相同。"},"items":[{"word":"infectious","structure":"infectio + -osus (full of)","meaning":"full of the power to infect","meaningCN":"充满感染力的","example":"The strain is highly infectious.","exampleCN":"该毒株传染性很强。"},{"word":"infect","structure":"in- + facere (verb)","meaning":"to transmit a germ to","meaningCN":"把病原传给","example":"The bite infected the wound.","exampleCN":"咬伤使伤口感染。"},{"word":"infection","structure":"inficere + -tio (action noun)","meaning":"the invasion or the disease","meaningCN":"侵入或疾病","example":"The infection lasted three weeks.","exampleCN":"感染持续了三周。"},{"word":"infectiously","structure":"infectious + -ly (adverb)","meaning":"in a spreading manner","meaningCN":"有感染力地","example":"She laughed infectiously.","exampleCN":"她笑得很有感染力。"},{"word":"infectiousness","structure":"infectious + -ness (quality)","meaning":"the quality of being infectious","meaningCN":"传染性","example":"Infectiousness falls as antibodies rise.","exampleCN":"随着抗体上升，传染性下降。"},{"word":"noninfectious","structure":"non- (not) + infectious","meaning":"not able to be passed on","meaningCN":"非传染性的","example":"The rash is noninfectious.","exampleCN":"这种皮疹不传染。"},{"word":"infective","structure":"infect + -ive (tending to)","meaning":"able to enter a host","meaningCN":"能进入宿主的","example":"The infective stage of the parasite is the larva.","exampleCN":"该寄生虫的感染阶段是幼虫。"},{"word":"disinfect","structure":"dis- (away) + infect","meaning":"to remove germs","meaningCN":"去除病原","example":"They disinfected the room after the patient left.","exampleCN":"病人离开后他们给房间消了毒。"}],"latinEntries":[{"word":"inficere","structure":"in- + facere (verb, third conjugation)","meaning":"to dip in, to stain, to taint","meaningCN":"浸入；染色；污染"},{"word":"infectio","structure":"inficere + -tio (f., third declension)","meaning":"a staining; infection","meaningCN":"染色；感染"},{"word":"infectiosus","structure":"infectio + -osus (adjective)","meaning":"contagious, full of infection","meaningCN":"有传染性的；充满感染的"}]}},{"word":"infectiousness","ipa_uk":"/ɪnˈfekʃəsnəs/","ipa_us":"/ɪnˈfekʃəsnəs/","definition_zh":"传染性；感染力（情绪、笑声等传播的能力）","definition_en":"the quality of being able to pass a disease to others, or of spreading quickly from person to person","core_image":"一个看不见的刻度表，量出某样东西能传多远、传多快","scene":"The infectiousness of the virus peaked in the first days of illness.","sceneCN":"这里 infectiousness 指「传染性」（第 1 个义项：疾病或病原向他人传播的能力）；句意：这种病毒的传染性在发病最初几天达到高峰。图中可辨识物件：病毒颗粒、传播箭头、时间曲线、人群。","pos":[{"tag":"n.","zh":"传染性；感染力；（情绪、笑声、观念等的）传播能力"}],"collocations":[{"phrase":"high infectiousness","zh":"高传染性"},{"phrase":"reduce infectiousness","zh":"降低传染性"},{"phrase":"peak infectiousness","zh":"传染性高峰"},{"phrase":"measure infectiousness","zh":"测量传染性"},{"phrase":"the infectiousness of laughter","zh":"笑声的感染力"},{"phrase":"viral infectiousness","zh":"病毒的传染性"}],"forms":[{"label":"形容词","form":"infectious（传染的；有感染力的）"},{"label":"副词","form":"infectiously（有感染力地）"},{"label":"名词（感染）","form":"infection（感染）"},{"label":"动词","form":"infect（感染）"},{"label":"同义技术词","form":"transmissibility（可传播性）"},{"label":"相关技术词","form":"infectivity（感染力）"}],"derivatives":[{"word":"infectious","pos":"adj.","zh":"传染的；有感染力的"},{"word":"infectiously","pos":"adv.","zh":"有感染力地"},{"word":"infect","pos":"v.","zh":"感染；传染"},{"word":"infection","pos":"n.","zh":"感染；传染病"},{"word":"noninfectiousness","pos":"n.","zh":"非传染性（罕用）"}],"senses":[{"no":"01","title":"Transmissibility of a disease","titleCN":"传染性：疾病在人际间传播的能力","definition":"the degree to which a disease can pass from one person to another","definitionCN":"一种疾病从一个人传给另一个人的能力程度","example":"The infectiousness of the virus peaked in the first days of illness.","exampleCN":"这种病毒的传染性在发病最初几天达到高峰。","why":"-ness turns the adjective into a measurable quantity: not just 'can it spread', but 'how readily does it spread'.","whyCN":"-ness 把形容词变成可测量的量：不只是「能不能传」，而是「多容易传」。"},{"no":"02","title":"Capacity of a pathogen","titleCN":"病原的传染力：某株病原能多有效地侵入宿主","definition":"the ability of a particular germ or strain to establish an infection in a new host","definitionCN":"某一病原或毒株在新宿主中建立感染的能力","example":"The new strain showed greater infectiousness in close contacts.","exampleCN":"新毒株在密切接触者中表现出更强的传染力。","why":"Strains differ in how easily they enter cells, so the property is attached to the germ as well as to the disease it causes.","whyCN":"不同毒株进入细胞的难易不同，因此这一属性既附着于疾病，也附着于病原本身。"},{"no":"03","title":"A term in outbreak measurement","titleCN":"暴发中的传染性指标：与传播速度相关的量","definition":"the component of transmission that describes how often a contact becomes infected, used in outbreak models","definitionCN":"传播中描述「一次接触有多大比例被感染」的成分，用于暴发模型","example":"Modellers separated infectiousness from contact rates.","exampleCN":"建模者把传染性与接触频率分开处理。","why":"An outbreak depends on both how many people meet and how likely each meeting is to transmit, so the property needs its own name in the equations.","whyCN":"一次暴发同时取决于有多少人相遇、以及每次相遇的传播概率，因此这一属性在方程中需要独立的名称。"},{"no":"04","title":"A person's transmitting state","titleCN":"（某人的）传染性：当下能传出去的程度","definition":"the extent to which a particular patient is currently able to transmit a germ","definitionCN":"某位患者当前能传播病原的程度","example":"Her infectiousness dropped once she started treatment.","exampleCN":"开始治疗后她的传染性下降了。","why":"Treatment and time change the amount of germ a person releases, so the quality becomes a personal, changing state rather than a fixed label.","whyCN":"治疗与时间会改变一个人释放的病原量，因此这种性质成了个人的、变化的状态，而不是固定标签。"},{"no":"05","title":"Infectiousness of laughter","titleCN":"笑声的感染力：让人不由自主跟着笑","definition":"the quality of a laugh that makes other people laugh too","definitionCN":"一种笑声让他人也跟着笑的性质","example":"The infectiousness of a baby's laugh needs no explanation.","exampleCN":"婴儿笑声的感染力无需解释。","why":"The metaphor is exact: a sound passes to others without any physical carrier, so the same suffix that marks a disease marks a laugh.","whyCN":"这个比喻是精确的：声音没有任何实体载体就传给了他人，因此标记疾病的同一个后缀也用来标记笑声。"},{"no":"06","title":"Infectiousness of a mood","titleCN":"情绪的感染力：氛围在人群中蔓延","definition":"the tendency of a mood, such as calm or panic, to spread through a group","definitionCN":"平静或恐慌等情绪在群体中扩散的倾向","example":"The infectiousness of panic emptied the platform in seconds.","exampleCN":"恐慌的感染力在几秒内清空了站台。","why":"Emotions are copied through attention and mimicry, and the word describes how strongly one person's state pulls others into the same state.","whyCN":"情绪通过注意与模仿被复制，这个词描述一个人的状态有多强地把他人拉入同一状态。"},{"no":"07","title":"Infectiousness of an idea","titleCN":"观念或谣言的感染力：被复述与扩散的程度","definition":"the tendency of an idea, rumour or habit to be repeated and carried to new people","definitionCN":"观念、谣言或习惯被复述并带到新人那里的倾向","example":"The rumour's infectiousness came from how easy it was to repeat.","exampleCN":"这条谣言的感染力来自它太容易复述。","why":"Cultural transmission also needs carriers, and the medical vocabulary gives a ready way to say that some ideas spread more readily than others.","whyCN":"文化传播同样需要载体，医学术语提供了一种现成说法：有些观念就是比别人更容易扩散。"},{"no":"08","title":"Measured in the laboratory","titleCN":"实验室测得的感染力：样本实际引发感染的能力","definition":"the measured ability of a sample or preparation to start an infection under controlled conditions","definitionCN":"样本或制品在受控条件下实际引发感染的能力","example":"Tests showed low infectiousness in the stored samples.","exampleCN":"检测显示储存样本的感染力很低。","why":"Regulators and researchers need a number rather than a warning, so the abstract noun became a laboratory quantity, distinct from the mere presence of genetic material.","whyCN":"监管者与研究者要的是数字而不是警告，于是这个抽象名词成了实验室的量，与「仅仅存在遗传物质」区别开来。"}],"etymology":{"intro":{"en":"Infectiousness is infectious plus -ness, a suffix that turns an adjective into the name of a quality. The word is a transparent modern formation, not an inherited Latin noun.","cn":"infectiousness 是 infectious 加 -ness，后者的作用是把形容词变成性质名词。这是透明的现代构词，而非继承来的拉丁名词。"},"items":[{"era":"LATIN INFECTIO","en":"The base is infectio 'a staining, a contamination', from inficere 'to put in, to taint'.","cn":"词基是 infectio「染色、污染」，来自 inficere「放入、染污」。"},{"era":"ENGLISH INFECTIOUS","en":"English infectious appears in the sixteenth century; once the adjective existed, the quality noun could be formed at any time.","cn":"英语 infectious 出现于 16 世纪；形容词一旦存在，性质名词随时可以构成。"},{"era":"SUFFIX -NESS","en":"The Old English suffix -nes formed abstract nouns from adjectives long before French suffixes entered the language; it remains the most productive way to name a quality.","cn":"古英语后缀 -nes 早在法语后缀进入英语之前就能从形容词构成抽象名词；至今仍是最能产的性质名词构成方式。"},{"era":"EPIDEMIOLOGY","en":"In the twentieth century the noun became a technical quantity in epidemiology, separated from contact rate and used in models of outbreak spread.","cn":"20 世纪这个名词成为流行病学中的技术量，与接触率分开，用于暴发传播模型。"},{"era":"SOCIAL USE","en":"Modern English also uses it for laughter, moods and ideas, where the metaphor of contagion is felt but no germ is involved.","cn":"现代英语也用它指笑声、情绪与观念，此时传染的比喻仍可感，但不涉及任何病原。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertainty: the exact first English date of infectiousness is not firmly fixed; the form is so regular that it may have been coined independently several times, so no single coiner can be named.","cn":"来源不确定（仅首见年代存疑）：infectiousness 的英语确切首见年代无定论；这个词构形太规则，可能被多次独立造出，因此无法指认单一首创者。"}]},"similar":{"note":{"en":"The first group holds the adjective and its close derivations; the second holds technical and everyday nouns that measure or name the same property.","cn":"第一组是形容词及其紧邻派生词；第二组是测量或命名同一性质的技术与日常名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"infectious","ipa":"/ɪnˈfekʃəs/","tag":"the adjective","definition":"Able to be passed on; the noun adds -ness to name that ability as a quantity or quality.","definitionCN":"能够被传播；名词加 -ness 把这能力命名为量或性质。"},{"word":"infection","ipa":"/ɪnˈfekʃn/","tag":"the event, not the quality","definition":"The invasion or the disease; it does not measure how easily the disease spreads.","definitionCN":"指侵入或疾病；它不衡量该病多容易传播。"},{"word":"infectivity","ipa":"/ˌɪnfekˈtɪvəti/","tag":"technical near-doublet","definition":"The ability of a germ to enter and infect a host, often used for the agent rather than for a person.","definitionCN":"病原进入并感染宿主的能力，常用于病原而非人。"},{"word":"virulence","ipa":"/ˈvɪrələns/","tag":"harm, not spread","definition":"The degree of damage a germ causes; a highly virulent germ can be less infectious, and the two are measured separately.","definitionCN":"病原造成损害的程度；高毒力病原可能传染性较低，两者分别测量。"}]},{"heading":"NEAR MEANING","entries":[{"word":"transmissibility","ipa":"/trænzˌmɪsəˈbɪləti/","tag":"neutral technical term","definition":"The capacity to be transmitted, used in modelling and regulation; it overlaps almost fully with infectiousness.","definitionCN":"被传播的能力，用于建模与法规；与 infectiousness 几乎完全重叠。"},{"word":"contagiousness","ipa":"/kənˈteɪdʒəsnəs/","tag":"contact spread","definition":"The quality of spreading by contact; narrower than infectiousness, which includes airborne and vector spread.","definitionCN":"经接触传播的性质；比 infectiousness 窄，后者包括空气与媒介传播。"},{"word":"communicability","ipa":"/kəˌmjuːnɪkəˈbɪləti/","tag":"public health register","definition":"The quality of being passable between people, used in official disease classification.","definitionCN":"可在人际间传递的性质，用于官方疾病分类。"},{"word":"catchiness","ipa":"/ˈkætʃinəs/","tag":"informal and cultural","definition":"The quality of being easy to catch or to remember, used of tunes and slogans rather than of diseases.","definitionCN":"容易染上或记住的性质，多用于曲调与口号，而非疾病。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"infectious + -ness: the suffix simply names the quality the adjective describes.","cn":"infectious + -ness：后缀只是把形容词所描述的性质命名出来。"},{"en":"The chain runs infect, infection, infectious, infectiousness; each step adds one grammatical layer.","cn":"链条是 infect、infection、infectious、infectiousness；每一步加一层语法。"},{"en":"Epidemiology separates infectiousness from contact rate; spread needs both.","cn":"流行病学把传染性与接触率分开；传播需要两者同时成立。"},{"en":"Fixed phrases: high infectiousness, peak infectiousness, reduce infectiousness.","cn":"固定搭配：高传染性、传染性高峰、降低传染性。"},{"en":"Do not confuse infectiousness with virulence: one is spread, the other is harm.","cn":"不要把 infectiousness（传染性）与 virulence（毒力）混同：一个是传播，一个是伤害。"}],"abstract":[{"en":"Picture a dial that measures how far one cough can reach.","cn":"想象一个刻度盘，测量一声咳嗽能传多远。"},{"en":"Picture a tune so easy that strangers hum it without being asked.","cn":"想象一支曲子太容易上口，陌生人不用邀请就哼起来。"},{"en":"Picture a rumour gaining speed each time it is repeated.","cn":"想象一条谣言每被复述一次就加速一分。"}]},"examples":[{"en":"Vaccines lower both the chance and the infectiousness of infection.","cn":"疫苗既降低感染概率，也降低感染的传染性。"},{"en":"The team compared the infectiousness of two variants.","cn":"团队比较了两种变异株的传染性。"},{"en":"The infectiousness of her optimism changed the office mood.","cn":"她乐观情绪的感染力改变了办公室的气氛。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「infectious 传染的 + ness 性质」——能被传出去的性质 → infectiousness 传染性","word":"infectiousness"},"root":"拉丁 inficere「染污」→ infectio「感染」→ 英语 infectious（16 世纪）+ -ness → infectiousness。","sensesIntro":{"en":"Eight senses follow one measurable quality: how readily a disease spreads, how well a strain enters hosts, its role in outbreak models, a patient's current state, the pull of laughter and of moods, the spread of ideas, and the number measured in a lab.","cn":"八个义项沿一个可测的性质展开：疾病多容易传播、毒株多能进入宿主、它在暴发模型中的角色、患者当下的状态、笑声与情绪的吸引力、观念的扩散，以及实验室测得的数值。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dial that shows how far and how fast something passes from person to person.","cn":"核心意象：一个刻度盘，显示某物在人与人之间传得多远、多快。"},"chain":["DISEASE SPREADS","STRAIN ENTERS HOSTS","OUTBREAK NUMBER","PATIENT'S STATE","LAUGHTER SPREADS","IDEA SPREADS"],"branches":[{"senses":"S1 · S2","en":"THE DISEASE AND THE GERM: how transmissible a disease is, and how well a strain establishes itself.","cn":"疾病与病原：疾病多易传播，毒株多能立足。"},{"senses":"S3","en":"THE MODEL: the property becomes one term in an outbreak equation.","cn":"模型：这一性质成为暴发方程中的一项。"},{"senses":"S4","en":"THE PATIENT: a personal state that treatment and time can change.","cn":"患者：一个会随治疗与时间改变的个人状态。"},{"senses":"S5 · S6","en":"SOCIAL CONTAGION: laughter and moods pass without any germ.","cn":"社会传染：笑声与情绪在没有任何病原时传播。"},{"senses":"S7 · S8","en":"IDEAS AND THE LAB: rumours spread by repetition, samples are measured by assay.","cn":"观念与实验室：谣言靠复述扩散，样本靠检测计量。"}]},"affixes":{"intro":{"en":"Infectiousness is three layers: the Latin base infect-, the adjective suffix -ous, and the Old English noun suffix -ness.","cn":"infectiousness 有三层：拉丁词基 infect-、形容词后缀 -ous、古英语名词后缀 -ness。"},"latinIntro":{"en":"The Latin base inficere 'to taint' supplies infect, infection and infectious; -ness is native English and simply names the quality.","cn":"拉丁词基 inficere「染污」提供 infect、infection、infectious；-ness 是英语本族后缀，只负责命名性质。"},"items":[{"word":"infectiousness","structure":"infectious + -ness (quality)","meaning":"the quality of being able to spread","meaningCN":"能传播的性质","example":"Infectiousness differs between strains.","exampleCN":"不同毒株的传染性不同。"},{"word":"infectious","structure":"infectio + -osus (full of)","meaning":"able to be passed on","meaningCN":"能被传播的","example":"The disease is infectious before symptoms appear.","exampleCN":"该病在症状出现前就有传染性。"},{"word":"infect","structure":"in- + facere (verb)","meaning":"to transmit a germ","meaningCN":"传播病原","example":"The germ infects the lining of the gut.","exampleCN":"该病原感染肠道内壁。"},{"word":"infection","structure":"inficere + -tio (action noun)","meaning":"invasion by a germ","meaningCN":"病原侵入","example":"The infection was treated early.","exampleCN":"感染得到了早期治疗。"},{"word":"infectiously","structure":"infectious + -ly (adverb)","meaning":"in a way that spreads","meaningCN":"以有感染力的方式","example":"He grinned infectiously.","exampleCN":"他笑得很有感染力。"},{"word":"infectivity","structure":"infective + -ity (quality)","meaning":"the power to enter a host","meaningCN":"进入宿主的能力","example":"Infectivity was measured in cell culture.","exampleCN":"感染力在细胞培养中测定。"},{"word":"noninfectious","structure":"non- (not) + infectious","meaning":"not transmissible","meaningCN":"不可传播的","example":"The condition is noninfectious.","exampleCN":"这种情况不传染。"},{"word":"disinfect","structure":"dis- (away) + infect","meaning":"to kill or remove germs","meaningCN":"杀灭或去除病原","example":"Disinfect the instruments before use.","exampleCN":"使用前给器械消毒。"}],"latinEntries":[{"word":"inficere","structure":"in- + facere (verb, third conjugation)","meaning":"to stain, to taint","meaningCN":"染色；污染"},{"word":"infectio","structure":"inficere + -tio (f., third declension)","meaning":"a staining; infection","meaningCN":"染色；感染"},{"word":"infectiosus","structure":"infectio + -osus (adjective)","meaning":"contagious","meaningCN":"有传染性的"}]}},{"word":"pathogen","ipa_uk":"/ˈpæθədʒən/","ipa_us":"/ˈpæθədʒən/","definition_zh":"病原体；病原微生物（引起疾病的生物）","definition_en":"a bacterium, virus, fungus or other organism that causes disease in a host","core_image":"一个微生物钻进宿主组织，宿主的细胞开始受损","scene":"A pathogen can enter the body through a cut in the skin.","sceneCN":"这里 pathogen 指「病原体」（第 1 个义项：能引起疾病的微生物或其他生物）；句意：病原体可以通过皮肤上的伤口进入身体。图中可辨识物件：皮肤破口、微生物、宿主细胞、侵入箭头。","pos":[{"tag":"n.","zh":"病原体；病原微生物（细菌、病毒、真菌、朊病毒等引起疾病者）"}],"collocations":[{"phrase":"bacterial pathogen","zh":"细菌病原体"},{"phrase":"viral pathogen","zh":"病毒病原体"},{"phrase":"plant pathogen","zh":"植物病原体"},{"phrase":"opportunistic pathogen","zh":"机会性病原体"},{"phrase":"pathogen load","zh":"病原负荷"},{"phrase":"emerging pathogen","zh":"新发病原体"}],"forms":[{"label":"复数","form":"pathogens"},{"label":"形容词","form":"pathogenic（致病的；病原的）"},{"label":"名词（致病性）","form":"pathogenicity（致病性）"},{"label":"名词（病理学）","form":"pathology（病理学；病变）"},{"label":"形容词（病原的）","form":"pathogenous（致病的，罕用）"}],"derivatives":[{"word":"pathogenic","pos":"adj.","zh":"致病的；病原的"},{"word":"pathogenicity","pos":"n.","zh":"致病性"},{"word":"pathology","pos":"n.","zh":"病理学；病变"},{"word":"pathogenesis","pos":"n.","zh":"发病机制"},{"word":"pathogenomics","pos":"n.","zh":"病原基因组学"}],"senses":[{"no":"01","title":"Disease-causing microbe","titleCN":"病原体：引起疾病的微生物","definition":"a microorganism, such as a bacterium or a virus, that causes disease when it enters or colonises a host","definitionCN":"进入或定植宿主后引起疾病的微生物，如细菌或病毒","example":"A pathogen can enter the body through a cut in the skin.","exampleCN":"病原体可以通过皮肤上的伤口进入身体。","why":"Greek pathos 'suffering' plus -gen 'producing' names the germ by its result: the thing that produces suffering.","whyCN":"希腊 pathos「痛苦」加 -gen「产生」按结果给微生物命名：制造痛苦的东西。"},{"no":"02","title":"Any biological agent","titleCN":"广义病原：病毒、真菌、朊病毒等一切致病生物因子","definition":"any biological agent that causes disease, including viruses, fungi, protozoa, helminths and prions, not only bacteria","definitionCN":"任何引起疾病的生物因子，包括病毒、真菌、原虫、蠕虫与朊病毒，而不只是细菌","example":"Fungi and prions are pathogens too, although neither is a bacterium.","exampleCN":"真菌与朊病毒也是病原体，尽管两者都不是细菌。","why":"The word names a role rather than a taxonomic class, so anything that reliably causes disease in a host can fill that role.","whyCN":"这个词命名的是一个角色而非分类类群，因此任何能稳定引起宿主疾病的东西都能承担这一角色。"},{"no":"03","title":"Opportunistic pathogen","titleCN":"机会性病原：通常不致病的条件致病微生物","definition":"a germ that normally causes no harm but becomes pathogenic when the host's defences are weakened","definitionCN":"通常不造成伤害、但在宿主防御减弱时转为致病的微生物","example":"The fungus is an opportunistic pathogen in patients with low immunity.","exampleCN":"这种真菌在免疫力低下的患者中是机会性病原。","why":"Pathogenicity depends on the host as much as the germ, so a harmless resident can be reclassified when the body's guard drops.","whyCN":"致病性既取决于病原也取决于宿主，因此无害的常驻菌在身体防线下降时可被重新归类。"},{"no":"04","title":"Plant pathogen","titleCN":"植物病原体：引起作物病害的生物","definition":"an organism that causes disease in plants, such as a fungus, bacterium or virus affecting crops","definitionCN":"引起植物疾病的生物，如影响作物的真菌、细菌或病毒","example":"A soil-borne pathogen wiped out half the wheat field.","exampleCN":"一种土传病原毁掉了半片麦田。","why":"Agriculture faces the same triangle of host, germ and environment, so the medical word was applied to crops without change.","whyCN":"农业面对同样的宿主、病原与环境三角，因此医学用词原封不动地用到了作物上。"},{"no":"05","title":"Foodborne pathogen","titleCN":"食源性病原：随食物进入人体的致病微生物","definition":"a germ carried by food or water that causes illness after being swallowed","definitionCN":"由食物或水携带、被吞下后引起疾病的微生物","example":"Inspectors test for foodborne pathogens such as Salmonella.","exampleCN":"检查员检测沙门氏菌等食源性病原。","why":"The route of entry defines a public health category, so the general word is used with a modifier for the food route.","whyCN":"进入途径界定了公共卫生类别，因此这个总称与修饰语连用，指经食物进入的那一类。"},{"no":"06","title":"Biothreat agent","titleCN":"生物威胁病原：被管控的高危病原","definition":"a pathogen dangerous enough to be regulated, listed or secured as a biological threat","definitionCN":"危险到需要被管控、列入名录或加以保安的病原体","example":"The laboratory is licensed to work with select-agent pathogens.","exampleCN":"该实验室获准研究特定管制病原。","why":"Security and law needed a neutral word that covers germs and toxins without promising that they are weapons, and pathogen supplied it.","whyCN":"安全与法律需要一个中性词来涵盖病原与毒素，又不直接宣称它们是武器，pathogen 正好补上。"},{"no":"07","title":"Pathogen load","titleCN":"病原负荷：体内病原的数量或密度","definition":"the amount or density of a pathogen present in a host, tissues or an environment","definitionCN":"宿主、组织或环境中存在的病原数量或密度","example":"High pathogen load predicts a worse outcome in sepsis.","exampleCN":"病原负荷高预示脓毒症的预后更差。","why":"Disease severity often tracks how much germ is present, so 'load' turns the countable organism into a measurable burden.","whyCN":"病情严重程度常随病原量变化，因此「负荷」这一说法把可数的微生物变成一个可测量的负担。"},{"no":"08","title":"Emerging pathogen","titleCN":"新发病原：新出现或重新流行的病原","definition":"a pathogen that has recently appeared in a population, changed its host range or rapidly increased its spread","definitionCN":"近期在人群中出现的病原，或已改变宿主范围、迅速扩大传播的病原","example":"Surveillance exists to catch an emerging pathogen early.","exampleCN":"监测系统的存在就是为了及早发现新发病原。","why":"The word is a role, and roles can be newly acquired: a germ harmless in one species can become a pathogen when it crosses into another.","whyCN":"这个词是一个角色，而角色可以被新获得：在一个物种中无害的微生物，跨入另一物种后便能成为病原体。"}],"etymology":{"intro":{"en":"Pathogen joins Greek pathos 'suffering, disease' to -gen 'producing'. It is a nineteenth-century scientific coinage, made when specific germs were being linked to specific diseases.","cn":"pathogen 把希腊 pathos「痛苦、疾病」接到 -gen「产生」上。它是 19 世纪的科学新造词，诞生于「特定微生物对应特定疾病」的研究时期。"},"items":[{"era":"GREEK PATHOS","en":"Pathos meant what is suffered: experience, emotion, and in medical writing disease or suffering. It is the root of pathology, sympathy and pathetic.","cn":"pathos 指所承受之事：经验、情感，在医学文献中指疾病或痛苦。它是 pathology、sympathy、pathetic 的词根。"},{"era":"GREEK -GENES","en":"The suffix -genes meant 'born of, produced by'; medical Latin shortened it to -gen, so a pathogen is literally a 'suffering-producer'.","cn":"后缀 -genes 意为「由…所生、由…产生」；医学拉丁缩为 -gen，因此 pathogen 字面即「痛苦制造者」。"},{"era":"GERM THEORY","en":"In the 1870s and 1880s Koch and Pasteur showed that particular microbes cause particular diseases; researchers then needed a general noun for the causal organism.","cn":"1870 至 1880 年代，科赫与巴斯德证明特定微生物引起特定疾病；研究者随后需要一个通称来指致病生物。"},{"era":"THE COINAGE","en":"The compound pathogen is recorded in the late nineteenth century, usually dated to the 1880s; it was built on the existing Greek elements rather than inherited from Latin.","cn":"复合词 pathogen 记录于 19 世纪后期，通常定在 1880 年代；它用现成的希腊成分构成，并非从拉丁语继承。"},{"era":"MODERN RANGE","en":"Twentieth-century science extended it beyond bacteria to viruses, fungi, protozoa and prions, and to plant and environmental contexts.","cn":"20 世纪科学把它从细菌扩展到病毒、真菌、原虫与朊病毒，并延伸到植物与环境语境。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertainty: the exact first date and first author of pathogen are not firmly established; the 1880s attribution is an approximation based on the growth of germ theory.","cn":"来源不确定（仅首见年代与首创者存疑）：pathogen 的确切首见年代与首位使用者都无定论；1880 年代之说只是依据病菌学说发展的约数。"}]},"similar":{"note":{"en":"The first group holds words built from the same Greek pieces or differing by one suffix; the second holds biological and clinical terms that are often used where pathogen appears.","cn":"第一组是用同样的希腊部件构成、或只差一个后缀的词；第二组是常与 pathogen 同处一句的生物学与临床术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"pathogenic","ipa":"/ˌpæθəˈdʒenɪk/","tag":"adjective","definition":"Meaning 'disease-causing'; it describes a germ, while pathogen names the germ itself.","definitionCN":"意为「致病的」；它形容病原，pathogen 则命名病原本身。"},{"word":"pathology","ipa":"/pəˈθɒlədʒi/","tag":"the study, not the germ","definition":"The study of disease and its effects on tissues; it shares the pathos root but names a discipline.","definitionCN":"研究疾病及其对组织影响的学科；共享 pathos 词根，但命名的是一门学问。"},{"word":"antigen","ipa":"/ˈæntɪdʒən/","tag":"a target, not a germ","definition":"A substance the immune system recognises; a pathogen carries antigens but an antigen need not be alive.","definitionCN":"免疫系统识别的物质；病原携带抗原，但抗原不必是活物。"},{"word":"pathogen vs. parasite","ipa":"/ˈpærəsaɪt/","tag":"different criterion","definition":"A parasite lives at another organism's expense; only some parasites cause disease, and only those are pathogens.","definitionCN":"寄生物以另一生物为代价生存；只有部分寄生物引起疾病，也只有那些才是病原体。"}]},{"heading":"NEAR MEANING","entries":[{"word":"germ","ipa":"/dʒɜːm/","tag":"everyday word","definition":"A informal term for a microbe that causes disease; pathogen is the technical equivalent.","definitionCN":"口语中指标病原微生物的词；pathogen 是技术对应词。"},{"word":"microbe","ipa":"/ˈmaɪkrəʊb/","tag":"neutral, not necessarily harmful","definition":"Any microscopic organism; most microbes are harmless, so microbe is broader than pathogen.","definitionCN":"任何微小生物；多数微生物无害，因此 microbe 比 pathogen 宽。"},{"word":"vector","ipa":"/ˈvektə/","tag":"the carrier, not the cause","definition":"An organism such as a mosquito that carries a pathogen from one host to another.","definitionCN":"把病原从一个宿主带到另一个宿主的生物，如蚊子。"},{"word":"virulence","ipa":"/ˈvɪrələns/","tag":"the degree of harm","definition":"The measure of how much damage a pathogen causes; being a pathogen is the role, virulence is the strength.","definitionCN":"病原造成损害程度的量；作为病原体是一种角色，毒力是强度。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"patho- 'disease' + -gen 'producing' = 'disease-producer'.","cn":"patho-「疾病」+ -gen「产生」=「疾病制造者」。"},{"en":"The family runs pathogen, pathogenic, pathogenicity, pathogenesis, pathology.","cn":"同族词包括 pathogen、pathogenic、pathogenicity、pathogenesis、pathology。"},{"en":"Fixed phrases name the host: plant pathogen, foodborne pathogen, emerging pathogen.","cn":"固定搭配命名宿主：植物病原、食源性病原、新发病原。"},{"en":"A pathogen is defined by the disease it causes, not by its species.","cn":"病原体按它引起的疾病定义，而不是按物种定义。"},{"en":"Do not confuse pathogen with antigen: the germ versus the molecule the immune system sees.","cn":"不要把 pathogen 与 antigen 混同：一个是病原，一个是免疫系统所见的分子。"}],"abstract":[{"en":"Picture a tiny visitor that is defined entirely by the trouble it leaves behind.","cn":"想象一位极小的访客，它的身份完全由留下的麻烦来定义。"},{"en":"Picture a key that opens a door only in a weakened house.","cn":"想象一把钥匙，只在虚弱的房子里才打得开门。"},{"en":"Picture a harmless passenger that changes role when it crosses a border.","cn":"想象一个无害的乘客，一旦越过边界就换了角色。"}]},"examples":[{"en":"The pathogen is spread by droplets from the nose and throat.","cn":"该病原通过鼻咽飞沫传播。"},{"en":"Researchers sequenced the pathogen to track its origin.","cn":"研究者对病原测序以追踪其来源。"},{"en":"Some pathogens survive for days on dry surfaces.","cn":"有些病原能在干燥表面存活数天。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「patho 病 + gen 产生」——产生疾病的东西 → pathogen 病原体","word":"pathogen"},"root":"希腊 pathos「痛苦；疾病」+ 希腊 -genes「产生」→ 英语 pathogen（19 世纪后期，1880 年代前后）。","sensesIntro":{"en":"Eight senses follow one role: the disease-causing microbe, the wider class of biological agents, the germ that waits for weakness, the crop-destroying and food-carried forms, the regulated threat, the measured load, and the germ that has newly acquired the role.","cn":"八个义项沿一个角色展开：致病的微生物、更宽的生物因子类别、等待宿主虚弱的病原、毁坏作物与随食物进入的类型、被管控的威胁、被计量的负荷，以及新近获得该角色的病原。"},"semanticMap":{"core":{"en":"CORE IMAGE: a microbe entering a host and leaving damage behind.","cn":"核心意象：一个微生物进入宿主，留下损害。"},"chain":["CAUSES DISEASE","ANY BIOLOGICAL AGENT","WAITS FOR WEAKNESS","ATTACKS PLANTS","ENTERS BY FOOD","NEWLY EMERGING"],"branches":[{"senses":"S1 · S2","en":"THE ROLE: the basic germ, then the full range of biological agents.","cn":"角色：基本微生物，然后是全部生物因子范围。"},{"senses":"S3","en":"DEPENDENCE ON THE HOST: a resident becomes a pathogen when defences fail.","cn":"依赖宿主：常驻者只在防线崩溃时成为病原。"},{"senses":"S4 · S5","en":"OTHER BODIES, OTHER ROUTES: crops and food carry the same kind of threat.","cn":"其他身体、其他途径：作物与食物携带同一类威胁。"},{"senses":"S6","en":"SECURITY: danger becomes a legal category and a select list.","cn":"安全：危险变成法律类别与管制名录。"},{"senses":"S7 · S8","en":"MEASURE AND CHANGE: load counts the burden, emergence marks a new role.","cn":"量与变：负荷计量负担，新发表明角色更新。"}]},"affixes":{"intro":{"en":"Pathogen is patho- 'disease' plus -gen 'producing'; the family replaces -gen with -genic, -genicity and -genesis.","cn":"pathogen 是 patho-「疾病」加 -gen「产生」；词族把 -gen 换成 -genic、-genicity、-genesis。"},"latinIntro":{"en":"Both elements are Greek: pathos and -genes. Latin supplies only the scientific ending conventions, not the root, so the compound is Greek throughout.","cn":"两个部件都来自希腊语：pathos 与 -genes。拉丁语只提供科学词尾的书写惯例，不提供词根，因此整词属希腊来源。"},"items":[{"word":"pathogen","structure":"patho- (disease) + -gen (producing)","meaning":"a disease-producing organism","meaningCN":"产生疾病的生物","example":"The pathogen was isolated from the blood.","exampleCN":"病原从血液中分离出来。"},{"word":"pathogens","structure":"pathogen + -s (plural)","meaning":"the class, in plural","meaningCN":"病原体（复数）","example":"Many pathogens share the same entry route.","exampleCN":"许多病原共享同一进入途径。"},{"word":"pathogenic","structure":"patho- + -genic (producing)","meaning":"disease-causing","meaningCN":"致病的","example":"Only a few strains are pathogenic.","exampleCN":"只有少数毒株是致病的。"},{"word":"pathogenicity","structure":"pathogenic + -ity (quality)","meaning":"the power to cause disease","meaningCN":"致病能力","example":"Pathogenicity varies with the host.","exampleCN":"致病性随宿主而变。"},{"word":"pathogenesis","structure":"patho- + -genesis (origin, development)","meaning":"the development of a disease","meaningCN":"疾病的发生发展过程","example":"The pathogenesis begins at the gut wall.","exampleCN":"发病过程始于肠壁。"},{"word":"pathology","structure":"patho- + -logia (study)","meaning":"the study of disease","meaningCN":"研究疾病的学科","example":"Pathology confirmed the tissue damage.","exampleCN":"病理学证实了组织损伤。"},{"word":"pathogenomics","structure":"pathogen + -omics (whole-set study)","meaning":"genomics applied to pathogens","meaningCN":"应用于病原的基因组学","example":"Pathogenomics tracks new variants.","exampleCN":"病原基因组学追踪新变异。"},{"word":"phytopathogen","structure":"phyto- (plant) + pathogen","meaning":"a plant pathogen","meaningCN":"植物病原","example":"The phytopathogen spreads through soil.","exampleCN":"该植物病原通过土壤传播。"}],"latinEntries":[{"word":"pathos","structure":"Greek pathos, patheos (neuter, third declension)","meaning":"suffering, disease, feeling","meaningCN":"痛苦；疾病；情感（希腊语，非拉丁语）"},{"word":"gignesthai","structure":"Greek gignesthai (verb)","meaning":"to be born, to arise","meaningCN":"出生；产生（希腊语，-genes 的动词来源）"},{"word":"genesis","structure":"Greek genesis (f., third declension)","meaning":"origin, birth, generation","meaningCN":"起源；诞生；生成（希腊语）"}]}},{"word":"pathogenic","ipa_uk":"/ˌpæθəˈdʒenɪk/","ipa_us":"/ˌpæθəˈdʒenɪk/","definition_zh":"致病的；病原的；引起病变的","definition_en":"able to cause disease, or relating to the causing of disease","core_image":"一个微生物贴在细胞上，细胞开始变形并死亡","scene":"The laboratory handles pathogenic bacteria under strict biosafety rules.","sceneCN":"这里 pathogenic 指「致病的」（第 1 个义项：能够引起疾病的）；句意：该实验室在严格的生物安全规定下处理致病细菌。图中可辨识物件：生物安全柜、培养皿、警示标志、防护装备。","pos":[{"tag":"adj.","zh":"致病的；病原的；（遗传变异）致病的；引起病变的"}],"collocations":[{"phrase":"pathogenic bacteria","zh":"致病细菌"},{"phrase":"pathogenic organism","zh":"致病生物"},{"phrase":"pathogenic variant","zh":"致病变异"},{"phrase":"pathogenic mechanism","zh":"致病机制"},{"phrase":"pathogenic mutation","zh":"致病突变"},{"phrase":"highly pathogenic","zh":"高致病性的"}],"forms":[{"label":"名词（病原体）","form":"pathogen（病原体）"},{"label":"名词（致病性）","form":"pathogenicity（致病性）"},{"label":"副词","form":"pathogenically（致病地，罕用）"},{"label":"比较级","form":"more pathogenic（较少用）"},{"label":"最高级","form":"most pathogenic（较少用）"},{"label":"反义形容词","form":"nonpathogenic（非致病的）"}],"derivatives":[{"word":"pathogen","pos":"n.","zh":"病原体"},{"word":"pathogenicity","pos":"n.","zh":"致病性"},{"word":"nonpathogenic","pos":"adj.","zh":"非致病的"},{"word":"pathogenesis","pos":"n.","zh":"发病机制"},{"word":"pathogenic","pos":"adj.","zh":"致病的（本词）"}],"senses":[{"no":"01","title":"Causing disease","titleCN":"致病的：能够引起疾病的","definition":"able to cause disease in a host organism","definitionCN":"能够在宿主生物中引起疾病","example":"The laboratory handles pathogenic bacteria under strict biosafety rules.","exampleCN":"该实验室在严格的生物安全规定下处理致病细菌。","why":"The adjective adds -ic 'relating to' to pathogen, so it says of a germ exactly what the noun says of it: it produces disease.","whyCN":"这个形容词在 pathogen 后加 -ic「与…有关」，因此它对病原所说的，正是名词本身的意思：它制造疾病。"},{"no":"02","title":"Virulent in practice","titleCN":"有致病力的：实际能造成感染的菌株","definition":"describing a strain that not only belongs to a harmful species but is actually able to establish infection","definitionCN":"描述不仅属于有害物种、实际也能建立感染的菌株","example":"The species is common, but only some isolates are pathogenic.","exampleCN":"这个物种很常见，但只有部分分离株有致病力。","why":"Species and strain are different levels, and a harmless member of a harmful species can lack the genes that make the difference.","whyCN":"物种与菌株是两个层级，有害物种中的无害成员可能恰好缺少造成差别的那部分基因。"},{"no":"03","title":"Pathogenic variant","titleCN":"致病变异：遗传学中引起疾病的基因改变","definition":"describing a gene variant or mutation that is known to cause or raise the risk of a disease","definitionCN":"描述已知会引起疾病或提高患病风险的基因变异","example":"She carries a pathogenic variant in a DNA repair gene.","exampleCN":"她携带一个 DNA 修复基因的致病变异。","why":"Clinical genetics borrowed the germ word because the logic is identical: a small change in a sequence produces a disease, with no organism involved.","whyCN":"临床遗传学借用了病原的词，因为逻辑完全相同：序列中的一个小改变产生疾病，并不涉及任何生物体。"},{"no":"04","title":"Pathogenic mechanism","titleCN":"致病机制：疾病如何在体内形成","definition":"relating to the steps by which a germ or a variant damages the body, as in pathogenic mechanism","definitionCN":"与病原或变异损害身体的步骤有关，如致病机制","example":"The study described the pathogenic mechanism of the toxin.","exampleCN":"该研究描述了这种毒素的致病机制。","why":"Once a germ is labelled pathogenic, research must explain how the harm is done, and the adjective attaches to the process as well as to the agent.","whyCN":"一旦某微生物被标为致病，研究就必须解释损害如何发生，于是这个形容词既附着于病原，也附着于过程。"},{"no":"05","title":"Pathogenic to plants","titleCN":"对植物致病的：引起作物病害的","definition":"describing a fungus, bacterium or virus that causes disease in plants","definitionCN":"描述引起植物病害的真菌、细菌或病毒","example":"The fungus is pathogenic to wheat but harmless to people.","exampleCN":"这种真菌对小麦致病，但对人无害。","why":"Pathogenicity is always relative to a host, so the same adjective needs a 'to' phrase to say which body it can damage.","whyCN":"致病性总是相对于宿主而言，因此同一个形容词需要接 to 短语来说明它能损害哪种身体。"},{"no":"06","title":"Crossing species","titleCN":"跨物种致病的：能越过宿主界限","definition":"describing a germ able to jump from one species to another and remain pathogenic in the new host","definitionCN":"描述能从一物种跳到另一物种、并在新宿主中仍能致病的病原","example":"A virus pathogenic in birds became pathogenic in humans.","exampleCN":"一种对鸟类致病的病毒变成了对人类致病的病毒。","why":"Host range is a property that can change by mutation, so the adjective marks a status that is not fixed for the life of the germ.","whyCN":"宿主范围是可由突变改变的性质，因此这个形容词标记的是一种并非终身固定的状态。"},{"no":"07","title":"Pathogenic antibody","titleCN":"致病性抗体：自身抗体造成组织损伤","definition":"describing an antibody that causes disease by attacking the body's own tissue","definitionCN":"描述通过攻击自身组织而造成疾病的抗体","example":"The pathogenic antibody targets the kidney filter.","exampleCN":"这种致病性抗体以肾脏滤过结构为靶。","why":"The word can describe the body's own molecules when they act like a germ, which shows how completely the root has become a general label for harm.","whyCN":"当身体自身的分子表现得像病原时，这个词也能描述它们，可见这个词根已完全变成「造成伤害」的通用标签。"},{"no":"08","title":"Biosafety classification","titleCN":"生物安全分级中的「致病」：按风险等级处理","definition":"in laboratory rules, describing organisms handled at a higher biosafety level because they can cause disease","definitionCN":"在实验室规章中，描述因能引起疾病而须在更高生物安全级别下处理的生物","example":"Pathogenic organisms are kept in a level-three facility.","exampleCN":"致病生物被保存在三级生物安全设施中。","why":"Regulation must sort agents by risk rather than by species, so the adjective became a formal category on laboratory doors.","whyCN":"规章必须按风险而非物种来分类病原，因此这个形容词成了实验室门上的正式类别。"}],"etymology":{"intro":{"en":"Pathogenic is patho- 'disease' plus -genic 'producing', the adjective twin of pathogen. The ending -genic is the same one found in genetic, photogenic and carcinogenic.","cn":"pathogenic 是 patho-「疾病」加 -genic「产生」，是 pathogen 的形容词孪生形式。词尾 -genic 与 genetic、photogenic、carcinogenic 中的相同。"},"items":[{"era":"GREEK PATHOS","en":"Pathos meant suffering or disease, and supplied the first element of pathology and pathogen alike.","cn":"pathos 意为痛苦或疾病，为 pathology 与 pathogen 提供第一个部件。"},{"era":"GREEK -GENES","en":"The element -genes 'born of, producing' became -genic in adjectives, so pathogenic means 'disease-producing' in form as well as in sense.","cn":"成分 -genes「由…所生、产生」在形容词中作 -genic，因此 pathogenic 在形式和意义上都是「产生疾病」。"},{"era":"NINETEENTH CENTURY","en":"The adjective appears with the noun in the late nineteenth century, when specific germs were being classified by whether they could reproduce disease in a healthy animal.","cn":"这个形容词与名词同在 19 世纪后期出现，当时人们正按「能否在健康动物中复制疾病」来分类微生物。"},{"era":"KOCH'S POSTULATES","en":"The standard for calling a germ pathogenic became experimental: isolate it, grow it, give it to a healthy host, and recover it again.","cn":"把某微生物称为致病的标准变成了实验性的：分离、培养、接种给健康宿主，再重新分离到它。"},{"era":"GENETICS","en":"In the twentieth century the word moved into genetics, where a pathogenic variant is a DNA change that causes disease without any germ at all.","cn":"20 世纪这个词进入遗传学，其中致病变异指完全无需病原、仅由 DNA 改变引起的疾病。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertainty: the exact first English date of pathogenic is not firmly fixed, and the priority between pathogen and pathogenic as first coinages is not established.","cn":"来源不确定（仅首见年代存疑）：pathogenic 的英语确切首见年代无定论，pathogen 与 pathogenic 孰先出现亦无定说。"}]},"similar":{"note":{"en":"The first group holds the noun, the abstract noun and look-alikes; the second holds adjectives that describe harm, spread or the absence of harm.","cn":"第一组是名词、抽象名词与形近词；第二组是描述危害、传播或无害的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"pathogen","ipa":"/ˈpæθədʒən/","tag":"the noun","definition":"The germ itself; pathogenic is the adjective that says it can cause disease.","definitionCN":"指病原本身；pathogenic 是说明它能致病的形容词。"},{"word":"pathogenicity","ipa":"/ˌpæθədʒəˈnɪsəti/","tag":"the abstract noun","definition":"The degree to which a germ can cause disease, a quantity compared between strains.","definitionCN":"病原引起疾病的程度，是菌株之间可比较的量。"},{"word":"pathologic","ipa":"/ˌpæθəˈlɒdʒɪk/","tag":"of pathology","definition":"Meaning 'relating to pathology or to disease as seen in tissue', not 'able to cause disease'.","definitionCN":"意为「病理学的、组织病变的」，而非「能引起疾病的」。"},{"word":"carcinogenic","ipa":"/ˌkɑːsɪnəˈdʒenɪk/","tag":"same -genic pattern","definition":"Cancer-producing; the suffix is identical, only the first element differs.","definitionCN":"致癌的；后缀完全相同，只是第一个部件不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"virulent","ipa":"/ˈvɪrələnt/","tag":"strong, not merely capable","definition":"Describes a germ that causes severe disease; pathogenic says it can cause disease, virulent says it does so powerfully.","definitionCN":"描述引起严重疾病的病原；pathogenic 说「能致病」，virulent 说「致病力强」。"},{"word":"infectious","ipa":"/ɪnˈfekʃəs/","tag":"spread, not harm","definition":"Able to pass between hosts; a germ can be infectious without being highly pathogenic.","definitionCN":"能在宿主间传播；病原可以传染性强而致病性不强。"},{"word":"harmful","ipa":"/ˈhɑːmfl/","tag":"general word","definition":"Causing damage of any kind; it is the everyday equivalent, while pathogenic is technical and host-specific.","definitionCN":"造成任何伤害；它是日常对应词，pathogenic 则技术化且针对特定宿主。"},{"word":"nonpathogenic","ipa":"/ˌnɒnpæθəˈdʒenɪk/","tag":"the negative","definition":"Not able to cause disease, used of harmless strains and of organisms studied safely.","definitionCN":"不能致病的，用于无害菌株与可安全研究的生物。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"patho- 'disease' + -genic 'producing' = 'disease-producing', the exact meaning.","cn":"patho-「疾病」+ -genic「产生」=「产生疾病」，正是其义。"},{"en":"The pair is fixed: pathogen is the germ, pathogenic is its property.","cn":"这一对是固定的：pathogen 是病原，pathogenic 是它的属性。"},{"en":"The family runs pathogen, pathogenic, pathogenicity, pathogenesis, nonpathogenic.","cn":"同族词包括 pathogen、pathogenic、pathogenicity、pathogenesis、nonpathogenic。"},{"en":"Pathogenicity is always relative: pathogenic to wheat, pathogenic to humans.","cn":"致病性总是相对的：对小麦致病、对人致病。"},{"en":"Same -genic suffix as carcinogenic; only the first element changes the target.","cn":"与 carcinogenic 共享 -genic 后缀；只有第一个部件改变目标。"}],"abstract":[{"en":"Picture a key that fits only one kind of lock, and the lock is a living body.","cn":"想象一把钥匙只配一种锁，而那把锁是一个活体。"},{"en":"Picture a harmless neighbour who turns dangerous only when the fence falls.","cn":"想象一位无害的邻居，只在篱笆倒下时才变得危险。"},{"en":"Picture a single letter in a recipe that ruins the whole dish.","cn":"想象食谱里一个字母写错，整道菜就毁了。"}]},"examples":[{"en":"Only the pathogenic form of the fungus damages the lung.","cn":"只有这种真菌的致病形态会损伤肺。"},{"en":"The pathogenic variant was found in three family members.","cn":"这个致病变异在三位家庭成员中被发现。"},{"en":"Handlers wear gloves when working with pathogenic organisms.","cn":"处理致病生物时操作人员要戴手套。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「patho 病 + genic 产生的」——能产生疾病的 → pathogenic 致病的","word":"pathogenic"},"root":"希腊 pathos「疾病」+ 希腊 -genes「产生」（形容词作 -genic）→ 英语 pathogenic（19 世纪后期）。","sensesIntro":{"en":"Eight senses follow one capacity: causing disease at all, actually doing it in a strain, a DNA variant that does it alone, the mechanism, the plant host, the cross-species jump, an antibody that turns on the body, and the biosafety category.","cn":"八个义项沿同一种能力展开：能致病、某菌株确实致病、单独致病的 DNA 变异、致病机制、植物宿主、跨物种跳跃、转而攻击自身的抗体，以及生物安全分类。"},"semanticMap":{"core":{"en":"CORE IMAGE: a germ attaching to a cell and damaging it.","cn":"核心意象：病原附着到细胞上并造成损害。"},"chain":["ABLE TO CAUSE DISEASE","ACTUALLY VIRULENT","GENETIC VARIANT","MECHANISM OF HARM","PLANT HOST","BIOSAFETY CLASS"],"branches":[{"senses":"S1 · S2","en":"CAPACITY AND PRACTICE: the general ability, then the strain that really has it.","cn":"能力与实践：一般能力，然后是确实具备该能力的菌株。"},{"senses":"S3 · S4","en":"WITHOUT A GERM: a DNA change can be pathogenic, and the steps of harm have their own name.","cn":"无需病原：DNA 改变也能致病，损害的步骤也有自己的名称。"},{"senses":"S5 · S6","en":"HOSTS: pathogenicity is always relative to a plant, an animal or a new species.","cn":"宿主：致病性总是相对于某种植物、动物或新物种。"},{"senses":"S7","en":"TURNED INWARD: the body's own antibody can act like a pathogen.","cn":"转向内部：身体自己的抗体也能像病原一样行动。"},{"senses":"S8","en":"THE LAB DOOR: risk levels turn the adjective into a rule.","cn":"实验室门上的标签：风险级别把形容词变成一条规定。"}]},"affixes":{"intro":{"en":"Pathogenic is patho- plus -genic, and the same suffix appears in carcinogenic and photogenic; the noun is pathogen, the abstract noun pathogenicity.","cn":"pathogenic 是 patho- 加 -genic，同一后缀见于 carcinogenic、photogenic；名词是 pathogen，抽象名词是 pathogenicity。"},"latinIntro":{"en":"Both parts are Greek; Latin contributes only the adjective ending convention. The related Greek noun genesis supplies pathogenesis.","cn":"两部分都是希腊语；拉丁语只贡献形容词词尾的书写惯例。相关希腊名词 genesis 提供 pathogenesis。"},"items":[{"word":"pathogenic","structure":"patho- (disease) + -genic (producing)","meaning":"disease-producing","meaningCN":"产生疾病的","example":"The strain proved pathogenic in mice.","exampleCN":"该菌株在小鼠中被证明是致病的。"},{"word":"pathogen","structure":"patho- + -gen (producer)","meaning":"a disease-producing organism","meaningCN":"产生疾病的生物","example":"The pathogen was identified as a fungus.","exampleCN":"该病原被鉴定为真菌。"},{"word":"pathogenicity","structure":"pathogenic + -ity (quality)","meaning":"the power to cause disease","meaningCN":"致病能力","example":"Pathogenicity is tested in animals.","exampleCN":"致病性在动物中检测。"},{"word":"nonpathogenic","structure":"non- (not) + pathogenic","meaning":"unable to cause disease","meaningCN":"不能致病的","example":"A nonpathogenic strain was used as a control.","exampleCN":"使用非致病菌株作为对照。"},{"word":"pathogenesis","structure":"patho- + -genesis (development)","meaning":"the development of disease","meaningCN":"疾病的发生发展","example":"The pathogenesis starts in the lymph node.","exampleCN":"发病过程始于淋巴结。"},{"word":"phytopathogenic","structure":"phyto- (plant) + pathogenic","meaning":"pathogenic to plants","meaningCN":"对植物致病的","example":"Phytopathogenic fungi reduce yields.","exampleCN":"植物病原真菌降低产量。"},{"word":"enteropathogenic","structure":"entero- (intestine) + pathogenic","meaning":"pathogenic in the gut","meaningCN":"在肠道中致病的","example":"Enteropathogenic strains cause diarrhoea.","exampleCN":"肠道致病菌株引起腹泻。"},{"word":"pathogenically","structure":"pathogenic + -ly (adverb)","meaning":"in a disease-causing way","meaningCN":"以致病的方式","example":"The isolate behaved pathogenically in tissue.","exampleCN":"该分离株在组织中表现出致病行为。"}],"latinEntries":[{"word":"pathos","structure":"Greek pathos, patheos (neuter, third declension)","meaning":"suffering, disease","meaningCN":"痛苦；疾病（希腊语）"},{"word":"genesis","structure":"Greek genesis (f., third declension)","meaning":"origin, generation","meaningCN":"起源；生成（希腊语）"},{"word":"genos","structure":"Greek genos (neuter, third declension)","meaning":"kind, birth, race","meaningCN":"种类；出生；族类（希腊语）"}]}},{"word":"bacteria","ipa_uk":"/bækˈtɪəriə/","ipa_us":"/bækˈtɪriə/","definition_zh":"细菌（bacterium 的复数）；细菌界；细菌（作为一大类微生物）","definition_en":"the plural of bacterium, naming single-celled organisms without a nucleus, many of which live in soil, water, food and bodies","core_image":"显微镜下密密麻麻的微小杆状、球状细胞，没有细胞核","scene":"Bacteria in the gut help break down food that the body cannot digest alone.","sceneCN":"这里 bacteria 指「细菌」（第 2 个义项：生活在肠道等特定环境中的细菌群）；句意：肠道里的细菌帮助分解身体无法独自消化的食物。图中可辨识物件：显微镜视野、杆状与球状菌体、肠道内壁、食物颗粒。","pos":[{"tag":"n.","zh":"细菌（bacterium 的复数形式，常作复数名词使用）"}],"collocations":[{"phrase":"gut bacteria","zh":"肠道细菌"},{"phrase":"pathogenic bacteria","zh":"致病细菌"},{"phrase":"beneficial bacteria","zh":"有益细菌"},{"phrase":"soil bacteria","zh":"土壤细菌"},{"phrase":"antibiotic-resistant bacteria","zh":"耐抗生素细菌"},{"phrase":"bacteria and viruses","zh":"细菌与病毒"}],"forms":[{"label":"单数","form":"bacterium（细菌，单数）"},{"label":"复数（本词）","form":"bacteria（细菌，复数）"},{"label":"形容词","form":"bacterial（细菌的）"},{"label":"名词（细菌学）","form":"bacteriology（细菌学）"},{"label":"名词（细菌学家）","form":"bacteriologist（细菌学家）"},{"label":"复合词","form":"bactericide（杀菌剂）"}],"derivatives":[{"word":"bacterium","pos":"n.","zh":"细菌（单数）"},{"word":"bacterial","pos":"adj.","zh":"细菌的；细菌性的"},{"word":"bacteriology","pos":"n.","zh":"细菌学"},{"word":"bacteriologist","pos":"n.","zh":"细菌学家"},{"word":"bactericide","pos":"n.","zh":"杀菌剂"}],"senses":[{"no":"01","title":"Plural of bacterium","titleCN":"细菌：bacterium 的复数，单细胞原核生物","definition":"the plural of bacterium: single-celled organisms that have no nucleus and reproduce by dividing","definitionCN":"bacterium 的复数：没有细胞核、靠分裂繁殖的单细胞生物","example":"Bacteria are far older than animals and live almost everywhere.","exampleCN":"细菌比动物古老得多，几乎无处不在。","why":"The word is a Latin plural, so it is grammatically plural: bacteria are, not bacteria is. The singular bacterium survives in scientific writing.","whyCN":"这个词是拉丁复数，因此语法上是复数：说 bacteria are，而不是 bacteria is。单数 bacterium 仍存活于科学写作中。"},{"no":"02","title":"Gut bacteria","titleCN":"肠道细菌：定居在消化道中的菌群","definition":"the community of bacteria that lives in the intestine and helps digest food, make vitamins and train the immune system","definitionCN":"生活在肠道、帮助消化、合成维生素并训练免疫系统的细菌群","example":"Bacteria in the gut help break down food that the body cannot digest alone.","exampleCN":"肠道里的细菌帮助分解身体无法独自消化的食物。","why":"The word is often used of a community rather than of individual cells, because what matters in a body is the population and what it does together.","whyCN":"这个词常指一个群落而非单个细胞，因为在身体里真正要紧的是这个群体及它们共同做的事。"},{"no":"03","title":"Pathogenic bacteria","titleCN":"致病细菌：引起感染的那一部分","definition":"those bacteria able to invade tissue and cause disease, as opposed to the harmless majority","definitionCN":"能侵入组织并引起疾病的细菌，与无害的大多数相对","example":"Only a small fraction of bacteria cause disease in humans.","exampleCN":"只有一小部分细菌会使人类致病。","why":"Public anxiety treats all bacteria as germs, but the technical use keeps the distinction, and the modifier pathogenic marks the exception.","whyCN":"公众的焦虑把一切细菌都当成病原，但技术用法保留区分，并用 pathogenic 这一修饰语标出例外。"},{"no":"04","title":"Beneficial bacteria","titleCN":"有益细菌：用于发酵、益生菌与生物防治","definition":"bacteria used for their helpful effects, in food cultures, probiotics or biological control","definitionCN":"因其有益作用而被使用的细菌，如食品发酵菌、益生菌或生物防治菌","example":"Beneficial bacteria turn milk into yoghurt overnight.","exampleCN":"有益细菌在一夜之间把牛奶变成酸奶。","why":"Fermentation is ancient practice, and modern language describes it with the same noun, showing that the category is neutral and only the modifier judges it.","whyCN":"发酵是古老实践，现代语言用同一个名词描述它，说明这个类别本身是中性的，只是修饰语在作判断。"},{"no":"05","title":"Soil bacteria","titleCN":"土壤细菌：参与分解与养分循环","definition":"bacteria living in soil that break down organic matter and recycle nitrogen and other nutrients","definitionCN":"生活在土壤中、分解有机物并循环氮等养分的细菌","example":"Soil bacteria release nitrogen that plants can use.","exampleCN":"土壤细菌释放出植物可利用的氮。","why":"The same organisms that decay leaves also feed crops, so ecology uses the word for the whole functional group rather than for a species.","whyCN":"分解落叶的正是为作物提供养分的那批生物，因此生态学用这个词指整个功能群，而非某个物种。"},{"no":"06","title":"Bacteria in food","titleCN":"食品中的细菌：发酵菌与腐败菌","definition":"bacteria present in food, whether useful cultures that preserve or flavour it or spoilage organisms that ruin it","definitionCN":"食品中的细菌，既包括保存或增味的发酵菌，也包括使食物变质的腐败菌","example":"The cheese depends on bacteria that ripen it from the inside.","exampleCN":"这种奶酪依赖从内部使其熟成的细菌。","why":"Food science needs one word for both the culture and the contaminant, and the outcome, not the organism, decides which label is used.","whyCN":"食品科学需要一个词同时涵盖发酵菌与污染物，而决定用哪个标签的是结果，而非生物本身。"},{"no":"07","title":"Laboratory model","titleCN":"实验模型细菌：研究遗传与代谢的工具","definition":"bacteria used as model organisms in research, because they grow fast and are easy to manipulate genetically","definitionCN":"因生长快、易于遗传操作而在研究中被用作模式生物的细菌","example":"Bacteria such as E. coli are the workhorses of molecular biology.","exampleCN":"大肠杆菌这类细菌是分子生物学的主力。","why":"A short generation time turns a cell into an experimental tool, and the plural noun names the whole set of standard organisms.","whyCN":"很短的世代时间把细胞变成实验工具，复数名词便指整套标准模式生物。"},{"no":"08","title":"The taxonomic group","titleCN":"细菌界：分类学上的一个域或界","definition":"in taxonomy, the large group Bacteria, one of the highest divisions of life, distinct from archaea and eukaryotes","definitionCN":"分类学中的细菌大群，是生命最高层级划分之一，与古菌和真核生物并列","example":"Bacteria form one of the three domains of life.","exampleCN":"细菌构成生命的三大域之一。","why":"When the word is capitalised and used as a taxon, it stops meaning 'some germs' and starts naming an entire branch of the tree of life.","whyCN":"当这个词首字母大写并作为分类单元使用时，它不再指「某些病菌」，而是命名生命之树的一整支。"}],"etymology":{"intro":{"en":"Bacteria is the plural of Latin bacterium, a modern scientific Latin word from Greek baktērion 'small staff', because the first ones seen were rod-shaped. It has been treated as a plural noun in English since the nineteenth century.","cn":"bacteria 是拉丁 bacterium 的复数，后者是现代科学拉丁词，来自希腊 baktērion「小棒」，因为最早被看见的细菌是杆状的。19 世纪以来英语一直把它当复数名词用。"},"items":[{"era":"GREEK BAKTRON","en":"Baktron meant a stick or staff; the diminutive baktērion meant a small rod, and had nothing to do with disease.","cn":"baktron 指棍棒；小称 baktērion 意为小棒，与疾病毫无关系。"},{"era":"MODERN LATIN","en":"Scientific Latin formed bacterium as a singular noun for a rod-shaped microbe, with the plural bacteria following Latin first-declension neuter patterns.","cn":"科学拉丁语造出 bacterium，作为杆状微生物的单数名词，复数 bacteria 依拉丁第一变格中性名词的模式构成。"},{"era":"EHRENBERG","en":"The German naturalist Christian Gottfried Ehrenberg used Bacterium as a genus name for rod-shaped microbes in the late 1820s, and the term spread through microscopy.","cn":"德国博物学家克里斯蒂安·戈特弗里德·埃伦伯格在 1820 年代后期把 Bacterium 用作杆状微生物的属名，这个词随显微镜研究传播开来。"},{"era":"GERM THEORY","en":"In the later nineteenth century bacteria became the central object of germ theory, and the plural became the ordinary English word for the whole class.","cn":"19 世纪后期细菌成为病菌学说的核心对象，复数形式成为指整类的日常英语词。"},{"era":"GRAM STAIN AND CULTURE","en":"Staining and culture methods made bacteria countable and classifiable, and the word entered medicine, food science and agriculture.","cn":"染色与培养方法使细菌变得可计数、可分类，这个词进入医学、食品科学与农业。"},{"era":"UNCERTAIN DETAIL","en":"Source uncertainty: the exact year of Ehrenberg's genus name is variously given as 1828 or the early 1830s, and the first English use of bacteria as a common noun is not precisely dated.","cn":"来源不确定（仅首见年代存疑）：埃伦伯格属名的确切年份有 1828 年与 1830 年代初两种说法，bacteria 作为普通名词的英语首见年代亦无精确记载。"}]},"similar":{"note":{"en":"The first group holds the singular and the look-alike terms built on the same stem; the second holds the other microbes and the words for what bacteria do.","cn":"第一组是单数形式与同词干的形近词；第二组是其他微生物，以及描述细菌作用的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"bacterium","ipa":"/bækˈtɪəriəm/","tag":"singular","definition":"One bacterial cell; bacteria is its plural, so 'a bacteria' is a mistake in formal writing.","definitionCN":"单个细菌细胞；bacteria 是其复数，因此正式写作中「a bacteria」是错误。"},{"word":"bacterial","ipa":"/bækˈtɪəriəl/","tag":"adjective","definition":"Relating to bacteria, as in bacterial infection; it describes the cause, not the organisms.","definitionCN":"与细菌有关，如细菌感染；它描述病因，而非生物本身。"},{"word":"bacteriology","ipa":"/bækˌtɪəriˈɒlədʒi/","tag":"the discipline","definition":"The study of bacteria; it is a science, while bacteria are its objects.","definitionCN":"研究细菌的学科；它是一门科学，而细菌是它的研究对象。"},{"word":"bactericide","ipa":"/bækˈtɪərɪsaɪd/","tag":"the killer","definition":"A substance that kills bacteria; the -cide element means 'killing'.","definitionCN":"杀灭细菌的物质；-cide 成分意为「杀」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"virus","ipa":"/ˈvaɪrəs/","tag":"not a cell at all","definition":"An infectious agent that reproduces only inside a host cell and has no independent metabolism; much smaller than bacteria.","definitionCN":"只能在宿主细胞内复制、没有独立代谢的感染因子；比细菌小得多。"},{"word":"archaea","ipa":"/ɑːˈkiːə/","tag":"the other prokaryotes","definition":"Single-celled organisms without a nucleus but chemically distinct from bacteria; they often live in extreme environments.","definitionCN":"无细胞核、但生化上与细菌不同的单细胞生物，常生活在极端环境。"},{"word":"microbe","ipa":"/ˈmaɪkrəʊb/","tag":"the umbrella term","definition":"Any microscopic organism, including bacteria, archaea, fungi and protozoa.","definitionCN":"任何微小生物，包括细菌、古菌、真菌与原虫。"},{"word":"probiotic","ipa":"/ˌprəʊbaɪˈɒtɪk/","tag":"a use, not a class","definition":"A preparation of live beneficial bacteria taken for health; it names a product, not the organisms' taxonomy.","definitionCN":"为健康而摄入的活性有益菌制品；它命名产品，而非生物分类。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek baktron 'staff' gives baktērion 'small rod', the shape of the first ones seen.","cn":"希腊 baktron「棍」生 baktērion「小棒」，正是最早被看见的细菌形状。"},{"en":"bacteria is plural: bacteria are, one bacterium; keep the pair straight.","cn":"bacteria 是复数：说 bacteria are、单数用 bacterium；把这一对记清。"},{"en":"The family runs bacterium, bacteria, bacterial, bacteriology, bactericide.","cn":"同族词包括 bacterium、bacteria、bacterial、bacteriology、bactericide。"},{"en":"Fixed phrases name habitats: gut bacteria, soil bacteria, beneficial bacteria.","cn":"固定搭配命名栖息地：肠道细菌、土壤细菌、有益细菌。"},{"en":"Do not treat bacteria and viruses as the same: one is a cell, the other needs a cell.","cn":"不要把细菌与病毒混为一谈：一个是细胞，另一个需要细胞才能复制。"}],"abstract":[{"en":"Picture a field of tiny rods under a lens, none of them with a nucleus.","cn":"想象镜头下的一片小棒，没有一个带细胞核。"},{"en":"Picture a city of invisible workers recycling everything that falls.","cn":"想象一座看不见的工人之城，把落下的东西全部回收。"},{"en":"Picture a single cell splitting into two, then four, within an hour.","cn":"想象一个细胞在一小时内分成两个，再分成四个。"}]},"examples":[{"en":"Antibiotics kill bacteria but have no effect on viruses.","cn":"抗生素杀细菌，但对病毒无效。"},{"en":"Some bacteria can survive boiling and dry heat.","cn":"有些细菌能耐受煮沸与干热。"},{"en":"The number of bacteria in a gram of soil runs into the millions.","cn":"一克土壤中的细菌数量可达数百万。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「bacterium 的单数 → bacteria 复数」——记住 are 配 bacteria，is 配 bacterium → bacteria 细菌","word":"bacteria"},"root":"希腊 baktron「棍棒」→ 小称 baktērion「小棒」→ 科学拉丁 bacterium（单数）→ 英语 bacteria（复数，19 世纪）。","sensesIntro":{"en":"Eight senses follow one class of cells: the grammatical plural, the gut community, the disease-causing minority, the useful cultures, soil recyclers, food organisms, laboratory models, and finally the taxonomic domain.","cn":"八个义项沿同一类细胞展开：语法上的复数、肠道菌群、致病的少数、有用的发酵菌、土壤分解者、食品中的菌、实验室模式生物，最后是分类学上的域。"},"semanticMap":{"core":{"en":"CORE IMAGE: a field of tiny rod-shaped cells with no nucleus, dividing.","cn":"核心意象：一片没有细胞核的微小杆状细胞，正在分裂。"},"chain":["PLURAL CELLS","GUT COMMUNITY","DISEASE-CAUSING MINORITY","USEFUL CULTURES","SOIL RECYCLERS","TAXONOMIC DOMAIN"],"branches":[{"senses":"S1","en":"GRAMMAR: a Latin plural used as a plural English noun.","cn":"语法：作为英语复数名词使用的拉丁复数。"},{"senses":"S2 · S3","en":"INSIDE THE BODY: the community that helps, and the minority that harms.","cn":"身体之内：帮助消化的群落，以及造成伤害的少数。"},{"senses":"S4 · S6","en":"USEFUL WORK: fermentation and probiotics turn the same class into tools and products.","cn":"有益工作：发酵与益生菌把同一类细胞变成工具与产品。"},{"senses":"S5","en":"OUTSIDE: soil bacteria drive the nutrient cycle.","cn":"身体之外：土壤细菌驱动养分循环。"},{"senses":"S7 · S8","en":"MODEL AND TREE: the lab uses a few species, while taxonomy names the whole branch.","cn":"模型与谱系：实验室只用少数物种，分类学则命名整支。"}]},"affixes":{"intro":{"en":"Bacteria is a plural Latin form in -a; the stem bacter- builds bacterial, bacteriology and bactericide, with -ium for the singular.","cn":"bacteria 是以 -a 结尾的拉丁复数；词干 bacter- 造出 bacterial、bacteriology、bactericide，单数则用 -ium。"},"latinIntro":{"en":"Modern Latin bacterium comes from Greek baktērion; the Greek diminutive suffix -ion is the source of the Latin -ium, which then yields the plural -ia and English -a.","cn":"现代拉丁 bacterium 来自希腊 baktērion；希腊小称后缀 -ion 是拉丁 -ium 的来源，后者再产生复数 -ia 与英语 -a。"},"items":[{"word":"bacteria","structure":"bacterium + -a (Latin neuter plural)","meaning":"the class, in plural","meaningCN":"细菌（复数）","example":"Bacteria are classified by shape and staining.","exampleCN":"细菌按形状与染色分类。"},{"word":"bacterium","structure":"Greek baktērion + Latin -ium","meaning":"one bacterial cell","meaningCN":"单个细菌","example":"A single bacterium can start a colony.","exampleCN":"一个细菌就能起始一个菌落。"},{"word":"bacterial","structure":"bacterium + -al (relating to)","meaning":"of or caused by bacteria","meaningCN":"细菌的；由细菌引起的","example":"The infection was bacterial, not viral.","exampleCN":"这是细菌感染，而非病毒感染。"},{"word":"bacteriology","structure":"bacterio- + -logia (study)","meaning":"the study of bacteria","meaningCN":"研究细菌的学科","example":"Bacteriology began with staining methods.","exampleCN":"细菌学始于染色方法。"},{"word":"bacteriologist","structure":"bacteriology + -ist (person)","meaning":"a specialist in bacteria","meaningCN":"细菌学专家","example":"The bacteriologist identified the strain.","exampleCN":"细菌学家鉴定了该菌株。"},{"word":"bactericide","structure":"bacteri- + -cide (killing)","meaning":"a substance that kills bacteria","meaningCN":"杀灭细菌的物质","example":"The soap contains a bactericide.","exampleCN":"这种肥皂含杀菌剂。"},{"word":"bactericidal","structure":"bactericide + -al (adjective)","meaning":"killing bacteria","meaningCN":"杀细菌的","example":"The drug is bactericidal rather than bacteriostatic.","exampleCN":"这种药是杀菌性的，而非抑菌性的。"},{"word":"bacteriophage","structure":"bacterio- + -phage (eater)","meaning":"a virus that infects bacteria","meaningCN":"感染细菌的病毒","example":"Bacteriophages were used before antibiotics.","exampleCN":"噬菌体在抗生素之前就已被使用。"}],"latinEntries":[{"word":"bacterium","structure":"Modern Latin, from Greek baktērion (n., second declension)","meaning":"a rod-shaped microbe","meaningCN":"杆状微生物"},{"word":"bacteria","structure":"plural of bacterium (neuter plural in -a)","meaning":"rod-shaped microbes, plural","meaningCN":"杆状微生物（复数）"},{"word":"bacillum","structure":"bacillum, bacilli (n., diminutive of baculus)","meaning":"a small rod","meaningCN":"小棒（拉丁语，与希腊 baktērion 语义对应的另一词）"}]}}]);
